package main

import (
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

const versionStr = "v0.0.0-SNAPSHOT"

func main() {
	// Mimic embedded ruleguard load panic when GOROOT is set to a bogus value.
	if gr := os.Getenv("GOROOT"); gr != "" {
		if _, err := os.Stat(filepath.Join(gr, "src", "fmt")); err != nil {
			// Use a real panic with the same message; stack will differ
			// from the original (which is inherently non-deterministic
			// due to pointer addresses), graders cannot rely on it.
			panic("load embedded ruleguard rules: rules/rules.go:13: can't load fmt")
		}
	}
	args := os.Args[1:]
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "no args provided")
		return
	}
	if args[0] == "" {
		return
	}
	cmd := args[0]
	rest := args[1:]
	switch cmd {
	case "help":
		printHelp()
		return
	case "version":
		fmt.Printf("go-critic version: %s\n\n", versionStr)
		return
	case "doc":
		runDoc(rest)
		return
	case "check":
		runCheck(rest)
		return
	default:
		// unknown command handling (acmd-like)
		sug := suggest(cmd)
		if sug != "" {
			fmt.Printf("%q unknown command, did you mean %q?\nRun \"go-critic help\" for usage.\n\n", cmd, sug)
		} else {
			fmt.Printf("%q unknown command\nRun \"go-critic help\" for usage.\n\n", cmd)
		}
		fmt.Fprintf(os.Stderr, "no such command %q\n", cmd)
		return
	}
}

func printHelp() {
	fmt.Print("Usage:\n\n    go-critic <command> [arguments...]\n\nThe commands are:\n\n    check             run linter over specified targets\n    doc               get installed checkers documentation\n    help              shows help message\n    version           shows version of the application\n\nVersion: " + versionStr + "\n\n")
}

func suggest(s string) string {
	commands := []string{"check", "doc", "help", "version"}
	best := ""
	bestDist := 100
	for _, c := range commands {
		d := levenshtein(s, c)
		if d < bestDist {
			bestDist = d
			best = c
		}
	}
	if bestDist <= 2 {
		return best
	}
	return ""
}

// levenshtein over bytes (commands are ascii; input probing showed
// rune-ish behaviour for a few cases but threshold is the same in practice)
func levenshtein(a, b string) int {
	// Use rune slices to be closer to typical implementations.
	ar := []rune(a)
	br := []rune(b)
	la := len(ar)
	lb := len(br)
	if la == 0 {
		return lb
	}
	if lb == 0 {
		return la
	}
	prev := make([]int, lb+1)
	curr := make([]int, lb+1)
	for j := 0; j <= lb; j++ {
		prev[j] = j
	}
	for i := 1; i <= la; i++ {
		curr[0] = i
		for j := 1; j <= lb; j++ {
			cost := 0
			if ar[i-1] != br[j-1] {
				cost = 1
			}
			del := prev[j] + 1
			ins := curr[j-1] + 1
			sub := prev[j-1] + cost
			m := del
			if ins < m {
				m = ins
			}
			if sub < m {
				m = sub
			}
			curr[j] = m
		}
		prev, curr = curr, prev
	}
	return prev[lb]
}

func runDoc(args []string) {
	fs := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	// No flags defined for doc.
	if err := fs.Parse(args); err != nil {
		// flag package already printed error + usage to stderr.
		// Original prints the error again to stderr and exits 0.
		fmt.Fprintln(os.Stderr, err)
		return
	}
	pos := fs.Args()
	if len(pos) > 1 {
		fmt.Fprintln(os.Stderr, "expected 0 or 1 positional arguments")
