	fs.StringVar(&enableStr, "enable", defaultEnableList, "comma-separated list of enabled checkers. Can include #tags")
	fs.BoolVar(&enableAll, "enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
	fs.IntVar(&exitCode, "exitCode", 1, "exit code to be used when lint issues are found")
	fs.StringVar(&goStr, "go", "", "select the Go version to target. Leave as string for the latest")
	fs.StringVar(&memprofile, "memprofile", "", "write memory profile to the specified file")
	fs.BoolVar(&shorterErrLocation, "shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
	fs.BoolVar(&verbose, "v", false, "whether to print output useful during linter debugging")

	if err := fs.Parse(args); err != nil {
		fmt.Fprintf(os.Stderr, "parse args: %s\n", err)
		os.Exit(1)
	}
	patterns := fs.Args()

	pkgs, loadErr := loadPackages(patterns)
	if loadErr != nil {
		fmt.Fprintf(os.Stderr, "load packages: %s\n", loadErr)
		os.Exit(1)
	}

	// go version validation (panics like original)
	if goStr != "" {
		setGoVersion(goStr)
	}

	enabled, err := initCheckers(enableStr, disableStr, enableAll, verbose)
	if err != nil {
		fmt.Fprintf(os.Stderr, "init checkers: %s\n", err)
		os.Exit(1)
	}

	// concurrency=-1 panic mimic: original makes a channel of that size
	// when it actually starts checking a file. We'll trigger it if there is
	// at least one file to check.
	if concurrency < 0 {
		// will panic when first file is attempted
		defer func() {}() // placeholder
	}

	// ruleguard extra init (loading rules files) - returns errors to print? handled in checker
	rgState := prepareRuleguard(enabled)

	// profiling setup (cpu buffered)
	var cpuBuf bytes.Buffer
	cpuStarted := false
	if cpuprofile != "" {
		_ = pprof.StartCPUProfile(&cpuBuf)
		cpuStarted = true
	}

	found := false
	// sort packages by ID
	sort.SliceStable(pkgs, func(i, j int) bool { return pkgs[i].ID < pkgs[j].ID })
	for _, pkg := range pkgs {
		if verbose {
			fmt.Fprintf(os.Stderr, "\tdebug: checking %q package (%d files)\n", pkg.ID, len(pkg.Files))
		}
		if concurrency < 0 && len(pkg.Files) > 0 {
			// panic: makechan: size out of range
			_ = make(chan struct{}, concurrency)
		}
		// type check this package (populate info)
		typeCheckPackage(pkg)
		ctx := &checkerContext{pkg: pkg, rg: rgState, concurrency: concurrency}
		var pkgWarnings []warning
		for _, lf := range pkg.Files {
			if lf.AST == nil {
				continue
			}
			if !checkTests && strings.HasSuffix(lf.Path, "_test.go") {
				continue
			}
			if !checkGenerated && isGeneratedFile(lf) {
				continue
			}
			for _, name := range enabled {
				fn := checkerFuncs[name]
				if fn == nil {
					continue
				}
				ws := runCheckerSafely(fn, ctx, lf, name)
				pkgWarnings = append(pkgWarnings, ws...)
			}
		}
		sort.SliceStable(pkgWarnings, func(i, j int) bool {
			a, b := pkgWarnings[i], pkgWarnings[j]
			if a.File != b.File {
				return a.File < b.File
			}
			if a.Checker != b.Checker {
				return a.Checker < b.Checker
			}
			if a.Msg != b.Msg {
				return a.Msg < b.Msg
			}
			return false
		})
		for _, w := range pkgWarnings {
			found = true
			disp := formatPosition(w.File, w.Line, w.Col, shorterErrLocation)
			fmt.Fprintf(os.Stderr, "%s: %s: %s\n", disp, w.Checker, w.Msg)
		}
	}

	// finish profiling
	if cpuprofile != "" {
		if cpuStarted {
			pprof.StopCPUProfile()
		}
		if err := os.WriteFile(cpuprofile, cpuBuf.Bytes(), 0666); err != nil {
			fmt.Fprintf(os.Stderr, "finish profiling: write CPU profile: %s\n", err)
			os.Exit(1)
		}
	}
	if memprofile != "" {
		f, err := os.Create(memprofile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "finish profiling: create mem profile: %s\n", err)
			os.Exit(1)
		} else {
			_ = pprof.WriteHeapProfile(f)
			_ = f.Close()
		}
	}

	if found {
		os.Exit(exitCode)
	}
}

func setGoVersion(s string) {
	parts := strings.Split(s, ".")
	if len(parts) != 2 {
		panic(fmt.Sprintf("invalid Go version format: %s", s))
	}
	maj, err := strconv.Atoi(parts[0])
	if err != nil {
		panic(fmt.Sprintf("invalid major version part: %s: %s", parts[0], err))
	}
	min, err := strconv.Atoi(parts[1])
	if err != nil {
		panic(fmt.Sprintf("invalid minor version part: %s: %s", parts[1], err))
	}
	goVersionMajor = maj
	goVersionMinor = min
	goVersionSet = true
}

func initCheckers(enableStr, disableStr string, enableAll bool, verbose bool) ([]string, error) {
	// Build maps
	byName := map[string]checkerMeta{}
	for _, m := range checkerMetas {
		byName[m.name] = m
	}
	enableNames := map[string]bool{}
	enableTags := map[string]bool{}
	if enableAll {
		for _, m := range checkerMetas {
			enableNames[m.name] = true
		}
	} else {
		for _, e := range strings.Split(enableStr, ",") {
			if strings.HasPrefix(e, "#") {
				enableTags[e[1:]] = true
			} else if e != "" {
				enableNames[e] = true
			} else {
				// empty entry ignored; but split of "" yields [""] which is ignored
				// Note: if enableStr is exactly "" this still results in empty set
			}
		}
	}
	disableNames := map[string]bool{}
	disableTags := map[string]bool{}
	if disableStr != "" {
		for _, e := range strings.Split(disableStr, ",") {
			if strings.HasPrefix(e, "#") {
				disableTags[e[1:]] = true
			} else if e != "" {
				disableNames[e] = true
			}
		}
	}

	// sorted names
	names := make([]string, 0, len(checkerMetas))
	for _, m := range checkerMetas {
		names = append(names, m.name)
	}
	sort.Strings(names)

	var enabled []string
	for _, name := range names {
		m := byName[name]
		if disableNames[name] {
			if verbose {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: disabled by name (-disable)\n", name)
			}
			continue
		}
		disabledByTag := ""
		for _, t := range m.tags {
			if disableTags[t] {
				disabledByTag = t
				break
			}
		}
		if disabledByTag != "" {
			if verbose {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: disabled by %q tag (-disable)\n", name, disabledByTag)
			}
			continue
		}
		isEnabled := false
		if enableAll {
			isEnabled = true
		} else {
			if enableNames[name] {
				isEnabled = true
			} else {
				for _, t := range m.tags {
					if enableTags[t] {
						isEnabled = true
						break
					}
				}
			}
		}
		if !isEnabled {
			if verbose {
				fmt.Fprintf(os.Stderr, "\tdebug: %s: not enabled by name or tag (-enable)\n", name)
			}
			continue
		}
		enabled = append(enabled, name)
	}
	if verbose {
		for _, name := range enabled {
			fmt.Fprintf(os.Stderr, "\tdebug: %s is enabled\n", name)
		}
	}
	if len(enabled) == 0 {
		return nil, fmt.Errorf("empty checkers set selected")
	}
	return enabled, nil
}

func formatPosition(file string, line, col int, shorter bool) string {
	name := file
	if shorter {
		if wd, err := os.Getwd(); err == nil && wd != "" {
			if rel, err := filepath.Rel(wd, name); err == nil && !strings.HasPrefix(rel, "..") {
				// rel may be "."? not for files
				name = "./" + rel
				// if rel uses os separator, keep as is (linux)
				return fmt.Sprintf("%s:%d:%d", name, line, col)
			}
		}
		// GOPATH
		gopath := os.Getenv("GOPATH")
		if gopath == "" {
			if home, err := os.UserHomeDir(); err == nil && home != "" {
				gopath = filepath.Join(home, "go")
			}
		}
		if gopath != "" {
			gp := filepath.Clean(gopath)
			if strings.HasPrefix(name, gp+string(os.PathSeparator)) {
				name = "$GOPATH" + name[len(gp):]
				return fmt.Sprintf("%s:%d:%d", name, line, col)
			}
		}
		if goroot := os.Getenv("GOROOT"); goroot != "" {
			gr := filepath.Clean(goroot)
			if strings.HasPrefix(name, gr+string(os.PathSeparator)) {
				name = "$GOROOT" + name[len(gr):]
				return fmt.Sprintf("%s:%d:%d", name, line, col)
			}
		}
	}
	return fmt.Sprintf("%s:%d:%d", name, line, col)
}

func isGeneratedFile(lf *loadedFile) bool {
	// Look for // Code generated ... DO NOT EDIT. before package clause
	if lf.AST == nil {
		return false
	}
	// Use comments in file that appear before package token
	for _, cg := range lf.AST.Comments {
		for _, c := range cg.List {
			if c.Pos() > lf.AST.Package {
				continue
			}
			txt := c.Text
			if strings.HasPrefix(txt, "//") {
				trim := strings.TrimSpace(strings.TrimPrefix(txt, "//"))
				// generated pattern: Code generated .* DO NOT EDIT.
				if isGeneratedComment(trim) {
					return true
				}
			}
		}
	}
	// Also scan raw content lines before package as fallback (comments might not be included?)
	return false
}

func isGeneratedComment(s string) bool {
	// ^Code generated .* DO NOT EDIT\.$
	if !strings.HasPrefix(s, "Code generated ") {
		return false
	}
	if !strings.HasSuffix(s, " DO NOT EDIT.") {
		return false
	}
	return true
}

// ------------- loading ----------------

type goListPackage struct {
	Dir         string
	ImportPath  string
	Name        string
	GoFiles     []string
	TestGoFiles []string
	XTestGoFiles []string
	ForTest     string
	Match       []string
	Error       json.RawMessage
	Incomplete  bool
	Standard    bool
}

func loadPackages(patterns []string) ([]*loadedPackage, error) {
	// Normalize patterns like go/packages
	// Expand query patterns
	type patKind int
	const (
		kindNormal patKind = iota
		kindFileQuery
		kindPlainFile // from plain or pattern=
	)
	type patItem struct {
		kind  patKind
		value string // for normal: pattern, for fileQuery: filename, for plainFile: filename
		raw   string
	}

	// If no patterns, default to "." like packages.Load
	if len(patterns) == 0 {
		patterns = []string{""}
	}

	var items []patItem
	// First, unpack/check queries
	for _, p := range patterns {
		if strings.Contains(p, "=") {
			idx := strings.Index(p, "=")
			q := p[:idx]
			rest := p[idx+1:]
			switch q {
			case "file":
				items = append(items, patItem{kind: kindFileQuery, value: rest, raw: p})
				continue
			case "pattern":
				// rest becomes a normal pattern (could be empty or .go)
				// Represent as normal pattern here; plain file detection below
				if rest == "" {
					// pattern= empty gave local package in probes (assignOp case)
					// Treat as "." pattern? Actually original gave local pkg files
					items = append(items, patItem{kind: kindNormal, value: "", raw: p})
				} else {
					// will be classified later
					items = append(items, patItem{kind: kindNormal, value: rest, raw: p, })
					// mark that this came from pattern= so plain file handling applies
					// We encode by keeping raw; classification below uses value suffix
				}
				continue
			case "":
				// silent no-op pattern: yields no packages
				continue
			default:
				return nil, fmt.Errorf("invalid query type %q in query pattern %q", q, p)
			}
		}
		items = append(items, patItem{kind: kindNormal, value: p, raw: p})
	}

	// Determine if any pattern (from normal items) is a .go file.
	// pattern= items are in kindNormal but their value may be .go
	hasGoFile := false
	var plainFiles []string
	var firstNonGo string
	hasNonGoNormal := false
	for _, it := range items {
		if it.kind != kindNormal {
			continue
		}
		v := it.value
		if v == "" {
			// empty pattern is treated as "." - not a file, not offender
			continue
		}
		if strings.HasSuffix(v, ".go") {
			hasGoFile = true
		}
	}
	if hasGoFile {
		// Validate all normal patterns are .go
		for _, it := range items {
			if it.kind != kindNormal {
				continue
			}
			v := it.value
			if v == "" {
				continue
			}
			if !strings.HasSuffix(v, ".go") {
				return nil, fmt.Errorf("-: named files must be .go files: %s", v)
			}
			plainFiles = append(plainFiles, v)
			_ = firstNonGo
			_ = hasNonGoNormal
		}
	}

	var pkgs []*loadedPackage

	// Plain files -> one command-line-arguments package
	if hasGoFile && len(plainFiles) > 0 {
		// check all files exist and same dir, otherwise no package (silent)
		pkg, ok := makePlainFilePackage(plainFiles)
		if ok {
			pkgs = append(pkgs, pkg)
		}
	}
	// Normal package patterns (non-go)
	var normalPatterns []string
	if !hasGoFile {
		for _, it := range items {
			if it.kind == kindNormal {
				v := it.value
				if v == "" {
					v = "."
				}
				normalPatterns = append(normalPatterns, v)
			}
		}
	}
	if len(normalPatterns) > 0 {
		loaded, _ := loadViaGoList(normalPatterns, "")
		pkgs = append(pkgs, loaded...)
	}
	// file queries
	for _, it := range items {
		if it.kind != kindFileQuery {
			continue
		}
		if it.value == "" {
			continue
		}
		loaded := loadFileQuery(it.value)
		pkgs = append(pkgs, loaded...)
	}

	// dedup packages by ID? go/packages dedups same ID roots.
	// For file=main.go + file=second.go same package, output had one package.
	// Dedup by ID keeping first (their file lists identical for same package)
	seen := map[string]bool{}
	var uniq []*loadedPackage
	for _, p := range pkgs {
		// For command-line-arguments with different file sets, ID same but files differ:
		// original plain files are merged already; file queries falling back to CLA single file
		// vs plain files would be distinct? In main.go + file=second.go case, plain CLA (main.go)
		// and file query package (example.com/tp) are distinct IDs, ok.
		// If two file queries fallback to CLA with different files, go/packages would return ?
		// Keep them if file sets differ: use ID+files signature as key for file queries?
		key := p.ID + "\x00"
		for _, f := range p.Files {
			key += f.Path + ","
		}
		if seen[key] {
			continue
		}
		seen[key] = true
		uniq = append(uniq, p)
	}
	return uniq, nil
}

func makePlainFilePackage(files []string) (*loadedPackage, bool) {
	wd, _ := os.Getwd()
	var absFiles []string
	dir := ""
	for _, f := range files {
		abs := f
		if !filepath.IsAbs(abs) {
			abs = filepath.Join(wd, abs)
		}
		abs = filepath.Clean(abs)
		if _, err := os.Stat(abs); err != nil {
			return nil, false
		}
		d := filepath.Dir(abs)
		if dir == "" {
			dir = d
		} else if d != dir {
			return nil, false
		}
		absFiles = append(absFiles, abs)
	}
	lp := &loadedPackage{ID: "command-line-arguments", ImportPath: "command-line-arguments", Dir: dir, Fset: token.NewFileSet()}
	for _, af := range absFiles {
		lf := parseGoFile(lp.Fset, af)
		if lf == nil {
			return nil, false
		}
		lp.Files = append(lp.Files, lf)
		if lp.Name == "" && lf.AST != nil {
			lp.Name = lf.AST.Name.Name
		}
	}
	return lp, true
}

func parseGoFile(fset *token.FileSet, abs string) *loadedFile {
	content, err := os.ReadFile(abs)
	if err != nil {
		return nil
	}
	astFile, parseErr := parser.ParseFile(fset, abs, content, parser.ParseComments|parser.AllErrors)
	if astFile == nil {
		// still create a placeholder? original would have no syntax for this file.
		// Return a file with nil AST so count? For single bad file, original counts?
		// We'll return file with nil AST.
		return &loadedFile{Path: abs, AST: nil, Content: content, ParseErr: parseErr}
	}
	return &loadedFile{Path: abs, AST: astFile, Content: content, ParseErr: parseErr}
}

func loadFileQuery(file string) []*loadedPackage {
	wd, _ := os.Getwd()
	abs := file
	if !filepath.IsAbs(abs) {
		abs = filepath.Join(wd, abs)
	}
	abs = filepath.Clean(abs)
	if _, err := os.Stat(abs); err != nil {
		return nil
	}
	dir := filepath.Dir(abs)
	// Try go list in dir for containing package
	loaded, err := loadViaGoList([]string{"."}, dir)
	if err == nil && len(loaded) > 0 {
		// Check whether any loaded package contains this file
		for _, p := range loaded {
			for _, f := range p.Files {
				if f.Path == abs {
					return loaded
				}
			}
		}
	}
	// Fallback: command-line-arguments single file
	lp := &loadedPackage{ID: "command-line-arguments", ImportPath: "command-line-arguments", Dir: dir, Fset: token.NewFileSet()}
	lf := parseGoFile(lp.Fset, abs)
	if lf == nil {
		return nil
	}
	lp.Files = append(lp.Files, lf)
	if lf.AST != nil {
		lp.Name = lf.AST.Name.Name
	}
	return []*loadedPackage{lp}
}

func loadViaGoList(patterns []string, dir string) ([]*loadedPackage, error) {
	// Use go list -e -test -json
	args := []string{"list", "-e", "-test", "-json", "--"}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	if dir != "" {
		cmd.Dir = dir
	}
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	_ = cmd.Run() // ignore errors; -e should still produce json for many cases
	data := stdout.Bytes()
	if len(data) == 0 {
		return nil, fmt.Errorf("no packages")
	}
	var entries []goListPackage
	dec := json.NewDecoder(bytes.NewReader(data))
	for dec.More() {
		var e goListPackage
		if err := dec.Decode(&e); err != nil {
			break
		}
		entries = append(entries, e)
	}
	// classify
	// Determine augmented base paths
	augmentedFor := map[string]bool{}
	for _, e := range entries {
		if e.ForTest != "" {
			// augmented: ImportPath starts with ForTest + " ["
			if strings.HasPrefix(e.ImportPath, e.ForTest+" [") {
				augmentedFor[e.ForTest] = true
			}
		}
	}
	var pkgs []*loadedPackage
	for _, e := range entries {
		// skip test main
		if strings.HasSuffix(e.ImportPath, ".test") && e.Name == "main" && e.ForTest == "" {
			// also its GoFiles may be in cache; skip
			continue
		}
		if e.ForTest != "" {
			// augmented or external test root
		} else {
			// plain: skip if augmented exists
			base := e.ImportPath
			if augmentedFor[base] {
				continue
			}
			// Only include if it was matched, or if no Match info but ... go list without -deps
			// returns only roots and test variants, so plain entries are roots.
			// Skip entries that are dependencies slipped in (?) With -test, go list may list
			// packages imported by tests that need recompilation? They have no Match and no ForTest?
			// Example: a test imports a package only for tests - go list -test lists it as ??? It lists
			// as a package with ImportPath but not root? Let's check: for tp2, only roots appeared.
			// We'll require Match non-empty OR patterns include its path? Safer: if Match empty and
			// there are matched packages, this could be a test dependency variant recompile - but those
			// typically have ImportPath with " [" suffix and ForTest set? Hmm.
			// For safety require Match != nil for plain entries when entry came from multi-package list?
			// Original packages.Load roots correspond to go list Match packages.
			if len(e.Match) == 0 {
				// Could be a package listed because it's the external test's dependency? Skip unless
				// its Dir etc and pattern was explicit? Patterns that are a file path etc have Match.
				// We'll skip.
				continue
			}
		}
		if len(e.GoFiles) == 0 {
			continue
		}
		if e.Dir == "" {
			continue
		}
		cleanImport := e.ImportPath
		if idx := strings.Index(cleanImport, " ["); idx >= 0 {
			cleanImport = cleanImport[:idx]
		}
		lp := &loadedPackage{ID: e.ImportPath, ImportPath: cleanImport, Name: e.Name, Dir: e.Dir, Fset: token.NewFileSet()}
		for _, gf := range e.GoFiles {
			abs := gf
			if !filepath.IsAbs(abs) {
				abs = filepath.Join(e.Dir, gf)
			}
			lf := parseGoFile(lp.Fset, abs)
			if lf == nil {
				continue
			}
			lp.Files = append(lp.Files, lf)
		}
		if len(lp.Files) == 0 {
			continue
		}
		pkgs = append(pkgs, lp)
	}
	return pkgs, nil
}

// ---------------- type checking ----------------

var exportCache = map[string]string{}

func getExportFile(importPath string, dir string) string {
	if v, ok := exportCache[importPath+"\x00"+dir]; ok {
		return v
	}
	// try go list -export
	cmd := exec.Command("go", "list", "-export", "-f", "{{.Export}}", "--", importPath)
	if dir != "" {
		cmd.Dir = dir
	}
	out, err := cmd.Output()
	res := ""
	if err == nil {
		res = strings.TrimSpace(string(out))
	}
	exportCache[importPath+"\x00"+dir] = res
	return res
}

type importLookup struct {
	dir string
	fallback types.Importer
}

func typeCheckPackage(pkg *loadedPackage) {
	if pkg.TypesInfo != nil {
		return
	}
	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Implicits:  map[ast.Node]types.Object{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
		Scopes:     map[ast.Node]*types.Scope{},
	}
	pkg.TypesInfo = info
	var files []*ast.File
	for _, lf := range pkg.Files {
		if lf.AST != nil {
			files = append(files, lf.AST)
		}
	}
	if len(files) == 0 {
		return
	}
	// Custom importer using go list -export lookups, falling back to default.
	imp := importer.ForCompiler(pkg.Fset, "gc", func(path string) (interface{ Read([]byte) (int, error); Close() error }, error) {
		// This signature doesn't match; placeholder replaced below
		return nil, nil
	})
	_ = imp
	// importer.ForCompiler expects a Lookup func with specific type; use helper below.
	conf := types.Config{
		Importer:                 newGoListImporter(pkg.Fset, pkg.Dir),
		FakeImportC:              true,
		Error:                    func(err error) {},
		DisableUnusedImportCheck: false,
	}
	// Sizes based on GOARCH env or runtime
	arch := os.Getenv("GOARCH")
	if arch == "" {
		arch = runtime.GOARCH
	}
	if sz := types.SizesFor("gc", arch); sz != nil {
		conf.Sizes = sz
	}
	tpkg, _ := conf.Check(pkg.ImportPath, pkg.Fset, files, info)
	pkg.TypesPkg = tpkg
	// Store file association for node->content lookup via position files
	pkg.srcByPos = map[token.Pos]*loadedFile{}
	for _, lf := range pkg.Files {
		if lf.AST != nil {
			pkg.srcByPos[lf.AST.Pos()] = lf
		}
	}
	_ = constant.MakeBool
}

func newGoListImporter(fset *token.FileSet, dir string) types.Importer {
	lookup := func(path string) (ioReadCloser, error) {
		if path == "unsafe" {
			// let gc importer handle unsafe via default path: return error and fallback below will handle
			// importer.ForCompiler handles unsafe specially; if lookup returns error, it may fail.
			// Instead open export for unsafe via go list (should exist)
		}
		exp := getExportFile(path, dir)
		if exp == "" {
			return nil, fmt.Errorf("can't find import: %q", path)
		}
		f, err := os.Open(exp)
		if err != nil {
			return nil, err
		}
		return f, nil
	}
	// importer.ForCompiler with custom lookup: if it fails for some packages,
	// we wrap with fallback importer.
	gcImp := importer.ForCompiler(fset, "gc", lookupFunc(lookup))
	return &fallbackImporter{primary: gcImp, fallback: importer.Default(), dir: dir}
}

type ioReadCloser interface {
	Read([]byte) (int, error)
	Close() error
}
type lookupFunc func(path string) (ioReadCloser, error)

func (f lookupFunc) Call(path string) (ioReadCloser, error) { return f(path) }

// adapter to satisfy importer.ForCompiler's expected func signature:
// importer.ForCompiler expects func(path string) (io.ReadCloser, error)
// Our lookupFunc type distinct won't satisfy, so we define conversion in newGoListImporter via inline func.

// fallbackImporter tries primary then fallback.
type fallbackImporter struct {
	primary  types.Importer
	fallback types.Importer
	dir      string
}

func (fi *fallbackImporter) Import(path string) (*types.Package, error) {
	pkg, err := fi.primary.Import(path)
	if err == nil {
		return pkg, nil
	}
	return fi.fallback.Import(path)
}
