{"command":"cat > ctx.go <<'EOF'
package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/printer"
	"go/token"
	"go/types"
	"strconv"
	"strings"
)

type checkerContext struct {
	pkg         *loadedPackage
	checker     string
	rg          *ruleguardState
	concurrency int
}

type checkerFunc func(ctx *checkerContext, lf *loadedFile) []warning

var checkerFuncs = map[string]checkerFunc{}

func register(name string, fn checkerFunc) {
	checkerFuncs[name] = fn
}

func runCheckerSafely(fn checkerFunc, parent *checkerContext, lf *loadedFile, name string) (out []warning) {
	ctx := &checkerContext{pkg: parent.pkg, checker: name, rg: parent.rg, concurrency: parent.concurrency}
	defer func() {
		if r := recover(); r != nil {
			// swallow checker panics to avoid crashing whole run on edge cases
			out = nil
		}
	}()
	return fn(ctx, lf)
}

func (ctx *checkerContext) warn(pos token.Pos, format string, args ...interface{}) warning {
	p := ctx.pkg.Fset.Position(pos)
	return warning{File: p.Filename, Line: p.Line, Col: p.Column, Checker: ctx.checker, Msg: fmt.Sprintf(format, args...)}
}

// nodeText returns exact source slice for node
func (ctx *checkerContext) nodeText(n ast.Node) string {
	if n == nil {
		return ""
	}
	start := ctx.pkg.Fset.Position(n.Pos())
	end := ctx.pkg.Fset.Position(n.End())
	for _, lf := range ctx.pkg.Files {
		if lf.Path == start.Filename && lf.Content != nil {
			// offset: position Offset fields
			s := ctx.pkg.Fset.File(n.Pos())
			if s == nil {
				break
			}
			so := s.Offset(n.Pos())
			eo := s.Offset(n.End())
			if so >= 0 && eo >= so && eo <= len(lf.Content) {
				return string(lf.Content[so:eo])
			}
			_ = end
		}
	}
	// fallback: printer
	var buf bytes.Buffer
	_ = printer.Fprint(&buf, ctx.pkg.Fset, n)
	return buf.String()
}

func (ctx *checkerContext) exprType(e ast.Expr) types.Type {
	if ctx.pkg.TypesInfo == nil {
		return nil
	}
	if t := ctx.pkg.TypesInfo.TypeOf(e); t != nil {
		return t
	}
	return nil
}

func (ctx *checkerContext) isType(e ast.Expr, pred func(types.Type) bool) bool {
	t := ctx.exprType(e)
	if t == nil {
		return false
	}
	return pred(t)
}

// formatNode renders node in normalized Go syntax (as go/printer would)
func (ctx *checkerContext) formatNode(n ast.Node) string {
	var buf bytes.Buffer
	cfg := printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 8}
	if err := cfg.Fprint(&buf, ctx.pkg.Fset, n); err != nil {
		return ctx.nodeText(n)
	}
	return buf.String()
}

func (ctx *checkerContext) formatNodeNoFset(n ast.Node) string {
	// Use format.Node which handles positions somewhat
	var buf bytes.Buffer
	if err := format.Node(&buf, ctx.pkg.Fset, n); err != nil {
		return ctx.formatNode(n)
	}
	return buf.String()
}

// string literal value
func stringLitValue(e ast.Expr) (string, bool) {
	if bl, ok := e.(*ast.BasicLit); ok && bl.Kind == token.STRING {
		v, err := strconv.Unquote(bl.Value)
		if err == nil {
			return v, true
		}
	}
	return "", false
}

func intLitValue(e ast.Expr) (string, bool) {
	if bl, ok := e.(*ast.BasicLit); ok && bl.Kind == token.INT {
		return bl.Value, true
	}
	return "", false
}

// selector call info: for call expr that is pkg.Name(...) or recv.Method(...)
// returns fun expr, sel
func selectorOf(e ast.Expr) (*ast.SelectorExpr, bool) {
	s, ok := e.(*ast.SelectorExpr)
	return s, ok
}

// identifies pkg path/name for a selector call: X must be an Ident that is a package name use
func (ctx *checkerContext) selPkgName(sel *ast.SelectorExpr) string {
	id, ok := sel.X.(*ast.Ident)
	if !ok {
		return ""
	}
	if ctx.pkg.TypesInfo != nil {
		if obj := ctx.pkg.TypesInfo.Uses[id]; obj != nil {
			if pn, ok := obj.(*types.PkgName); ok {
				return pn.Imported().Path()
			}
		}
		// Definitions of imported package name also in Defs? Uses should cover
	}
	// fallback: look at file imports
	// return ident name as package name guess
	return id.Name
}

func pkgPathLast(path string) string {
	if i := strings.LastIndex(path, "/"); i >= 0 {
		return path[i+1:]
	}
	return path
}

// function full name like "strings.Contains" based on type info package path last element
func (ctx *checkerContext) callFuncName(call *ast.CallExpr) string {
	sel, ok := selectorOf(call.Fun)
	if !ok {
		if id, ok := call.Fun.(*ast.Ident); ok {
			return id.Name
		}
		return ctx.nodeText(call.Fun)
	}
	p := ctx.selPkgName(sel)
	if p != "" {
		// if sel.X is not a package but a var, type info will tell: PkgName check above.
		// If X is not package, selPkgName returned ident name as fallback; detect package via Uses
		if id, ok := sel.X.(*ast.Ident); ok {
			if ctx.pkg.TypesInfo != nil {
				if obj := ctx.pkg.TypesInfo.Uses[id]; obj != nil {
					if _, isPkg := obj.(*types.PkgName); isPkg {
