package main

import (
	"go/ast"
	"go/token"
	"strings"
)

// normalized text: printer output removing whitespace distinctions somewhat
func (ctx *checkerContext) normText(n ast.Node) string {
	s := ctx.formatNode(n)
	// printer output already normalized
	return s
}

func (ctx *checkerContext) exprEq(a, b ast.Expr) bool {
	if a == nil || b == nil {
		return false
	}
	// unwrap parens
	a = unparen(a)
	b = unparen(b)
	if ctx.normText(a) == ctx.normText(b) {
		return true
	}
	// fallback textual without spaces
	sa := strings.Map(func(r rune) rune {
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' { return -1 }
		return r
	}, ctx.nodeText(a))
	sb := strings.Map(func(r rune) rune {
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' { return -1 }
		return r
	}, ctx.nodeText(b))
	return sa == sb
}

func unparen(e ast.Expr) ast.Expr {
	for {
		if p, ok := e.(*ast.ParenExpr); ok {
			e = p.X
			continue
		}
		return e
	}
}

func isIdent(e ast.Expr, name string) bool {
	id, ok := unparen(e).(*ast.Ident)
	return ok && id.Name == name
}

func identName(e ast.Expr) (string, bool) {
	id, ok := unparen(e).(*ast.Ident)
	if !ok { return "", false }
	return id.Name, true
}

// isNilIdent etc
func isNilExpr(e ast.Expr) bool { return isIdent(e, "nil") }

func isBoolLit(e ast.Expr, val bool) bool {
	id, ok := unparen(e).(*ast.Ident)
	if !ok { return false }
	if val { return id.Name == "true" }
	return id.Name == "false"
}

func basicLitKind(e ast.Expr) (token.Token, string, bool) {
	bl, ok := unparen(e).(*ast.BasicLit)
	if !ok { return token.ILLEGAL, "", false }
	return bl.Kind, bl.Value, true
}

// statement list containers: collect blocks in file
// returns slices in traversal order

func isGeneratedCommentText(s string) bool { return isGeneratedComment(s) }
EOF
