{"command":"cat > checkers1.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"strconv"
	"strings"
	"unicode"
)

func init() {
	register("appendAssign", checkAppendAssign)
	register("appendCombine", checkAppendCombine)
	register("argOrder", checkArgOrder)
	register("assignOp", checkAssignOp)
	register("badCall", checkBadCall)
	register("badCond", checkBadCond)
	register("captLocal", checkCaptLocal)
	register("caseOrder", checkCaseOrder)
	register("codegenComment", checkCodegenComment)
	register("commentFormatting", checkCommentFormatting)
	register("defaultCaseOrder", checkDefaultCaseOrder)
	register("deprecatedComment", checkDeprecatedComment)
	register("dupArg", checkDupArg)
	register("dupBranchBody", checkDupBranchBody)
	register("dupCase", checkDupCase)
	register("dupSubExpr", checkDupSubExpr)
	register("elseif", checkElseif)
	register("exitAfterDefer", checkExitAfterDefer)
	register("flagDeref", checkFlagDeref)
	register("flagName", checkFlagName)
	register("ifElseChain", checkIfElseChain)
	register("mapKey", checkMapKey)
	register("newDeref", checkNewDeref)
	register("offBy1", checkOffBy1)
	register("regexpMust", checkRegexpMust)
	register("singleCaseSwitch", checkSingleCaseSwitch)
	register("sloppyLen", checkSloppyLen)
	register("sloppyTypeAssert", checkSloppyTypeAssert)
	register("switchTrue", checkSwitchTrue)
	register("typeSwitchVar", checkTypeSwitchVar)
	register("underef", checkUnderef)
	register("unlambda", checkUnlambda)
	register("unslice", checkUnslice)
	register("valSwap", checkValSwap)
	register("wrapperFunc", checkWrapperFunc)
}

// appendAssign
func checkAppendAssign(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok || len(as.Lhs) != 1 || len(as.Rhs) != 1 {
			return true
		}
		call, ok := unparen(as.Rhs[0]).(*ast.CallExpr)
		if !ok {
			return true
		}
		id, ok := unparen(call.Fun).(*ast.Ident)
		if !ok || id.Name != "append" || len(call.Args) < 1 {
			return true
		}
		if !ctx.exprEq(as.Lhs[0], call.Args[0]) {
			out = append(out, ctx.warn(call.Pos(), "append result not assigned to the same slice"))
		}
		return true
	})
	return out
}

// appendCombine
func checkAppendCombine(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// helper to process a statement list
	processList := func(list []ast.Stmt) {
		i := 0
		for i < len(list) {
			// collect chain
			j := i
			var first *ast.AssignStmt
			var firstCall *ast.CallExpr
			count := 0
			var lhs ast.Expr
			for j < len(list) {
				as, ok := list[j].(*ast.AssignStmt)
				if !ok || len(as.Lhs) != 1 || len(as.Rhs) != 1 {
					break
				}
				call, ok := unparen(as.Rhs[0]).(*ast.CallExpr)
				if !ok {
					break
				}
				id, ok := unparen(call.Fun).(*ast.Ident)
				if !ok || id.Name != "append" || len(call.Args) < 1 {
					break
				}
				if count == 0 {
					if !ctx.exprEq(as.Lhs[0], call.Args[0]) {
						break
					}
					first = as
					firstCall = call
					lhs = as.Lhs[0]
				} else {
					if !ctx.exprEq(lhs, as.Lhs[0]) || !ctx.exprEq(lhs, call.Args[0]) {
						break
					}
				}
				count++
				j++
			}
			if count >= 2 {
				out = append(out, ctx.warn(firstCall.Pos(), "can combine chain of %d appends into one", count))
				_ = first
				i = j
			} else {
				i++
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.BlockStmt:
			processList(v.List)
		case *ast.CaseClause:
			processList(v.Body)
		case *ast.CommClause:
			processList(v.Body)
		}
		return true
	})
	return out
}

// argOrder
var argOrderFuncs = map[string]bool{
	"strings.HasPrefix": true, "strings.HasSuffix": true, "strings.TrimPrefix": false, // TrimPrefix excluded? handled below
	"bytes.HasPrefix": true, "bytes.HasSuffix": true,
	"strings.Contains": true, "bytes.Contains": true,
}

func checkArgOrder(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}
		fname := ctx.callFuncName(call)
		switch fname {
		case "strings.HasPrefix", "strings.HasSuffix", "bytes.HasPrefix", "bytes.HasSuffix",
			"strings.Contains", "bytes.Contains", "strings.ContainsRune":
			// first arg literal string, second non-const ?
		default:
			return true
		}
		// conditions: first arg is string literal (or const string?) and second is not literal?
		// Probed: HasPrefix("#", s) flagged, HasPrefix(s,"#") not, HasSuffix(s,"#") not
		// Also need to ensure literal looks like the longer (?) Simplest: first is basic string literal,
		// second is not a basic literal.
		if _, ok1 := stringLitValue(call.Args[0]); !ok1 {
			return true
		}
		if _, ok2 := stringLitValue(call.Args[1]); ok2 {
			return true
		}
		// For HasSuffix, doc example? If first is literal and pattern... Actually HasSuffix(s, suffix): first arg is s.
		// If code writes HasSuffix("#", s) it's reversed.
		// So flag any.
		out = append(out, ctx.warn(call.Args[0].Pos(), "%s and %s arguments order looks reversed", ctx.nodeText(call.Args[0]), ctx.nodeText(call.Args[1])))
		return true
	})
	return out
}

// assignOp
func checkAssignOp(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok || as.Tok != token.ASSIGN || len(as.Lhs) != 1 || len(as.Rhs) != 1 {
			return true
		}
		bin, ok := unparen(as.Rhs[0]).(*ast.BinaryExpr)
		if !ok {
			return true
		}
		// bin.X must equal lhs
		if !ctx.exprEq(as.Lhs[0], bin.X) {
			return true
		}
		op := bin.Op
		var opStr string
		switch op {
		case token.ADD, token.SUB, token.MUL, token.QUO, token.REM, token.AND, token.OR, token.XOR, token.SHL, token.SHR, token.AND_NOT:
			opStr = op.String()
		default:
			return true
		}
		lhsText := ctx.nodeText(as.Lhs[0])
		rhsText := ctx.nodeText(bin.Y)
		origText := ctx.nodeText(as) // AssignStmt node text
		// special case +1 / -1 -> ++ / --
		if (op == token.ADD || op == token.SUB) {
			if v, ok := intLitValue(bin.Y); ok && v == "1" {
				sug := lhsText + "++"
				if op == token.SUB {
					sug = lhsText + "--"
				}
				out = append(out, ctx.warn(as.Pos(), "replace `%s` with `%s`", origText, sug))
				return true
			}
		}
		// origText as stored is statement text; original probe used exact source (no trailing semicolon)
		sug := fmt.Sprintf("%s %s= %s", lhsText, opStr, rhsText)
		out = append(out, ctx.warn(as.Pos(), "replace `%s` with `%s`", origText, sug))
		return true
	})
	return out
}

// badCall
func checkBadCall(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		fname := ctx.callFuncName(call)
		switch fname {
		case "strings.Replace", "bytes.Replace":
			if len(call.Args) == 4 {
				if v, ok := intLitValue(call.Args[3]); ok && v == "0" {
					out = append(out, ctx.warn(call.Pos(), "suspicious arg 0, probably meant -1"))
				}
			}
		case "strings.TrimSpace":
			// not?
		}
		// Additional suspicious calls probed later: will add in refinement
		// fmt Sprint with no args etc?
		return true
	})
	return out
}

// badCond
func checkBadCond(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		// loop condition
		if fs, ok := n.(*ast.ForStmt); ok && fs.Cond != nil {
			// pattern i > n where init i:=0 and post i++
			// simplistic: binary > or >= and init is 0 ?
			if bin, ok := unparen(fs.Cond).(*ast.BinaryExpr); ok && (bin.Op == token.GTR || bin.Op == token.GEQ) {
				// check init assigns 0 to x and post increments x (same ident as bin.X)
				if fs.Init != nil && fs.Post != nil {
					if as, ok := fs.Init.(*ast.AssignStmt); ok && len(as.Rhs) == 1 {
						if v, ok := intLitValue(as.Rhs[0]); ok && v == "0" {
							// post is IncDec ++ on same
							if inc, ok := fs.Post.(*ast.IncDecStmt); ok && inc.Tok == token.INC {
								if ctx.exprEq(bin.X, inc.X) && ctx.exprEq(inc.X, as.Lhs[0]) {
									out = append(out, ctx.warn(bin.Pos(), "`%s` in loop; probably meant `%s`?", ctx.nodeText(bin), ctx.nodeText(bin.X)+" < "+ctx.nodeText(bin.Y)))
								}
							}
						}
					}
				}
			}
		}
		// duplicate equality condition a==b && a==b (only == ? probed)
		if bin, ok := n.(*ast.BinaryExpr); ok && (bin.Op == token.LAND) {
			// check if X and Y are identical equality expressions
			// Avoid double counting nested && chains: only flag topmost? original flagged once for a==b && a==b
			// If parent also is LAND with same? ast.Inspect will also visit sub? sub is X which is not LAND so fine.
			xb, ok1 := unparen(bin.X).(*ast.BinaryExpr)
			yb, ok2 := unparen(bin.Y).(*ast.BinaryExpr)
			if ok1 && ok2 && xb.Op == token.EQL && yb.Op == token.EQL {
				if ctx.exprEq(xb, yb) {
					out = append(out, ctx.warn(bin.Pos(), "`%s` condition is suspicious", ctx.nodeText(bin)))
				}
			}
		}
		return true
	})
	return out
}

// captLocal
func checkCaptLocal(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// paramsOnly default true: only func params/results
	// else also local variables
	checkIdent := func(id *ast.Ident) {
		if id == nil || id.Name == "_" || id.Name == "" {
			return
		}
		// capitalized: first rune uppercase and at least? Also if name is all caps? probe: IN, OUT, ERR flagged. LocalVar?
		// CaptLocal presumably flags names starting with uppercase letter?
		r := []rune(id.Name)[0]
		if unicode.IsUpper(r) {
			// ensure not exported? local scope
			out = append(out, ctx.warn(id.Pos(), "`%s' should not be capitalized", id.Name))
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			if v.Type != nil {
				if v.Type.Params != nil {
					for _, f := range v.Type.Params.List {
						for _, name := range f.Names {
							checkIdent(name)
						}
					}
				}
				if v.Type.Results != nil {
					for _, f := range v.Type.Results.List {
						for _, name := range f.Names {
							checkIdent(name)
						}
					}
				}
			}
			if paramCaptLocalParamsOnly {
				// still need to traverse into body? ast.Inspect will visit FuncType etc again causing duplicates.
				// To avoid duplicate of FuncLit params etc, we handle FuncLit separately and skip FuncType of FuncDecl here?
				// Return true will also visit params as nodes, but we do not flag on generic Ident visit.
				// So fine.
			}
		case *ast.FuncLit:
			if v.Type != nil {
				if v.Type.Params != nil {
					for _, f := range v.Type.Params.List {
						for _, name := range f.Names {
							checkIdent(name)
						}
					}
				}
				if v.Type.Results != nil {
					for _, f := range v.Type.Results.List {
						for _, name := range f.Names {
							checkIdent(name)
						}
					}
				}
			}
		default:
			if !paramCaptLocalParamsOnly {
				// local variable declarations: AssignStmt := , ValueSpec inside funcs, RangeStmt, etc.
				// We'll handle in second pass below to avoid duplicates? Simplify: handle here
				switch s := v.(type) {
				case *ast.AssignStmt:
					if s.Tok == token.DEFINE {
						for _, lhs := range s.Lhs {
							if id, ok := lhs.(*ast.Ident); ok {
								checkIdent(id)
							}
						}
					}
				case *ast.RangeStmt:
					if s.Tok == token.DEFINE {
						if id, ok := s.Key.(*ast.Ident); ok {
							checkIdent(id)
						}
						if id, ok := s.Value.(*ast.Ident); ok {
							checkIdent(id)
						}
					}
				case *ast.ValueSpec:
					// only locals - but ValueSpec at top level also visited; need know if inside func.
					// That determination hard in Inspect; skip ValueSpec here, handle via func bodies below.
					_ = s
				}
			}
		}
		return true
	})
	// TODO: for paramsOnly=false, local ValueSpec inside funcs could be missed; acceptable
	_ = out
	return out
}

// caseOrder
func checkCaseOrder(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ts, ok := n.(*ast.TypeSwitchStmt)
		if !ok {
			return true
		}
		// Find switch body
		var body *ast.BlockStmt
		// TypeSwitchStmt has Body
		body = ts.Body
		if body == nil {
			return true
		}
		// Collect cases in order: each CaseClause List are types
		// For each earlier case type A, later case type B, if B implements(?) / is subtype of A, then B unreachable.
		// Use type info: type of case expr? Cases are type expressions; their types are types.Type from TypesInfo? For type expr, TypeOf returns type?
		// Approach: get types via ctx.exprType for each case type expr, if later type is more specific: check if it implements earlier interface or if earlier is interface and later ...
		// Simplified based on ast types: *ast.BasicLit case in probe: ast.Expr is interface, *ast.BasicLit implements it.
		// Use types: laterType implements earlierType (if earlier is interface), or later is pointer vs earlier...
		type caseInfo struct {
			clause *ast.CaseClause
			expr   ast.Expr
			typ    types.Type
		}
		var cases []caseInfo
		for _, stmt := range body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			for _, e := range cc.List {
				t := ctx.exprType(e)
				cases = append(cases, caseInfo{clause: cc, expr: e, typ: t})
			}
		}
		for j := 0; j < len(cases); j++ {
			for i := 0; i < j; i++ {
				// if cases[j] is subtype of cases[i] and not equal
				if cases[i].typ == nil || cases[j].typ == nil {
					continue
				}
				if types.Identical(cases[i].typ, cases[j].typ) {
					continue
				}
				// if earlier is interface and later implements it
				if types.Implements(cases[j].typ, interfaceOf(cases[i].typ)) {
					// also need ensure earlier is interface type
					if isInterfaceType(cases[i].typ) {
						out = append(out, ctx.warn(cases[j].clause.Pos(), "case %s must go before the %s case", ctx.nodeText(cases[j].expr), ctx.nodeText(cases[i].expr)))
						break // one warning per later case?
					}
				}
			}
		}
		return true
	})
	return out
}

func interfaceOf(t types.Type) *types.Interface {
	if iface, ok := t.Underlying().(*types.Interface); ok {
		return iface
	}
	return nil
}
func isInterfaceType(t types.Type) bool {
	_, ok := t.Underlying().(*types.Interface)
	return ok
}

// codegenComment
func checkCodegenComment(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	for _, cg := range lf.AST.Comments {
		for _, c := range cg.List {
			if c.Pos() > lf.AST.Package {
				return out // only before package? original checks file header comments
			}
			if !strings.HasPrefix(c.Text, "//") {
				continue
			}
			text := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
			low := strings.ToLower(text)
			// malformed if it looks like generated comment but doesn't match
			// Probes: "// This file was automatically generated by foogen" flagged
			// "// Code generated by foo DO NOT EDIT." (without period) ??? probe later
			// heuristic: contains "generated" and not exact match
			if strings.Contains(low, "generated") {
				if !isGeneratedComment(text) {
					out = append(out, ctx.warn(c.Pos(), "comment should match `Code generated .* DO NOT EDIT.` regexp"))
				}
			}
		}
	}
	return out
}

// commentFormatting
func checkCommentFormatting(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	for _, cg := range lf.AST.Comments {
		for _, c := range cg.List {
			txt := c.Text
			if !strings.HasPrefix(txt, "//") {
				continue
			}
			if txt == "//" {
				continue
			}
			rest := txt[2:]
			if rest == "" {
				continue
			}
			// directives: //go:, //line, // +build, //go:build, etc (?) check first char
			if strings.HasPrefix(txt, "//go:") || strings.HasPrefix(txt, "//line") || strings.HasPrefix(txt, "// +build") || strings.HasPrefix(txt, "//go:build") {
				continue
			}
			// if rest starts with space or tab or / (///) or !? probe showed /// and //! not flagged, tab?
			// Original flagged //This and //bad, not /// / //! / //\t
			first := rest[0]
			if first == ' ' || first == '\t' || first == '/' || first == '!' {
				continue
			}
			// Also comments like //- ? Possibly URLs?
			out = append(out, ctx.warn(c.Pos(), "put a space between `//` and comment text"))
		}
	}
	return out
}

// defaultCaseOrder
func checkDefaultCaseOrder(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	checkClauses := func(list []ast.Stmt) {
		// find default index
		for idx, stmt := range list {
			if cc, ok := stmt.(*ast.CaseClause); ok && cc.List == nil {
				if idx != 0 && idx != len(list)-1 {
					out = append(out, ctx.warn(cc.Pos(), "consider to make `default` case as first or as last case"))
				}
			}
			if cc, ok := stmt.(*ast.CommClause); ok && cc.Comm == nil {
				if idx != 0 && idx != len(list)-1 {
					out = append(out, ctx.warn(cc.Pos(), "consider to make `default` case as first or as last case"))
				}
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.SwitchStmt:
			if v.Body != nil {
				checkClauses(v.Body.List)
			}
		case *ast.TypeSwitchStmt:
			if v.Body != nil {
				checkClauses(v.Body.List)
			}
		case *ast.SelectStmt:
			if v.Body != nil {
				checkClauses(v.Body.List)
			}
		}
		return true
	})
	return out
}

