func checkArgOrder(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}
		fname := ctx.callFuncName(call)
		switch fname {
		case "strings.HasPrefix", "strings.HasSuffix", "bytes.HasPrefix", "bytes.HasSuffix",
			"strings.Contains", "bytes.Contains", "strings.ContainsRune":
			// first arg literal string, second non-const ?
		default:
			return true
		}
		// conditions: first arg is string literal (or const string?) and second is not literal?
		// Probed: HasPrefix("#", s) flagged, HasPrefix(s,"#") not, HasSuffix(s,"#") not
		// Also need to ensure literal looks like the longer (?) Simplest: first is basic string literal,
		// second is not a basic literal.
		if _, ok1 := stringLitValue(call.Args[0]); !ok1 {
			return true
		}
		if _, ok2 := stringLitValue(call.Args[1]); ok2 {
			return true
		}
		// For HasSuffix, doc example? If first is literal and pattern... Actually HasSuffix(s, suffix): first arg is s.
		// If code writes HasSuffix("#", s) it's reversed.
		// So flag any.
		out = append(out, ctx.warn(call.Args[0].Pos(), "%s and %s arguments order looks reversed", ctx.nodeText(call.Args[0]), ctx.nodeText(call.Args[1])))
		return true
	})
	return out
