// assignOp
func checkAssignOp(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok || as.Tok != token.ASSIGN || len(as.Lhs) != 1 || len(as.Rhs) != 1 {
			return true
		}
		bin, ok := unparen(as.Rhs[0]).(*ast.BinaryExpr)
		if !ok {
			return true
		}
		// bin.X must equal lhs
		if !ctx.exprEq(as.Lhs[0], bin.X) {
			return true
		}
		op := bin.Op
		var opStr string
		switch op {
		case token.ADD, token.SUB, token.MUL, token.QUO, token.REM, token.AND, token.OR, token.XOR, token.SHL, token.SHR, token.AND_NOT:
			opStr = op.String()
		default:
			return true
		}
		lhsText := ctx.nodeText(as.Lhs[0])
		rhsText := ctx.nodeText(bin.Y)
		origText := ctx.nodeText(as) // AssignStmt node text
		// special case +1 / -1 -> ++ / --
		if (op == token.ADD || op == token.SUB) {
			if v, ok := intLitValue(bin.Y); ok && v == "1" {
				sug := lhsText + "++"
				if op == token.SUB {
					sug = lhsText + "--"
				}
				out = append(out, ctx.warn(as.Pos(), "replace `%s` with `%s`", origText, sug))
				return true
			}
		}
		// origText as stored is statement text; original probe used exact source (no trailing semicolon)
		sug := fmt.Sprintf("%s %s= %s", lhsText, opStr, rhsText)
		out = append(out, ctx.warn(as.Pos(), "replace `%s` with `%s`", origText, sug))
		return true
	})
	return out
}

// badCall
func checkBadCall(ctx *checkerContext, lf *loadedFile) []warning {
