		if !ok {
			return true
		}
		fname := ctx.callFuncName(call)
		switch fname {
		case "strings.Replace", "bytes.Replace":
			if len(call.Args) == 4 {
				if v, ok := intLitValue(call.Args[3]); ok && v == "0" {
					out = append(out, ctx.warn(call.Pos(), "suspicious arg 0, probably meant -1"))
				}
			}
		case "strings.TrimSpace":
			// not?
		}
		// Additional suspicious calls probed later: will add in refinement
		// fmt Sprint with no args etc?
		return true
	})
