}

// badCond
func checkBadCond(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		// loop condition
		if fs, ok := n.(*ast.ForStmt); ok && fs.Cond != nil {
			// pattern i > n where init i:=0 and post i++
			// simplistic: binary > or >= and init is 0 ?
			if bin, ok := unparen(fs.Cond).(*ast.BinaryExpr); ok && (bin.Op == token.GTR || bin.Op == token.GEQ) {
				// check init assigns 0 to x and post increments x (same ident as bin.X)
				if fs.Init != nil && fs.Post != nil {
					if as, ok := fs.Init.(*ast.AssignStmt); ok && len(as.Rhs) == 1 {
						if v, ok := intLitValue(as.Rhs[0]); ok && v == "0" {
							// post is IncDec ++ on same
							if inc, ok := fs.Post.(*ast.IncDecStmt); ok && inc.Tok == token.INC {
								if ctx.exprEq(bin.X, inc.X) && ctx.exprEq(inc.X, as.Lhs[0]) {
									out = append(out, ctx.warn(bin.Pos(), "`%s` in loop; probably meant `%s`?", ctx.nodeText(bin), ctx.nodeText(bin.X)+" < "+ctx.nodeText(bin.Y)))
								}
							}
						}
					}
				}
			}
		}
		// duplicate equality condition a==b && a==b (only == ? probed)
		if bin, ok := n.(*ast.BinaryExpr); ok && (bin.Op == token.LAND) {
			// check if X and Y are identical equality expressions
			// Avoid double counting nested && chains: only flag topmost? original flagged once for a==b && a==b
			// If parent also is LAND with same? ast.Inspect will also visit sub? sub is X which is not LAND so fine.
			xb, ok1 := unparen(bin.X).(*ast.BinaryExpr)
			yb, ok2 := unparen(bin.Y).(*ast.BinaryExpr)
			if ok1 && ok2 && xb.Op == token.EQL && yb.Op == token.EQL {
				if ctx.exprEq(xb, yb) {
					out = append(out, ctx.warn(bin.Pos(), "`%s` condition is suspicious", ctx.nodeText(bin)))
				}
			}
		}
		return true
	})
	return out
}

// captLocal
func checkCaptLocal(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// paramsOnly default true: only func params/results
	// else also local variables
	checkIdent := func(id *ast.Ident) {
		if id == nil || id.Name == "_" || id.Name == "" {
			return
		}
		// capitalized: first rune uppercase and at least? Also if name is all caps? probe: IN, OUT, ERR flagged. LocalVar?
		// CaptLocal presumably flags names starting with uppercase letter?
		r := []rune(id.Name)[0]
		if unicode.IsUpper(r) {
			// ensure not exported? local scope
			out = append(out, ctx.warn(id.Pos(), "`%s' should not be capitalized", id.Name))
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			if v.Type != nil {
				if v.Type.Params != nil {
					for _, f := range v.Type.Params.List {
						for _, name := range f.Names {
							checkIdent(name)
						}
					}
				}
				if v.Type.Results != nil {
					for _, f := range v.Type.Results.List {
						for _, name := range f.Names {
							checkIdent(name)
						}
					}
				}
			}
			if paramCaptLocalParamsOnly {
				// still need to traverse into body? ast.Inspect will visit FuncType etc again causing duplicates.
				// To avoid duplicate of FuncLit params etc, we handle FuncLit separately and skip FuncType of FuncDecl here?
				// Return true will also visit params as nodes, but we do not flag on generic Ident visit.
				// So fine.
			}
		case *ast.FuncLit:
			if v.Type != nil {
				if v.Type.Params != nil {
					for _, f := range v.Type.Params.List {
						for _, name := range f.Names {
							checkIdent(name)
						}
					}
				}
				if v.Type.Results != nil {
					for _, f := range v.Type.Results.List {
						for _, name := range f.Names {
							checkIdent(name)
						}
					}
				}
			}
		default:
			if !paramCaptLocalParamsOnly {
				// local variable declarations: AssignStmt := , ValueSpec inside funcs, RangeStmt, etc.
				// We'll handle in second pass below to avoid duplicates? Simplify: handle here
				switch s := v.(type) {
				case *ast.AssignStmt:
					if s.Tok == token.DEFINE {
						for _, lhs := range s.Lhs {
							if id, ok := lhs.(*ast.Ident); ok {
								checkIdent(id)
							}
						}
					}
				case *ast.RangeStmt:
					if s.Tok == token.DEFINE {
						if id, ok := s.Key.(*ast.Ident); ok {
							checkIdent(id)
						}
						if id, ok := s.Value.(*ast.Ident); ok {
							checkIdent(id)
						}
					}
				case *ast.ValueSpec:
					// only locals - but ValueSpec at top level also visited; need know if inside func.
					// That determination hard in Inspect; skip ValueSpec here, handle via func bodies below.
					_ = s
				}
			}
		}
		return true
	})
	// TODO: for paramsOnly=false, local ValueSpec inside funcs could be missed; acceptable
	_ = out
	return out
}

// caseOrder
func checkCaseOrder(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ts, ok := n.(*ast.TypeSwitchStmt)
		if !ok {
			return true
		}
		// Find switch body
		var body *ast.BlockStmt
		// TypeSwitchStmt has Body
		body = ts.Body
		if body == nil {
			return true
		}
		// Collect cases in order: each CaseClause List are types
		// For each earlier case type A, later case type B, if B implements(?) / is subtype of A, then B unreachable.
		// Use type info: type of case expr? Cases are type expressions; their types are types.Type from TypesInfo? For type expr, TypeOf returns type?
		// Approach: get types via ctx.exprType for each case type expr, if later type is more specific: check if it implements earlier interface or if earlier is interface and later ...
		// Simplified based on ast types: *ast.BasicLit case in probe: ast.Expr is interface, *ast.BasicLit implements it.
		// Use types: laterType implements earlierType (if earlier is interface), or later is pointer vs earlier...
		type caseInfo struct {
			clause *ast.CaseClause
			expr   ast.Expr
			typ    types.Type
		}
		var cases []caseInfo
		for _, stmt := range body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			for _, e := range cc.List {
				t := ctx.exprType(e)
				cases = append(cases, caseInfo{clause: cc, expr: e, typ: t})
			}
		}
		for j := 0; j < len(cases); j++ {
			for i := 0; i < j; i++ {
				// if cases[j] is subtype of cases[i] and not equal
				if cases[i].typ == nil || cases[j].typ == nil {
					continue
				}
				if types.Identical(cases[i].typ, cases[j].typ) {
					continue
				}
				// if earlier is interface and later implements it
				if types.Implements(cases[j].typ, interfaceOf(cases[i].typ)) {
					// also need ensure earlier is interface type
					if isInterfaceType(cases[i].typ) {
						out = append(out, ctx.warn(cases[j].clause.Pos(), "case %s must go before the %s case", ctx.nodeText(cases[j].expr), ctx.nodeText(cases[i].expr)))
						break // one warning per later case?
					}
				}
			}
		}
		return true
	})
	return out
}

func interfaceOf(t types.Type) *types.Interface {
	if iface, ok := t.Underlying().(*types.Interface); ok {
		return iface
	}
	return nil
}
func isInterfaceType(t types.Type) bool {
	_, ok := t.Underlying().(*types.Interface)
	return ok
}

// codegenComment
func checkCodegenComment(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	for _, cg := range lf.AST.Comments {
		for _, c := range cg.List {
			if c.Pos() > lf.AST.Package {
				return out // only before package? original checks file header comments
			}
			if !strings.HasPrefix(c.Text, "//") {
				continue
			}
			text := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
			low := strings.ToLower(text)
			// malformed if it looks like generated comment but doesn't match
			// Probes: "// This file was automatically generated by foogen" flagged
			// "// Code generated by foo DO NOT EDIT." (without period) ??? probe later
			// heuristic: contains "generated" and not exact match
			if strings.Contains(low, "generated") {
				if !isGeneratedComment(text) {
					out = append(out, ctx.warn(c.Pos(), "comment should match `Code generated .* DO NOT EDIT.` regexp"))
				}
			}
		}
	}
	return out
}

// commentFormatting
func checkCommentFormatting(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	for _, cg := range lf.AST.Comments {
		for _, c := range cg.List {
			txt := c.Text
			if !strings.HasPrefix(txt, "//") {
				continue
			}
			if txt == "//" {
				continue
			}
			rest := txt[2:]
			if rest == "" {
				continue
			}
			// directives: //go:, //line, // +build, //go:build, etc (?) check first char
			if strings.HasPrefix(txt, "//go:") || strings.HasPrefix(txt, "//line") || strings.HasPrefix(txt, "// +build") || strings.HasPrefix(txt, "//go:build") {
				continue
			}
			// if rest starts with space or tab or / (///) or !? probe showed /// and //! not flagged, tab?
			// Original flagged //This and //bad, not /// / //! / //\t
			first := rest[0]
			if first == ' ' || first == '\t' || first == '/' || first == '!' {
				continue
			}
			// Also comments like //- ? Possibly URLs?
			out = append(out, ctx.warn(c.Pos(), "put a space between `//` and comment text"))
		}
	}
	return out
}

// defaultCaseOrder
func checkDefaultCaseOrder(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	checkClauses := func(list []ast.Stmt) {
		// find default index
		for idx, stmt := range list {
			if cc, ok := stmt.(*ast.CaseClause); ok && cc.List == nil {
				if idx != 0 && idx != len(list)-1 {
					out = append(out, ctx.warn(cc.Pos(), "consider to make `default` case as first or as last case"))
				}
			}
			if cc, ok := stmt.(*ast.CommClause); ok && cc.Comm == nil {
				if idx != 0 && idx != len(list)-1 {
					out = append(out, ctx.warn(cc.Pos(), "consider to make `default` case as first or as last case"))
				}
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.SwitchStmt:
			if v.Body != nil {
				checkClauses(v.Body.List)
			}
		case *ast.TypeSwitchStmt:
			if v.Body != nil {
				checkClauses(v.Body.List)
			}
		case *ast.SelectStmt:
			if v.Body != nil {
				checkClauses(v.Body.List)
			}
		}
		return true
	})
	return out
}

// deprecatedComment
func checkDeprecatedComment(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	// Need comments that are doc for declarations: we look at all comments
	// Original message varied by variant: probe one: use `Deprecated: ` (note the casing) instead of `deprecated: `
	// Need discover other variants later.
	for _, cg := range lf.AST.Comments {
		for _, _ = range cg.List {
			_ = cg
			break
		}
	}
	// Approach: Inspect decls with Doc
	checkDoc := func(doc *ast.CommentGroup) {
		if doc == nil {
			return
		}
		for _, c := range doc.List {
			text := strings.TrimPrefix(c.Text, "//")
			text = strings.TrimSpace(text)
			// also /* */ comments?
			// Paragraph beginning with deprecated...
			// Check forms:
			// It should be "Deprecated: "
			if strings.HasPrefix(text, "Deprecated:") {
				// check proper: "Deprecated: " with space?
				if !strings.HasPrefix(text, "Deprecated: ") && text != "Deprecated:" {
					// maybe message?
					// skip for now
				}
				continue
			}
			// lowercase
			lower := strings.ToLower(text)
			if strings.HasPrefix(lower, "deprecated") {
				// figure the actual prefix up to colon if any
				// extract up to first colon or space?
				rest := text[len("deprecated"):]
				prefix := "deprecated" + rest
				// only if prefix forms like "deprecated," "deprecated:" "deprecated." etc
				// Generate suggestion based on original prefix variation.
				// Probe showed for "deprecated, use..." - wait original code snippet in probe was //deprecated: bad (third). Actually probe batch included:
				// 1) // deprecated, use FuncNew ... (first line??) Wait output only one warning at line6 which corresponds to //deprecated: bad
				// Let's re-evaluate later; for now flag any lower case prefix starting with deprecated followed by :, ,, ?
				if strings.HasPrefix(rest, ":") || strings.HasPrefix(rest, ",") || strings.HasPrefix(rest, ".") || strings.HasPrefix(rest, " ") {
					// Determine the prefix string used in message: it includes up to colon+space if present?
					// For "deprecated: " case message: instead of `deprecated: `
					bad := "deprecated"
					if idx := strings.Index(text, ":"); idx >= 0 && idx < 20 {
						bad = text[:idx+1] + " "
						// if original had no space after colon, bad maybe "deprecated:" ?
						// Message in probe: '`Deprecated: ` (note the casing) instead of `deprecated: `'
						// That corresponds to c.Text being "deprecated:"? Let's generate based on actual:
						if !strings.HasPrefix(text[idx:], ": ") {
							bad = text[:idx+1]
							// suggestion still `Deprecated: ` ?
						}
					}
					out = append(out, ctx.warn(c.Pos(), "use `Deprecated: ` (note the casing) instead of `%s`", bad))
				}
			}
		}
	}
	for _, decl := range lf.AST.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			checkDoc(d.Doc)
		case *ast.GenDecl:
			checkDoc(d.Doc)
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					checkDoc(s.Doc)
				case *ast.ValueSpec:
					checkDoc(s.Doc)
				case *ast.ImportSpec:
					checkDoc(s.Doc)
				}
			}
		}
	}
	return out
}

// dupArg
// whitelist-ish generic: flag duplicate args in package selector calls and builtin copy
var dupArgExcluded = map[string]bool{
	"strings.Trim": true, "strings.TrimPrefix": true, "strings.TrimSuffix": true,
	"strings.IndexAny": true, "strings.LastIndexAny": true, "strings.Count": true, "bytes.Count": true,
	"bytes.IndexAny": true, "bytes.LastIndexAny": true,
}

func checkDupArg(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}
		fname := ctx.callFuncName(call)
		isBuiltinCopy := false
		if id, ok := unparen(call.Fun).(*ast.Ident); ok && id.Name == "copy" {
			isBuiltinCopy = true
		}
		if !isBuiltinCopy {
			// must be selector package call
			sel, ok := selectorOf(call.Fun)
			if !ok {
				return true
			}
			// check sel.X is package
			id, ok := sel.X.(*ast.Ident)
			if !ok {
				return true
			}
			if !ctx.isImportedName(id.Name) {
				// if type info tells it's package, accept
				if ctx.pkg.TypesInfo != nil {
					obj := ctx.pkg.TypesInfo.Uses[id]
					if _, isPkg := obj.(*types.PkgName); !isPkg {
						return true
					}
				} else {
					return true
				}
			}
			if dupArgExcluded[fname] {
				return true
			}
			// variadic calls like fmt.Println - arguments duplication maybe not flagged; exclude Print family?
			if strings.HasPrefix(fname, "fmt.") {
				return true
			}
		}
		// look for any duplicate pair (identical expr)
		for i := 0; i < len(call.Args); i++ {
			for j := i + 1; j < len(call.Args); j++ {
				if ctx.exprEq(call.Args[i], call.Args[j]) {
					out = append(out, ctx.warn(call.Pos(), "suspicious duplicated args in %s", ctx.nodeText(call)))
					return true
				}
			}
		}
		return true
	})
	return out
}

