		}
		// switch?
		return true
	})
	// Also switch (?) maybe
	walkFile(lf, func(n ast.Node) bool {
		// switch with 2 cases duplicate bodies? Probe later
		return true
	})
	return out
}

func stmtListEq(ctx *checkerContext, a, b []ast.Stmt) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if ctx.formatNode(a[i]) != ctx.formatNode(b[i]) {
			return false
		}
	}
	return true
}

// dupCase
func checkDupCase(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		var list []ast.Stmt
		switch v := n.(type) {
		case *ast.SwitchStmt:
			if v.Body != nil { list = v.Body.List }
		case *ast.TypeSwitchStmt:
			if v.Body != nil { list = v.Body.List }
		case *ast.SelectStmt:
			if v.Body != nil { list = v.Body.List }
		default:
			return true
		}
		// collect case exprs across all clauses in this switch
		seen := map[string]ast.Expr{}
		for _, stmt := range list {
			var exprs []ast.Expr
			var clause ast.Node
			switch cc := stmt.(type) {
			case *ast.CaseClause:
				exprs = cc.List
				clause = cc
			case *ast.CommClause:
				// comm clause comm is statement, not case expr - dupCase probably only switch
				_ = clause
				continue
			}
			for _, e := range exprs {
				key := ctx.formatNode(e)
				if _, dup := seen[key]; dup {
					out = append(out, ctx.warn(e.Pos(), "'case %s' is duplicated", ctx.nodeText(e)))
				} else {
					seen[key] = e
				}
				_ = clause
			}
		}
		return true
	})
	return out
}

// dupSubExpr
func checkDupSubExpr(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch bin.Op {
		case token.EQL, token.NEQ, token.LSS, token.GTR, token.LEQ, token.GEQ, token.ADD, token.SUB, token.MUL, token.QUO, token.REM, token.AND, token.OR, token.XOR, token.AND_NOT:
			// Also LAND/LOR?? probe had < only
			if ctx.exprEq(bin.X, bin.Y) {
				// exclude? For a==a etc badCond... dupSubExpr should flag? Probe a==b etc not.
				// In dupSubExpr probe, xs[0].v < xs[0].v flagged.
				// Conditions: operator is one of? We'll flag for relational and arithmetic as above.
				out = append(out, ctx.warn(bin.Pos(), "suspicious identical LHS and RHS for `%s` operator", bin.Op.String()))
			}
		case token.LAND, token.LOR:
			// if X == Y ?
			if ctx.exprEq(bin.X, bin.Y) {
				out = append(out, ctx.warn(bin.Pos(), "suspicious identical LHS and RHS for `%s` operator", bin.Op.String()))
			}
		}
		return true
	})
	return out
}

