// flagName
func checkFlagName(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 1 {
			return true
		}
		fname := ctx.callFuncName(call)
		if !strings.HasPrefix(fname, "flag.") {
			return true
		}
		// Which functions take flag name as first arg: Bool, String, Int, Var variants, etc.
		// Also flag package functions like Lookup(name) ? Probably.
		nameVal, ok := stringLitValue(call.Args[0])
		if !ok {
			return true
		}
		if nameVal == "" {
			out = append(out, ctx.warn(call.Pos(), "empty flag name"))
			return true
		}
		if strings.TrimSpace(nameVal) != nameVal {
			out = append(out, ctx.warn(call.Pos(), "flag name %q contains whitespace", nameVal))
			return true
		}
		if strings.Contains(nameVal, " ") || strings.Contains(nameVal, "\t") {
			out = append(out, ctx.warn(call.Pos(), "flag name %q contains whitespace", nameVal))
			return true
		}
		if strings.HasPrefix(nameVal, "-") {
			out = append(out, ctx.warn(call.Pos(), "flag name %q should not start with a hyphen", nameVal))
			return true
		}
		// other suspicious: contains "=" ?
		if strings.Contains(nameVal, "=") {
			out = append(out, ctx.warn(call.Pos(), "flag name %q should not contain '='", nameVal))
		}
		return true
	})
	return out
}

// ifElseChain
func checkIfElseChain(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// Count else-if chain. Trigger when number of if-else blocks >= minThreshold (default 2)
	// Structure: if {} else if {} else {} - count ??? Probe with 1 else-if + else gave warning.
	// Algorithm: For top-level if (not part of else-if), count number of else-ifs + final else?
	walkFile(lf, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		// Determine if this if is an else-if of a parent: we can't know parent in Inspect.
		// We can handle only "root" ifs by tracking: ast.Inspect visits root first, returns true will also visit inner else-if as separate node and would duplicate.
		// To avoid duplicates, we can in callback return false after handling chain? But Inspect control: if we handle a chain, we should not descend into its else chain? However we still need to visit bodies for nested ifs inside branches.
		// We'll implement custom recursive traversal instead below.
		_ = ifs
		return true
	})
	// Custom traversal
	var visit func(n ast.Node)
	seenRoot := map[*ast.IfStmt]bool{}
	// Build set of ifs that are else-if children
	elseIfSet := map[*ast.IfStmt]bool{}
	walkFile(lf, func(n ast.Node) bool {
		if ifs, ok := n.(*ast.IfStmt); ok {
			// walk its else chain
			cur := ifs
			for cur.Else != nil {
				if elseIf, ok := cur.Else.(*ast.IfStmt); ok {
					elseIfSet[elseIf] = true
					cur = elseIf
				} else {
					break
				}
			}
		}
		return true
	})
	visit = func(n ast.Node) {}
	_ = visit
	_ = seenRoot
	walkFile(lf, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		if elseIfSet[ifs] {
			return true // only roots evaluated
		}
		// count chain
		count := 0 // number of else branches?
		hasFinalElse := false
		cur := ifs
		for cur.Else != nil {
			if elseIf, ok := cur.Else.(*ast.IfStmt); ok {
				count++
				cur = elseIf
				if cur.Else != nil {
					if _, isIf := cur.Else.(*ast.IfStmt); !isIf {
						hasFinalElse = true
					}
				}
			} else {
				hasFinalElse = true
				break
			}
		}
		// threshold: minThreshold =2 (default). Probe: chain with 1 else-if + final else: count=1, hasFinalElse true -> ??? total blocks?
		// define total = count + (hasFinalElse?1:0) ??? that =2 meets threshold.
		// Also chain with 2 else-ifs no final else: total=2 meets.
		total := count
		if hasFinalElse {
			total++
		}
		if total >= paramIfElseChainMin {
			out = append(out, ctx.warn(ifs.Pos(), "rewrite if-else to switch statement"))
		}
		return true
	})
	return out
}

// mapKey
func checkMapKey(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		cl, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		// type must be map with string key
		t := ctx.exprType(cl)
		if t != nil {
			mt, ok := t.Underlying().(*types.Map)
			if !ok {
				return true
			}
			if !isStringType(mt.Key()) {
				// also if key type name string
				return true
			}
		} else {
			// syntactic: type is map[..]
			if _, ok := cl.Type.(*ast.MapType); !ok {
				return true
			}
		}
		if len(cl.Elts) < 2 {
			return true
		}
		type kv struct {
			key ast.Expr
			val string
			has bool
		}
		var bad []kv
		for _, elt := range cl.Elts {
			kve, ok := elt.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			s, ok := stringLitValue(kve.Key)
			if !ok {
				continue
			}
			if strings.HasPrefix(s, " ") || strings.HasSuffix(s, " ") {
				bad = append(bad, kv{key: kve.Key, val: s, has: true})
			}
		}
		if len(bad) == 1 {
			b := bad[0]
			out = append(out, ctx.warn(b.key.Pos(), "suspicious whitespace in %q key", b.val))
		}
		return true
	})
	return out
}

// newDeref
func checkNewDeref(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		star, ok := n.(*ast.StarExpr)
		if !ok {
			return true
		}
		call, ok := unparen(star.X).(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		id, ok := unparen(call.Fun).(*ast.Ident)
		if !ok || id.Name != "new" {
			return true
		}
		// Type argument is call.Args[0] type expr
		typeText := ctx.nodeText(call.Args[0])
		zero := zeroValueForType(typeText, ctx.exprType(call.Args[0]))
		// If zero unknown, message? Probe: new(bool)->false, new(int)->0
		if zero == "" {
			// Original might suggest something else for struct types: replace with T{}?
			// For now, use typeText+"{}"? We'll investigate later.
			zero = typeText + "{}"
			// For basic types probe later
		}
		out = append(out, ctx.warn(star.Pos(), "replace `%s` with `%s`", ctx.nodeText(star), zero))
		return true
	})
	return out
}

func zeroValueForType(typeText string, t types.Type) string {
	// strip package qualifier?
	base := typeText
	if idx := strings.LastIndex(base, "."); idx >= 0 {
		base = base[idx+1:]
	}
	switch base {
	case "bool":
		return "false"
	case "int", "int8", "int16", "int32", "int64", "uint", "uint8", "uint16", "uint32", "uint64", "uintptr", "float32", "float64", "complex64", "complex128", "byte", "rune":
		return "0"
	case "string":
		return `""`
	}
	// type info kind
	if t != nil {
		if b, ok := t.Underlying().(*types.Basic); ok {
			switch b.Kind() {
			case types.Bool, types.UntypedBool:
				return "false"
			case types.String, types.UntypedString:
				return `""`
			default:
				if b.Info()&types.IsNumeric != 0 {
					return "0"
				}
			}
		}
	}
	return ""
}

// offBy1
func checkOffBy1(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		idx, ok := n.(*ast.IndexExpr)
		if !ok {
			return true
		}
		// index is len(X) where X equals idx.X (or len of same)
		call, ok := unparen(idx.Index).(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		id, ok := unparen(call.Fun).(*ast.Ident)
		if !ok || id.Name != "len" {
			return true
		}
		if !ctx.exprEq(idx.X, call.Args[0]) {
			return true
		}
		// message: index expr always panics; maybe you wanted xs[len(xs)-1]?
		suggest := fmt.Sprintf("%s[len(%s)-1]", ctx.nodeText(idx.X), ctx.nodeText(call.Args[0]))
		out = append(out, ctx.warn(idx.Pos(), "index expr always panics; maybe you wanted %s?", suggest))
		return true
	})
	// Also slices xs[len(xs):] etc probed later
	return out
}

// regexpMust
func checkRegexpMust(ctx *checkerContext, lf *loadedFile) []warning {
