		}
		// Assign context: original flagged even when error used? Probe: re3,err:=Compile; _,_=re3,err still flagged (3rd)
		// So any const pattern compile
		// Message uses quoted pattern? For pattern "const": like "const"
		// It printed: for const patterns like "const", use regexp.MustCompile
		// Using %q for pat? pat is Go string; if pattern had backticks in source, it prints using ??? Node text?
		// Use original literal text? Probe: Compile("const") -> "const" includes quotes as in source.
		origArgText := ctx.nodeText(call.Args[0])
