// typeSwitchVar
func checkTypeSwitchVar(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ts, ok := n.(*ast.TypeSwitchStmt)
		if !ok {
			return true
		}
		// If switch already has assignment var (switch v := v.(type)), skip
		// Determine guarded expr: TypeSwitchStmt Assign or Init
		var assignStmt ast.Stmt
		if ts.Assign != nil {
			assignStmt = ts.Assign
		} else if ts.Init != nil {
			// init could be assignment?
			assignStmt = ts.Init
		}
		if assignStmt == nil {
			return true
		}
		// If assign is like v := v.(type) or v = v.(type) with a lhs ident that is not "_" ? then already has var.
		// Probe: switch v.(type) - assign is ExprStmt with TypeAssert ?
		// Detect base expression being asserted repeatedly in cases.
		var baseExpr ast.Expr
		switch a := assignStmt.(type) {
		case *ast.ExprStmt:
			if ta, ok := unparen(a.X).(*ast.TypeAssertExpr); ok {
				// Type is nil in type switch guard
				baseExpr = ta.X
			}
		case *ast.AssignStmt:
			// switch v := v.(type)
			return true // already has var
		}
		if baseExpr == nil {
			return true
		}
		if ts.Body == nil {
			return true
		}
		count := 0
		for _, stmt := range ts.Body.List {
			cc, ok := stmt.(*ast.CaseClause)
			if !ok {
				continue
			}
			// case has a type (not default?) and body contains a type assertion of baseExpr
			found := false
			for _, s := range cc.Body {
				ast.Inspect(s, func(nn ast.Node) bool {
					if ta, ok := nn.(*ast.TypeAssertExpr); ok && ta.Type != nil {
						if ctx.exprEq(ta.X, baseExpr) {
							found = true
						}
					}
					return true
				})
			}
			if found {
				count++
			}
		}
		if count >= 1 {
			// Original probe: 2 cases can benefit... message says "%d cases can benefit from type switch with assignment"
			// If count is 1, does it warn? Probe later
			out = append(out, ctx.warn(ts.Pos(), "%d cases can benefit from type switch with assignment", count))
		}
		return true
	})
	return out
}

// underef
func checkUnderef(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		// (*x).field, (*x)[i], (*x).method() (depending), (*x) ??? patterns: ParenExpr containing StarExpr as X of Selector/Index/Call
		switch v := n.(type) {
		case *ast.SelectorExpr:
			if paren, ok := v.X.(*ast.ParenExpr); ok {
				if star, ok := unparenStar(paren.X); ok {
					// skip receiver deref if it's a call selector? Selector is used in various contexts.
					// If parent is CallExpr and star receiver is pointer receiver method, skip per param.
					// We can't easily know parent; but check type of star.X : if it's pointer to type that has method with pointer receiver?
					// Simpler: if this selector is function of a CallExpr, ast.Inspect will also visit that CallExpr separate; our detection here might duplicate/ incorrectly flag method calls.
					// To mimic skipRecvDeref=true: if selector's name corresponds to a method... We can check type info selection.
					if paramUnderefSkipRecv {
						// If v is used as a Call Fun, we need to know. ast.Inspect doesn't give parent.
						// We'll handle call case separately and skip selector case when it's likely method call by checking next handling:
						// Heuristic: if method exists on pointer type, skip.
						// Determine type of star.X
						// Use TypesInfo Selections for v: if selection kind is MethodVal, skip ?
						if ctx.pkg.TypesInfo != nil {
							if sel, ok := ctx.pkg.TypesInfo.Selections[v]; ok && sel != nil && sel.Kind() == types.MethodVal {
								// But field access also selection FieldVal - method val only for method expressions? (*k).Method without call is method value.
								// In probe (*k).f is field, (*k).Method() likely call.
								// We'll skip method val.
								return true
							}
						}
					}
					simplified := ctx.nodeText(star.X) + "." + v.Sel.Name
					orig := ctx.nodeText(v)
					out = append(out, ctx.warn(v.Pos(), "could simplify %s to %s", orig, simplified))
				}
			}
		case *ast.IndexExpr:
			if paren, ok := v.X.(*ast.ParenExpr); ok {
				if star, ok := unparenStar(paren.X); ok {
					// only if a is array (not slice?) doc: v := (*a)[5] // only if a is array
					// Check type of star.X: pointer to array
					t := ctx.exprType(star.X)
					if t != nil {
						ut := t.Underlying()
						if ptr, ok := ut.(*types.Pointer); ok {
							if _, isArr := ptr.Elem().Underlying().(*types.Array); isArr {
								simplified := ctx.nodeText(star.X) + "[" + ctx.nodeText(v.Index) + "]"
								// If index list (generics IndexList) not here
								out = append(out, ctx.warn(v.Pos(), "could simplify %s to %s", ctx.nodeText(v), simplified))
							}
						}
					} else {
						// fallback: flag regardless?
						simplified := ctx.nodeText(star.X) + "[" + ctx.nodeText(v.Index) + "]"
						out = append(out, ctx.warn(v.Pos(), "could simplify %s to %s", ctx.nodeText(v), simplified))
					}
				}
			}
		case *ast.IndexListExpr:
			// generics, ignore
			_ = v
		}
		return true
	})
	return out
}

func unparenStar(e ast.Expr) (*ast.StarExpr, bool) {
	// e may be StarExpr directly (inside paren)
	if s, ok := e.(*ast.StarExpr); ok {
		return s, true
	}
	return nil, false
}

// unlambda
func checkUnlambda(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		fl, ok := n.(*ast.FuncLit)
		if !ok || fl.Body == nil || len(fl.Body.List) != 1 {
			return true
		}
		ret, ok := fl.Body.List[0].(*ast.ReturnStmt)
		if !ok || len(ret.Results) != 1 {
			// also could be a single ExprStmt call : func() { fn() } -> fn ?
			// Probe only return case
			// Check expr statement case later
			if es, ok := fl.Body.List[0].(*ast.ExprStmt); ok {
				_ = es
			}
			return true
		}
		call, ok := unparen(ret.Results[0]).(*ast.CallExpr)
		if !ok {
			return true
		}
		// function params must exactly match call args in order, simple idents
		if fl.Type == nil || fl.Type.Params == nil {
			return true
		}
		var paramNames []string
		for _, field := range fl.Type.Params.List {
			for _, name := range field.Names {
				paramNames = append(paramNames, name.Name)
			}
			// anonymous param? cannot match
			if len(field.Names) == 0 {
				return true
			}
		}
		if len(paramNames) != len(call.Args) {
			return true
		}
		for i, arg := range call.Args {
			id, ok := unparen(arg).(*ast.Ident)
			if !ok || id.Name != paramNames[i] {
				return true
			}
		}
		// Also need check results types match? function call returns ...
		// If FuncLit has results but call's function returns not? assume ok
		// Original message: replace `func(x int) int { return fn(x) }` with `fn`
		// The printed FuncLit text uses printer normalized (spaces). In probe, source was func(x int)int{return fn(x)} but message showed spaces: func(x int) int { return fn(x) }
		// So use formatNode for FuncLit, nodeText for function?
		litText := ctx.formatNode(fl)
		fnText := ctx.nodeText(call.Fun)
		out = append(out, ctx.warn(fl.Pos(), "replace `%s` with `%s`", litText, fnText))
		return true
	})
	return out
}

