// appendAssign
func checkAppendAssign(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok || len(as.Lhs) != 1 || len(as.Rhs) != 1 {
			return true
		}
		call, ok := unparen(as.Rhs[0]).(*ast.CallExpr)
		if !ok {
			return true
		}
		id, ok := unparen(call.Fun).(*ast.Ident)
		if !ok || id.Name != "append" || len(call.Args) < 1 {
			return true
		}
		if !ctx.exprEq(as.Lhs[0], call.Args[0]) {
			out = append(out, ctx.warn(call.Pos(), "append result not assigned to the same slice"))
		}
		return true
	})
	return out
}

// appendCombine
func checkAppendCombine(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// helper to process a statement list
	processList := func(list []ast.Stmt) {
		i := 0
		for i < len(list) {
			// collect chain
			j := i
			var first *ast.AssignStmt
			var firstCall *ast.CallExpr
			count := 0
			var lhs ast.Expr
			for j < len(list) {
				as, ok := list[j].(*ast.AssignStmt)
				if !ok || len(as.Lhs) != 1 || len(as.Rhs) != 1 {
					break
				}
				call, ok := unparen(as.Rhs[0]).(*ast.CallExpr)
				if !ok {
					break
				}
				id, ok := unparen(call.Fun).(*ast.Ident)
				if !ok || id.Name != "append" || len(call.Args) < 1 {
					break
				}
				if count == 0 {
					if !ctx.exprEq(as.Lhs[0], call.Args[0]) {
						break
					}
					first = as
					firstCall = call
					lhs = as.Lhs[0]
				} else {
					if !ctx.exprEq(lhs, as.Lhs[0]) || !ctx.exprEq(lhs, call.Args[0]) {
						break
					}
				}
				count++
				j++
			}
			if count >= 2 {
				out = append(out, ctx.warn(firstCall.Pos(), "can combine chain of %d appends into one", count))
				_ = first
				i = j
			} else {
				i++
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.BlockStmt:
			processList(v.List)
		case *ast.CaseClause:
			processList(v.Body)
		case *ast.CommClause:
			processList(v.Body)
		}
		return true
	})
	return out
}

// argOrder
var argOrderFuncs = map[string]bool{
	"strings.HasPrefix": true, "strings.HasSuffix": true, "strings.TrimPrefix": false, // TrimPrefix excluded? handled below
	"bytes.HasPrefix": true, "bytes.HasSuffix": true,
	"strings.Contains": true, "bytes.Contains": true,
