// singleCaseSwitch
func checkSingleCaseSwitch(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		var body *ast.BlockStmt
		isType := false
		switch v := n.(type) {
		case *ast.SwitchStmt:
			body = v.Body
		case *ast.TypeSwitchStmt:
			body = v.Body
			isType = true
		default:
			return true
		}
		if body == nil {
			return true
		}
		// count non-default cases
		cases := 0
		hasDefault := false
		for _, stmt := range body.List {
			if cc, ok := stmt.(*ast.CaseClause); ok {
				if cc.List == nil {
					hasDefault = true
				} else {
					cases++
				}
			}
		}
		if cases == 1 && !hasDefault {
			out = append(out, ctx.warn(n.Pos(), "should rewrite switch statement to if statement"))
		}
		_ = isType
		return true
	})
	return out
}

// sloppyLen
func checkSloppyLen(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		// detect len(x) op const
		// patterns: len <=0, len <0, len >=0 (?) etc
		// helper to extract len call and other side
		type lenSide struct {
			call *ast.CallExpr
			other ast.Expr
			lenOnLeft bool
		}
		extract := func() *lenSide {
			if call, ok := unparen(bin.X).(*ast.CallExpr); ok && isLenCall(ctx, call) {
				return &lenSide{call: call, other: bin.Y, lenOnLeft: true}
			}
			if call, ok := unparen(bin.Y).(*ast.CallExpr); ok && isLenCall(ctx, call) {
				return &lenSide{call: call, other: bin.X, lenOnLeft: false}
			}
			return nil
		}
		ls := extract()
		if ls == nil {
			return true
		}
		// other must be int lit 0 or -1 etc
		otherText := ctx.nodeText(ls.other)
		// Evaluate constant int if literal / unary
		cval, ok := constIntValue(ls.other)
		if !ok {
			return true
		}
		lenText := ctx.nodeText(ls.call) // len(xs)
		whole := ctx.nodeText(bin)
		// Normalize operator direction if len on right: flip
		op := bin.Op
		if !ls.lenOnLeft {
			op = flipOp(op)
		}
		// Cases probed:
		// len <=0 => can be len == 0  (message: "len(xs) <= 0 can be len(xs) == 0")
		// len <0 => always false
		// len >=0 => always true
		// len > -1 (?) probe in first batch: function i returning len > -1 not flagged in output (only 3 warnings). Actually list: g len<0, f len<=0, h len>=0 . i len>-1 absent. Hmm len > -1 is always true similar to >=0 but not flagged? Wait maybe because -1 literal is unary expr not basic lit, constInt handles? But we must match: len > -1 not flagged - maybe they only handle 0 constant.
		if cval != 0 {
			return true
		}
		_ = otherText
		switch op {
		case token.LEQ:
			out = append(out, ctx.warn(bin.Pos(), "%s can be %s == 0", whole, lenText))
		case token.LSS:
			out = append(out, ctx.warn(bin.Pos(), "%s is always false", whole))
		case token.GEQ:
			out = append(out, ctx.warn(bin.Pos(), "%s is always true", whole))
		case token.GTR:
			// len >0 is normal, not
		case token.EQL:
			// len ==0 is fine
		}
		return true
	})
	return out
}

func isLenCall(ctx *checkerContext, call *ast.CallExpr) bool {
	id, ok := unparen(call.Fun).(*ast.Ident)
	return ok && id.Name == "len" && len(call.Args) == 1
}
func flipOp(op token.Token) token.Token {
	switch op {
	case token.LSS:
		return token.GTR
	case token.GTR:
		return token.LSS
	case token.LEQ:
		return token.GEQ
	case token.GEQ:
		return token.LEQ
	default:
		return op
	}
}
func constIntValue(e ast.Expr) (int64, bool) {
	e = unparen(e)
	if bl, ok := e.(*ast.BasicLit); ok && bl.Kind == token.INT {
		v, err := strconv.ParseInt(bl.Value, 0, 64)
		if err == nil {
			return v, true
		}
		// try uint
		uv, err2 := strconv.ParseUint(bl.Value, 0, 64)
		if err2 == nil {
			return int64(uv), true
		}
		return 0, false
	}
	if ue, ok := e.(*ast.UnaryExpr); ok && ue.Op == token.SUB {
		v, ok := constIntValue(ue.X)
		if ok {
			return -v, true
		}
	}
	return 0, false
}

