// valSwap
func checkValSwap(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// Process statement lists
	processList := func(list []ast.Stmt) {
		for i := 0; i+2 < len(list); i++ {
			// patterns:
			// tmp := a ; a = b ; b = tmp  (first can be := or = where tmp is fresh? )
			// *tmp = *x; *x = *y; *y = *tmp  (doc)
			// generalize: stmt1: tmp = X, stmt2: X = Y, stmt3: Y = tmp  (LHS/RHS)
			s1, ok1 := list[i].(*ast.AssignStmt)
			s2, ok2 := list[i+1].(*ast.AssignStmt)
			s3, ok3 := list[i+2].(*ast.AssignStmt)
			if !ok1 || !ok2 || !ok3 {
				continue
			}
			if len(s1.Lhs) != 1 || len(s1.Rhs) != 1 || len(s2.Lhs) != 1 || len(s2.Rhs) != 1 || len(s3.Lhs) != 1 || len(s3.Rhs) != 1 {
				continue
			}
			tmpExpr := s1.Lhs[0]
			xExpr := s1.Rhs[0]
			// s2: x = y
			if !ctx.exprEq(s2.Lhs[0], xExpr) {
				continue
			}
			yExpr := s2.Rhs[0]
			// s3: y = tmp
			if !ctx.exprEq(s3.Lhs[0], yExpr) || !ctx.exprEq(s3.Rhs[0], tmpExpr) {
				continue
			}
			// message: can re-write as `a, b = b, a`
			sug := fmt.Sprintf("%s, %s = %s, %s", ctx.nodeText(xExpr), ctx.nodeText(yExpr), ctx.nodeText(yExpr), ctx.nodeText(xExpr))
			out = append(out, ctx.warn(s1.Pos(), "can re-write as `%s`", sug))
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.BlockStmt:
			processList(v.List)
		case *ast.CaseClause:
			processList(v.Body)
		case *ast.CommClause:
			processList(v.Body)
		}
		return true
	})
	return out
}

// wrapperFunc
func checkWrapperFunc(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := selectorOf(call.Fun)
		if !ok {
			return true
		}
		// WaitGroup Add(-1) -> Done
		if sel.Sel.Name == "Add" && len(call.Args) == 1 {
			// arg is -1
			if ue, ok := unparen(call.Args[0]).(*ast.UnaryExpr); ok && ue.Op == token.SUB {
				if v, ok := intLitValue(ue.X); ok && v == "1" {
					// Check receiver type is sync.WaitGroup (or pointer)
					t := ctx.exprType(sel.X)
					if t != nil {
						// named type sync.WaitGroup
						name := typeNameString(t)
						if strings.Contains(name, "WaitGroup") {
							out = append(out, ctx.warn(call.Pos(), "use WaitGroup.Done method in `%s`", ctx.nodeText(call)))
							return true
						}
					} else {
						// fallback: heuristic if receiver name is wg ?
						out = append(out, ctx.warn(call.Pos(), "use WaitGroup.Done method in `%s`", ctx.nodeText(call)))
						return true
					}
				}
			}
		}
		// Other wrapper cases will be explored later (e.g. time, sync, etc)
		// Package-level wrappers:
		fname := ctx.callFuncName(call)
		switch fname {
		case "strings.TrimPrefix":
			// not wrapper?
		}
		return true
	})
	return out
}

