func checkExternalErrorReassign(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		as, ok := n.(*ast.AssignStmt)
		if !ok {
			return true
		}
		for _, lhs := range as.Lhs {
			sel, ok := selectorOf(unparen(lhs))
			if !ok {
				continue
			}
			if id, ok := sel.X.(*ast.Ident); ok && ctx.isImportedName(id.Name) {
				// Check if selected object is a var error? io.EOF
				// Use type info: Uses[sel.Sel] is *types.Var with type error?
				if ctx.pkg.TypesInfo != nil {
					if obj := ctx.pkg.TypesInfo.Uses[sel.Sel]; obj != nil {
						// obj type should be error ?
						out = append(out, ctx.warn(as.Pos(), "suspicious reassignment of error from another package"))
						break
					}
				} else {
					out = append(out, ctx.warn(as.Pos(), "suspicious reassignment of error from another package"))
					break
				}
			}
		}
		return true
	})
	return out
}

func checkFilepathJoin(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
