		}
		fname := ctx.callFuncName(call)
		if fname != "path/filepath.Join" && fname != "filepath.Join" && fname != "path.Join" {
			// callFuncName returns last segment based package name, so filepath.Join is expected
			// Actually above covered; if fname is "filepath.Join", second case catches
			if fname != "filepath.Join" {
				return true
			}
		}
		for _, arg := range call.Args {
			if s, ok := stringLitValue(arg); ok {
