					// Only if ends with separator? Probe more later. For now flag if string contains separator and not just ?
					// To match probe, we flag any containing '/' - risk: Join("a/b", ...) may be intended.
					out = append(out, ctx.warn(call.Pos(), "%q contains a path separator", s))
				}
