func checkPreferWriteByte(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		sel, ok := selectorOf(call.Fun)
		if !ok || sel.Sel.Name != "WriteRune" {
			return true
		}
		// arg is rune literal single byte: '\n' etc where rune value < 128 and is char literal
		bl, ok := unparen(call.Args[0]).(*ast.BasicLit)
		if !ok || bl.Kind != token.CHAR {
			return true
		}
		// unquote char
		r, _, _, err := strconv.UnquoteChar(strings.Trim(bl.Value, "'"), '\'')
		if err != nil {
			// try using strconv parse
			v, err2 := strconv.Unquote(bl.Value)
			if err2 != nil || len([]rune(v)) != 1 {
				return true
			}
			r = []rune(v)[0]
		}
		if r >= 128 {
			return true
		}
		out = append(out, ctx.warn(call.Pos(), "consider writing single byte rune %s with %s.WriteByte(%s)", bl.Value, ctx.nodeText(sel.X), bl.Value))
		return true
	})
	return out
}

func checkPtrToRefParam(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	checkFunc := func(ft *ast.FuncType, pos token.Pos) {
		if ft == nil {
			return
		}
		// params
		if ft.Params != nil {
			for _, field := range ft.Params.List {
				if isPtrToRef(field.Type, ctx) {
					if len(field.Names) > 0 {
						for _, name := range field.Names {
							out = append(out, ctx.warn(field.Pos(), "consider `%s' to be of non-pointer type", name.Name))
							// Original position for param: field.Pos() ? Probe pointer param m at col8 - field starts at m - correct.
						}
					} else {
						out = append(out, ctx.warn(field.Pos(), "consider `%s' to be of non-pointer type", ctx.nodeText(field.Type)))
					}
				}
			}
		}
		// results
		if ft.Results != nil {
			for _, field := range ft.Results.List {
				if isPtrToRef(field.Type, ctx) {
					if len(field.Names) > 0 {
						for _, name := range field.Names {
							// message for named result? Original for result `(*chan int)` unnamed gave: consider to make non-pointer type for `*chan int`
							out = append(out, ctx.warn(field.Pos(), "consider `%s' to be of non-pointer type", name.Name))
						}
					} else {
						out = append(out, ctx.warn(field.Pos(), "consider to make non-pointer type for `%s`", ctx.nodeText(field.Type)))
					}
				}
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			checkFunc(v.Type, v.Pos())
		case *ast.FuncLit:
