func hasStringMethod(t types.Type) bool {
	// Use method set
	ms := types.NewMethodSet(t)
	for i := 0; i < ms.Len(); i++ {
		obj := ms.At(i).Obj()
		if obj.Name() == "String" {
			if sig, ok := obj.Type().(*types.Signature); ok && sig.Params().Len() == 0 && sig.Results().Len() == 1 && isStringType(sig.Results().At(0).Type()) {
				return true
			}
		}
	}
	// pointer method set
	if ptr := types.NewPointer(t); true {
		ms2 := types.NewMethodSet(ptr)
		for i := 0; i < ms2.Len(); i++ {
			if ms2.At(i).Obj().Name() == "String" {
				return true
			}
		}
	}
	return false
}

