func checkBoolExprSimplify(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		// !(x >= y) -> x < y etc
		if ue, ok := n.(*ast.UnaryExpr); ok && ue.Op == token.NOT {
			if bin, ok := unparen(ue.X).(*ast.BinaryExpr); ok {
				var newOp token.Token
				switch bin.Op {
				case token.GEQ:
					newOp = token.LSS
				case token.GTR:
					newOp = token.LEQ
				case token.LEQ:
					newOp = token.GTR
				case token.LSS:
					newOp = token.GEQ
				case token.EQL:
					newOp = token.NEQ
				case token.NEQ:
					newOp = token.EQL
				default:
					return true
				}
				sug := fmt.Sprintf("%s %s %s", ctx.nodeText(bin.X), newOp.String(), ctx.nodeText(bin.Y))
				out = append(out, ctx.warn(ue.Pos(), "can simplify `%s` to `%s`", ctx.nodeText(ue), sug))
				return true
			}
		}
		// !(x) == !(y) -> (x) == (y) , also !=
		if bin, ok := n.(*ast.BinaryExpr); ok && (bin.Op == token.EQL || bin.Op == token.NEQ) {
			ux, ok1 := unparen(bin.X).(*ast.UnaryExpr)
			uy, ok2 := unparen(bin.Y).(*ast.UnaryExpr)
			if ok1 && ok2 && ux.Op == token.NOT && uy.Op == token.NOT {
				// Sug uses original text of ux.X with its parens? Probe: !(x) == !(y) -> (x) == (y) - they keep parentheses nodes as written: ux.X is ParenExpr (x)
				sug := fmt.Sprintf("%s %s %s", ctx.nodeText(ux.X), bin.Op.String(), ctx.nodeText(uy.X))
				out = append(out, ctx.warn(bin.Pos(), "can simplify `%s` to `%s`", ctx.nodeText(bin), sug))
			}
		}
		return true
	})
	return out
}

func checkBuiltinShadow(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// Detect definitions of predeclared idents in assignments / params / etc (like builtinShadowDecl but local)
	// Original: function params also flagged (fmt: max param), local var len:=...
	report := func(id *ast.Ident) {
		if id != nil && predeclared[id.Name] && id.Name != "_" {
			// exclude true/false/iota/nil? Those can't be defined as names in Go? They would be parse?
			out = append(out, ctx.warn(id.Pos(), "shadowing of predeclared identifier: %s", id.Name))
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.AssignStmt:
			if v.Tok == token.DEFINE {
				for _, lhs := range v.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						report(id)
					}
				}
			}
		case *ast.RangeStmt:
			if v.Tok == token.DEFINE {
				if id, ok := v.Key.(*ast.Ident); ok {
					report(id)
				}
				if id, ok := v.Value.(*ast.Ident); ok {
					report(id)
				}
			}
		case *ast.Field:
			// function params / results, struct fields? Struct fields named len? That would shadow? Probably not fields.
			// We need differentiate: Field in FuncType vs StructType: ast.Inspect doesn't give parent.
			// We'll handle FuncDecl/FuncLit separately and ignore Field here.
			_ = v
		case *ast.FuncDecl:
			if v.Type != nil {
				reportFields(v.Type.Params, report)
				reportFields(v.Type.Results, report)
			}
			if v.Recv != nil {
				reportFields(v.Recv, report)
			}
		case *ast.FuncLit:
			if v.Type != nil {
				reportFields(v.Type.Params, report)
				reportFields(v.Type.Results, report)
			}
		case *ast.ValueSpec:
			// local var or global? builtinShadow may flag var declarations inside funcs and also globals? fmt scan had var? Cases 817: real, imag as local assignment? It was var?
			// We'll report names - but top-level var named max would be also builtinShadowDecl, but this checker is for assignments? Probe earlier: var max int at top level with builtinShadowDecl flagged; builtinShadow probe with `var max int`? In batch earlier builtinShadowDecl probe, we didn't run builtinShadow on it. Need test but assume ValueSpec inside FuncDecl only? ast walk can't tell.
			// Report anyway, may duplicate expectations? If top-level var, builtinShadow checker might also flag ("in assignments")
			for _, name := range v.Names {
				report(name)
			}
		case *ast.TypeSpec:
			// type named len - that's Decl shadowing, not builtinShadow? Might not
		case *ast.IncDecStmt:
			_ = v
		}
		return true
	})
	return out
}

func reportFields(fl *ast.FieldList, report func(*ast.Ident)) {
	if fl == nil {
		return
	}
	for _, f := range fl.List {
		for _, n := range f.Names {
			report(n)
		}
	}
}

