func checkCommentedOutCode(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	// Comments inside function bodies: text after // trimmed length >= minLength and looks like Go code
	for _, cg := range lf.AST.Comments {
		for _, c := range cg.List {
			if !strings.HasPrefix(c.Text, "//") {
				continue
			}
			// must be inside a function body: find position within a FuncDecl/FuncLit body
			if !posInsideFuncBody(ctx, lf, c.Pos()) {
				continue
			}
			text := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
			if len(text) < paramCommentedOutCodeMinLen {
				continue
			}
			if looksLikeCode(text) {
				out = append(out, ctx.warn(c.Pos(), "may want to remove commented-out code"))
			}
		}
	}
	return out
}

func posInsideFuncBody(ctx *checkerContext, lf *loadedFile, pos token.Pos) bool {
	found := false
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			if v.Body != nil && pos >= v.Body.Pos() && pos <= v.Body.End() {
				found = true
			}
		case *ast.FuncLit:
			if v.Body != nil && pos >= v.Body.Pos() && pos <= v.Body.End() {
				found = true
			}
		}
		return true
	})
	return found
}

func looksLikeCode(s string) bool {
	// Heuristics: contains '(' and ')' and ends? or ends with ; or contains call pattern or keywords
	// Examples: fmt.Println("Debugging hard")
	if strings.Contains(s, "(") && strings.Contains(s, ")") {
		// exclude prose containing parens? Simple
		return true
	}
	if strings.HasSuffix(s, ";") {
		return true
	}
	// statements: return, if, for, :=, =
	if strings.HasPrefix(s, "return ") || strings.HasPrefix(s, "if ") || strings.HasPrefix(s, "for ") {
		return true
	}
	if strings.Contains(s, ":=") {
		return true
	}
	return false
}

func checkCommentedOutImport(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	// Comments inside import GenDecl parentheses
	for _, decl := range lf.AST.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		// look at comments whose position is inside gd
		for _, cg := range lf.AST.Comments {
			for _, c := range cg.List {
				if c.Pos() < gd.Pos() || c.Pos() > gd.End() {
					continue
				}
				if !strings.HasPrefix(c.Text, "//") {
					continue
				}
				rest := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
				// should be like "os" or `"os"` or os "os" ?
				// Probe: //"os"
				impPath := ""
				if strings.HasPrefix(rest, "\"") {
					v, err := strconv.Unquote(rest)
					if err == nil {
						impPath = v
					} else {
						// rest may be "\"os\"" with closing
						impPath = strings.Trim(rest, "\"")
					}
				} else {
					continue
				}
				out = append(out, ctx.warn(c.Pos(), "remove commented-out %q import", impPath))
			}
		}
	}
	return out
}

func checkDeferInLoop(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// Defer inside for/range loop bodies (not nested func)
	walkFile(lf, func(n ast.Node) bool {
		var body *ast.BlockStmt
		switch v := n.(type) {
		case *ast.ForStmt:
			body = v.Body
		case *ast.RangeStmt:
			body = v.Body
		default:
			return true
		}
		if body == nil {
			return true
		}
		ast.Inspect(body, func(nn ast.Node) bool {
			if _, ok := nn.(*ast.FuncLit); ok {
				return false
			}
			if d, ok := nn.(*ast.DeferStmt); ok {
				out = append(out, ctx.warn(d.Pos(), "Possible resource leak, 'defer' is called in the 'for' loop"))
				return false
			}
			return true
		})
		return true
	})
	return out
}

func checkDeferUnlambda(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		d, ok := n.(*ast.DeferStmt)
		if !ok {
			return true
		}
		// defer func(){ f() }()
		callOuter, ok := unparen(d.Call.Fun).(*ast.FuncLit)
		_ = callOuter
		// DeferStmt.Call is CallExpr where Fun is FuncLit and Args empty, and Fun.Body single call statement
		if fl, ok := unparen(d.Call.Fun).(*ast.FuncLit); ok && len(d.Call.Args) == 0 && fl.Body != nil && len(fl.Body.List) == 1 {
			// body is ExprStmt call or ??? probe defer func(){ f() }()
			if es, ok := fl.Body.List[0].(*ast.ExprStmt); ok {
				if innerCall, ok := unparen(es.X).(*ast.CallExpr); ok {
					// args of inner call must match fl params (none)
					sug := fmt.Sprintf("defer %s", ctx.nodeText(innerCall))
					out = append(out, ctx.warn(d.Pos(), "can rewrite as `%s`", sug))
				}
			} else if ret, ok := fl.Body.List[0].(*ast.ReturnStmt); ok {
				_ = ret
			}
		}
		return true
	})
	return out
}

func checkDocStub(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	// Exported declarations whose Doc text is like "Foo ..." or "Foo is ..." stub?
	// Probe: // Foo ... flagged
	checkDoc := func(doc *ast.CommentGroup, name string) {
		if doc == nil || name == "" {
			return
		}
		text := doc.Text()
		text = strings.TrimSpace(text)
		// stub patterns: "<Name> ..." , "<Name> ...." etc
		if text == name+" ..." || text == name+"..." || strings.HasSuffix(text, "...") && strings.HasPrefix(text, name) {
			// Determine position: doc.Pos()
			out = append(out, ctx.warn(doc.Pos(), "silencing go lint doc-comment warnings is unadvised"))
		}
	}
	for _, decl := range lf.AST.Decls {
		if fd, ok := decl.(*ast.FuncDecl); ok {
			if fd.Name != nil && ast.IsExported(fd.Name.Name) {
				checkDoc(fd.Doc, fd.Name.Name)
			}
		}
		if gd, ok := decl.(*ast.GenDecl); ok {
			for _, spec := range gd.Specs {
				if ts, ok := spec.(*ast.TypeSpec); ok && ast.IsExported(ts.Name.Name) {
					doc := ts.Doc
					if doc == nil {
						doc = gd.Doc
					}
					checkDoc(doc, ts.Name.Name)
				}
			}
		}
	}
	return out
}

func checkDupImport(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	type impInfo struct {
		path string
		spec *ast.ImportSpec
		line1 int
	}
	seen := map[string]*impInfo{}
	for _, imp := range lf.AST.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		if prev, ok := seen[path]; ok {
			// Report each duplicate import spec? Probe gave two warnings on same line for both specs (col 9 and 16) with lines 2 and 2
			// First warning is for first import? Position of first spec (?) and second?
			// Probe output: :2:9 and :2:16 both message "package is imported 2 times under different aliases on lines 2 and 2"
			// That suggests for each spec in duplicate group, warn.
			// But our iterative approach will only warn on second on detection. To mimic, if this is second occurrence, warn for prev and current.
			// If third, ??? Might warn again?
			posPrev := ctx.pkg.Fset.Position(prev.spec.Pos())
			posCurr := ctx.pkg.Fset.Position(imp.Pos())
			// Only warn prev once: if prev not yet warned? We can warn both when encountering duplicate for first time.
			// Use a set
			_ = posPrev
			out = append(out, ctx.warn(prev.spec.Pos(), "package is imported 2 times under different aliases on lines %d and %d", posPrev.Line, posCurr.Line))
			out = append(out, ctx.warn(imp.Pos(), "package is imported 2 times under different aliases on lines %d and %d", posPrev.Line, posCurr.Line))
		} else {
			seen[path] = &impInfo{path: path, spec: imp}
		}
	}
	return out
}

