func checkHexLiteral(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bl, ok := n.(*ast.BasicLit)
		if !ok || bl.Kind != token.INT {
			return true
		}
		val := bl.Value
		if strings.HasPrefix(val, "0X") {
			sug := "0x" + val[2:]
			out = append(out, ctx.warn(bl.Pos(), "prefer 0x over 0X, s/%s/%s/", val, sug))
			return true
		}
		if strings.HasPrefix(val, "0x") {
			digits := val[2:]
			hasLower := false
			hasUpper := false
			for _, r := range digits {
				if r >= 'a' && r <= 'f' { hasLower = true }
				if r >= 'A' && r <= 'F' { hasUpper = true }
			}
			if hasLower && hasUpper {
				out = append(out, ctx.warn(bl.Pos(), "don't mix hex literal letter digits casing"))
			}
		}
		return true
	})
	return out
}

