func checkHugeParam(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	reportFunc := func(ft *ast.FuncType) {
		if ft == nil || ft.Params == nil {
			return
		}
		for _, field := range ft.Params.List {
			t := ctx.exprType(field.Type)
			if t == nil {
				// Try types from TypeInfo for field type - TypeOf on Type expr returns type
				continue
			}
			// TypesInfo.TypeOf for a type expr gives the type itself? For [1024]int it gives [1024]int unnamed array type.
			sz := typeSize(ctx, t)
			if sz > int64(paramHugeParamSize) {
				// for each name in field
				if len(field.Names) == 0 {
					// unnamed param? position field
					out = append(out, ctx.warn(field.Pos(), "%s is heavy (%d bytes); consider passing it by pointer", ctx.nodeText(field.Type), sz))
				} else {
					for _, name := range field.Names {
						out = append(out, ctx.warn(field.Type.Pos(), "%s is heavy (%d bytes); consider passing it by pointer", name.Name, sz))
						// Wait probe: func f(x [1024]int) position at 2:8 which is f? Let's check: `func f(x [1024]int)` col: 1 func,6 f,7 '(' ,8 x ... So position is param ident, not type. Our warn used field.Type.Pos() - wrong. Use name.Pos().
						// correction: change below line's pos - currently we used field.Type.Pos(), fix by using name.Pos by editing after)
						// We'll adjust: last appended warning position overwritten? Can't. We'll reimplement: need to warn at name.
						// To avoid wrong, remove last and re-add
						out = out[:len(out)-1]
						out = append(out, ctx.warn(name.Pos(), "%s is heavy (%d bytes); consider passing it by pointer", name.Name, sz))
					}
				}
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			reportFunc(v.Type)
		case *ast.FuncLit:
			reportFunc(v.Type)
		case *ast.FuncType:
			// This will duplicate FuncDecl params because walk visits FuncType inside FuncDecl.
			// To avoid, skip: FuncDecl case already handled and returning true will cause double.
			// But walk can't prevent. We'll rely on FuncDecl/FuncLit only and expect duplicate if we also do FuncType.
			_ = v
		}
		return true
	})
	return out
}

func typeSize(ctx *checkerContext, t types.Type) int64 {
	sizes := types.SizesFor("gc", "amd64")
	// Use arch from env?
	if sz := ctx.pkgTypesSizes(); sz != nil {
		sizes = sz
	}
	if sizes == nil {
		return 0
	}
	return sizes.Sizeof(t)
}

func (ctx *checkerContext) pkgTypesSizes() types.Sizes {
	// We stored sizes in type check config but not kept; compute
	arch := "amd64"
	// try env GOARCH
	if v := getenvGOARCH(); v != "" {
		arch = v
	}
	return types.SizesFor("gc", arch)
}

func checkImportShadow(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// Local definitions shadowing import names (package scope imports of this file)
	importNames := map[string]bool{}
	if lf.AST != nil {
		for _, imp := range lf.AST.Imports {
			name := ""
			if imp.Name != nil {
				name = imp.Name.Name
			} else {
				p, _ := strconv.Unquote(imp.Path.Value)
				name = pkgPathLast(p)
			}
			if name != "" && name != "_" && name != "." {
				importNames[name] = true
			}
		}
	}
	if len(importNames) == 0 {
		return out
	}
	report := func(id *ast.Ident) {
		if id != nil && importNames[id.Name] {
			out = append(out, ctx.warn(id.Pos(), "shadow of imported package '%s'", id.Name))
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.AssignStmt:
			if v.Tok == token.DEFINE {
				for _, lhs := range v.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						report(id)
					}
				}
			}
		case *ast.RangeStmt:
			if v.Tok == token.DEFINE {
				if id, ok := v.Key.(*ast.Ident); ok { report(id) }
				if id, ok := v.Value.(*ast.Ident); ok { report(id) }
			}
		case *ast.FuncDecl:
			// params / receiver / results names?
			// Check fields
			if v.Type != nil {
				if v.Type.Params != nil {
					for _, f := range v.Type.Params.List { for _, nm := range f.Names { report(nm) } }
				}
				if v.Type.Results != nil {
					for _, f := range v.Type.Results.List { for _, nm := range f.Names { report(nm) } }
				}
			}
			if v.Recv != nil {
				for _, f := range v.Recv.List { for _, nm := range f.Names { report(nm) } }
			}
		case *ast.FuncLit:
			if v.Type != nil {
				if v.Type.Params != nil { for _, f := range v.Type.Params.List { for _, nm := range f.Names { report(nm) } } }
				if v.Type.Results != nil { for _, f := range v.Type.Results.List { for _, nm := range f.Names { report(nm) } } }
			}
		case *ast.ValueSpec:
			// local? global vars also shadow import in file scope? importShadow may flag var decls
			for _, nm := range v.Names { report(nm) }
		}
		return true
	})
	return out
}

func checkIndexAlloc(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		fname := ctx.callFuncName(call)
		if fname != "strings.Index" && fname != "strings.IndexByte" && fname != "strings.IndexRune" {
			// Probe: strings.Index(string(x), y)
			if fname != "strings.Index" {
				return true
			}
		}
		// first arg is string(x) conversion where x is []byte
		conv, ok := unparen(call.Args[0]).(*ast.CallExpr)
		if !ok || len(conv.Args) != 1 {
			return true
		}
		// conv.Fun is type string
		if !isIdent(conv.Fun, "string") {
			// type conversion fun may be Ident string or type expr - nodeText
			if ctx.nodeText(conv.Fun) != "string" {
				return true
			}
		}
		x := conv.Args[0]
		sugCall := fmt.Sprintf("bytes.Index(%s, []byte(%s))", ctx.nodeText(x), ctx.nodeText(call.Args[1]))
		// But if IndexByte etc suggestion differs; for Index probe exact
		out = append(out, ctx.warn(call.Pos(), "consider replacing %s with %s", ctx.nodeText(call), sugCall))
		return true
	})
	return out
}

func checkInitClause(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		var init ast.Stmt
		var kind string
		var pos token.Pos
		switch v := n.(type) {
		case *ast.IfStmt:
			init = v.Init
			kind = "if"
			pos = v.Pos()
		case *ast.SwitchStmt:
			init = v.Init
			kind = "switch"
			pos = v.Pos()
		case *ast.ForStmt:
			// for init clause? initClause likely only if/switch? Probe had if
			return true
		default:
			return true
		}
		if init == nil {
			return true
		}
		// if init is SimpleStmt that is not assignment / incdec? Examples: sideEffect(); cond
		// AssignStmt and IncDec are allowed? Original doc: non-assignment statements inside if/switch init clause.
		// It flagged `if recurCount++; cond` in fmt - that's IncDec - Wait fmt_test line: initClause: consider to move `recurCount++` before if
		// So IncDec also flagged? Hmm
		switch init.(type) {
		case *ast.ExprStmt:
			out = append(out, ctx.warn(pos, "consider to move `%s` before %s", ctx.nodeText(init), kind))
		case *ast.IncDecStmt:
			out = append(out, ctx.warn(pos, "consider to move `%s` before %s", ctx.nodeText(init), kind))
		}
		return true
	})
	return out
}

func checkMethodExprCall(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 1 {
			return true
		}
		sel, ok := selectorOf(call.Fun)
		if !ok {
			return true
		}
		// foo.bar(f) where sel.X is a type name ident and first arg is receiver value
		// Type info: sel.X ident is a type name object
		id, ok := sel.X.(*ast.Ident)
		if !ok {
			return true
		}
		if ctx.pkg.TypesInfo == nil {
			return true
		}
		obj := ctx.pkg.TypesInfo.Uses[id]
		if obj == nil {
			return true
		}
		if _, isTypeName := obj.(*types.TypeName); !isTypeName {
			return true
		}
		// Check that call's first arg type matches that type (or pointer)
		recv := call.Args[0]
		// Message: consider to change `foo.bar` to `f.bar`
		out = append(out, ctx.warn(call.Pos(), "consider to change `%s` to `%s.%s`", ctx.nodeText(call.Fun), ctx.nodeText(recv), sel.Sel.Name))
		return true
	})
	return out
}

func checkNestingReduce(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		// for ... { if cond { many statements } }
		var body *ast.BlockStmt
		isRange := false
		switch v := n.(type) {
		case *ast.RangeStmt:
			body = v.Body
			isRange = true
		case *ast.ForStmt:
			body = v.Body
		default:
			return true
		}
		if body == nil || len(body.List) != 1 {
			return true
		}
		ifs, ok := body.List[0].(*ast.IfStmt)
		if !ok || ifs.Else != nil {
			return true
		}
		if len(ifs.Body.List) < paramNestingReduceBodyWidth {
			return true
		}
		// Also need ifs.Body at least bodyWidth statements - probe had 5 prints with default 5 flagged
		msg := "invert if cond, replace body with `continue`, move old body after the statement"
		if !isRange {
			// for loop also continue works
		}
		out = append(out, ctx.warn(ifs.Pos(), "%s", msg))
		return true
	})
	return out
}

func checkNilValReturn(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		// cond is x == nil
		bin, ok := unparen(ifs.Cond).(*ast.BinaryExpr)
		if !ok || bin.Op != token.EQL {
			return true
		}
		var varExpr ast.Expr
		if isNilExpr(bin.Y) {
			varExpr = bin.X
		} else if isNilExpr(bin.X) {
			varExpr = bin.Y
		} else {
			return true
		}
		// if body contains return varExpr (single return?)
		// Look direct statements
		if ifs.Body == nil {
			return true
		}
		for _, stmt := range ifs.Body.List {
			if ret, ok := stmt.(*ast.ReturnStmt); ok && len(ret.Results) >= 1 {
				// first result matching varExpr ?
				for _, res := range ret.Results {
					if ctx.exprEq(res, varExpr) {
						out = append(out, ctx.warn(ret.Pos(), "returned expr is always nil; replace %s with nil", ctx.nodeText(res)))
					}
				}
			}
		}
		return true
	})
	return out
}

func checkOctalLiteral(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// Go version matters: octal 0o introduced in Go 1.13; original likely checks if go version >=? If target Go version <1.13, maybe not flag?
	// If goVersionSet and (maj<1 or maj==1 && minor<13) skip?
	if goVersionSet {
		if goVersionMajor < 1 || (goVersionMajor == 1 && goVersionMinor < 13) {
			return out
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		bl, ok := n.(*ast.BasicLit)
		if !ok || bl.Kind != token.INT {
			return true
		}
		val := bl.Value
		// old style: 0 followed by octal digits 0-7, at least one digit, not 0o, 0x, 0b, and not single 0
		if len(val) >= 2 && val[0] == '0' && val[1] >= '0' && val[1] <= '7' {
			// ensure all chars are octal digits maybe underscores
			isOld := true
			for _, r := range val[1:] {
				if (r < '0' || r > '7') && r != '_' {
					isOld = false
					break
				}
			}
			if isOld {
				out = append(out, ctx.warn(bl.Pos(), "use new octal literal style, 0o%s", val[1:]))
			}
		}
		return true
	})
	return out
}

func checkParamTypeCombine(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	checkFuncType := func(ft *ast.FuncType, pos token.Pos, recv *ast.FieldList) {
		if ft == nil {
			return
		}
		// Need to detect adjacent fields with same type but separate names, or repeated single-name fields
		// Original triggers for: func(a int, b int, ...) / func(format string) (index int, wid int, ok bool) where results also combinable
		// It reports once per function with full suggested signature (including params and results combined).
		// Determine if any combining possible in Params or Results.
		canCombineParams := fieldListCanCombine(ctx, ft.Params)
		canCombineResults := fieldListCanCombine(ctx, ft.Results)
		if !canCombineParams && !canCombineResults {
			return
		}
		orig := buildFuncSignature(ctx, ft, recv, false)
		sug := buildFuncSignature(ctx, ft, recv, true)
		if orig == sug {
			return
		}
		out = append(out, ctx.warn(pos, "%s could be replaced with %s", orig, sug))
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			checkFuncType(v.Type, v.Pos(), v.Recv)
			// return false to avoid duplicate FuncType visit below? But Walk will still visit Type node as FuncType case and duplicate.
			// Our switch includes FuncType case; to avoid, we should not handle FuncType separately for FuncDecls.
			// Since Inspect visits children regardless, FuncType node will be visited next and check again with same pos (FuncType.Pos, not FuncDecl.Pos)
			// Problem: original position for FuncDecl is decl pos (1:1) not type pos. If FuncType check also runs, position would be slightly differ and duplicate.
			// So we will handle FuncType only if it's not part of FuncDecl/FuncLit? Hard.
			// Solution: Do NOT register FuncType handling in walk; only FuncDecl and FuncLit and maybe type declarations `type F func(...)`
		case *ast.FuncLit:
			checkFuncType(v.Type, v.Pos(), nil)
		}
		return true
	})
	// Handle named func types: type Handler func(a int, b int)
	if lf.AST != nil {
		for _, decl := range lf.AST.Decls {
			if gd, ok := decl.(*ast.GenDecl); ok {
				for _, spec := range gd.Specs {
					if ts, ok := spec.(*ast.TypeSpec); ok {
						if ft, ok := unparenType(ts.Type).(*ast.FuncType); ok {
							// check with pos of spec?
							// Original probably visits FuncType nodes... Position may be GenDecl pos
							// We'll add but might duplicate FuncDecl case if we also did - we didn't duplicate because walk didn't handle FuncType, so this is separate.
							checkFuncType(ft, ts.Pos(), nil)
						}
					}
				}
			}
		}
	}
	return out
}

func unparenType(e ast.Expr) ast.Expr { return unparen(e) }

func fieldListCanCombine(ctx *checkerContext, fl *ast.FieldList) bool {
	if fl == nil || len(fl.List) < 2 {
		return false
	}
	// Adjacent fields with same type text and both have names (at least 1 name each)
	for i := 0; i+1 < len(fl.List); i++ {
		a := fl.List[i]
		b := fl.List[i+1]
		if len(a.Names) == 0 || len(b.Names) == 0 {
			continue
		}
		if ctx.formatNode(a.Type) == ctx.formatNode(b.Type) {
			// But need handle variadic? merging variadic with non-variadic same type not allowed; formatNode includes ... so differs
			return true
		}
	}
	return false
}

func buildFuncSignature(ctx *checkerContext, ft *ast.FuncType, recv *ast.FieldList, combine bool) string {
	// Format: func(params) (results) - no name, no receiver? Probe: FuncDecl method? For method, orig maybe includes receiver? Unknown.
	// For plain functions, format as: func(a int, b int)
	// Results: if single unnamed result, just type without parentheses; if multiple or named, parens.
	var sb strings.Builder
	sb.WriteString("func")
	// receiver if any: prepend? Original for methods maybe "func (r T) (....)"? Unknown - include recv if present as (recv)
	if recv != nil && len(recv.List) > 0 {
		sb.WriteString("(")
		sb.WriteString(fieldListString(ctx, recv, false))
		sb.WriteString(") ")
	} else {
		// func types need '(' directly
	}
	sb.WriteString("(")
	sb.WriteString(fieldListString(ctx, ft.Params, combine))
	sb.WriteString(")")
	// results
	if ft.Results != nil && len(ft.Results.List) > 0 {
		// Determine if needs parens: more than one field, or one field with names, or multiple names
		needsParens := false
		if len(ft.Results.List) > 1 {
			needsParens = true
		} else if len(ft.Results.List) == 1 && len(ft.Results.List[0].Names) > 0 {
			needsParens = true
		} else if len(ft.Results.List) == 1 && len(ft.Results.List[0].Names) > 1 {
			needsParens = true
		}
		// Actually if combine changed structure, may need parens based on combined
		if combine {
			// combined results may become multi-name single field with names - still needs parens if names present
			// Our fieldListString combine will merge adjacent, but count names...
			// Keep logic: if original has names, parens.
		}
		if needsParens {
			sb.WriteString(" (")
			sb.WriteString(fieldListString(ctx, ft.Results, combine))
			sb.WriteString(")")
		} else {
			sb.WriteString(" ")
			sb.WriteString(fieldListString(ctx, ft.Results, combine))
		}
	}
	return sb.String()
}

func fieldListString(ctx *checkerContext, fl *ast.FieldList, combine bool) string {
	if fl == nil {
		return ""
	}
	type fieldRepr struct {
		names []string
		typ   string
	}
	var fields []fieldRepr
	for _, f := range fl.List {
		var names []string
		for _, n := range f.Names {
			names = append(names, n.Name)
		}
		fields = append(fields, fieldRepr{names: names, typ: ctx.formatNode(f.Type)})
	}
	if combine {
		var merged []fieldRepr
		for _, fr := range fields {
			if len(merged) > 0 && len(fr.names) > 0 && len(merged[len(merged)-1].names) > 0 && merged[len(merged)-1].typ == fr.typ {
				merged[len(merged)-1].names = append(merged[len(merged)-1].names, fr.names...)
			} else {
				merged = append(merged, fr)
			}
		}
		fields = merged
	}
	var parts []string
	for _, fr := range fields {
		if len(fr.names) == 0 {
			parts = append(parts, fr.typ)
		} else {
			parts = append(parts, strings.Join(fr.names, ", ")+" "+fr.typ)
		}
	}
	return strings.Join(parts, ", ")
}

func checkPreferDecodeRune(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		idx, ok := n.(*ast.IndexExpr)
		if !ok {
			return true
		}
		// []rune(s)[0]
		conv, ok := unparen(idx.X).(*ast.CallExpr)
		if !ok || len(conv.Args) != 1 {
			return true
		}
		// conv.Fun is []rune type: Slice type with elt rune
		if ctx.nodeText(conv.Fun) != "[]rune" {
			// format node may be []rune
			if ctx.formatNode(conv.Fun) != "[]rune" {
				return true
			}
		}
		// index must be 0
		if v, ok := constIntValue(idx.Index); !ok || v != 0 {
			return true
		}
		out = append(out, ctx.warn(idx.Pos(), "consider replacing %s with utf8.DecodeRuneInString(%s)", ctx.nodeText(idx), ctx.nodeText(conv.Args[0])))
		return true
	})
	return out
}

func checkPreferFilepathJoin(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || bin.Op != token.ADD {
			return true
		}
		// Pattern x + string(os.PathSeparator) + y  : outer bin Y is y, X is (x + string(...))
		// Collect flattened + chain
		parts := flattenAdd(bin)
		if len(parts) != 3 {
			return true
		}
		// middle part is string(os.PathSeparator) conversion
		mid := parts[1]
		conv, ok := unparen(mid).(*ast.CallExpr)
		if !ok || len(conv.Args) != 1 {
			return true
		}
		if !isIdent(conv.Fun, "string") && ctx.nodeText(conv.Fun) != "string" {
			return true
		}
		sel, ok := selectorOf(unparen(conv.Args[0]))
		if !ok || sel.Sel.Name != "PathSeparator" {
			return true
		}
		// sel.X should be os package
		out = append(out, ctx.warn(bin.Pos(), "filepath.Join(%s, %s) should be preferred to the %s", ctx.nodeText(parts[0]), ctx.nodeText(parts[2]), ctx.nodeText(bin)))
		return true
	})
	return out
}

func flattenAdd(e ast.Expr) []ast.Expr {
	e = unparen(e)
	if bin, ok := e.(*ast.BinaryExpr); ok && bin.Op == token.ADD {
		left := flattenAdd(bin.X)
		right := flattenAdd(bin.Y)
		return append(left, right...)
	}
	return []ast.Expr{e}
}

func checkPreferFprint(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// w.Write([]byte(fmt.Sprintf(...))) -> fmt.Fprintf(w, ...)
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		sel, ok := selectorOf(call.Fun)
		if !ok || sel.Sel.Name != "Write" {
			return true
		}
		// arg is []byte(fmt.Sprintf / Sprint / Sprintln)
		conv, ok := unparen(call.Args[0]).(*ast.CallExpr)
		if !ok || len(conv.Args) != 1 {
			return true
		}
		if ctx.formatNode(conv.Fun) != "[]byte" && ctx.nodeText(conv.Fun) != "[]byte" {
			return true
		}
		inner, ok := unparen(conv.Args[0]).(*ast.CallExpr)
		if !ok || len(inner.Args) < 1 {
			return true
		}
		fname := ctx.callFuncName(inner)
		var replacement string
		var innerName string
		switch fname {
		case "fmt.Sprintf":
			replacement = "Fprintf"
			innerName = "Sprintf"
		case "fmt.Sprint":
			replacement = "Fprint"
			innerName = "Sprint"
		case "fmt.Sprintln":
			replacement = "Fprintln"
			innerName = "Sprintln"
		default:
			return true
		}
		_ = innerName
		// Build suggestion: fmt.Fprintf(w, "%x",10) -- note args formatting: original message in probe:
		// fmt.Fprintf(w, "%x",10) should be preferred to the w.Write([]byte(fmt.Sprintf("%x",10)))
		// Notice no space after comma in second arg list? printer formatNode gives "%x", 10 with space.
		// Original suggestion arguments appear without spaces? That came from their template using ??? Probe: `fmt.Fprintf(w, "%x",10)` - after comma no space for args beyond first? Hmm first comma has space, rest no?
		// They may construct suggestion by joining args with "," (no space) for inner args but receiver with ", "
		// Let's replicate: fmt.Fprintf(<recv>, <arg0>,<arg1>...)
		argsTexts := []string{}
		for _, a := range inner.Args {
			argsTexts = append(argsTexts, ctx.nodeText(a))
		}
		sug := fmt.Sprintf("fmt.%s(%s, %s)", replacement, ctx.nodeText(sel.X), strings.Join(argsTexts, ","))
		out = append(out, ctx.warn(call.Pos(), "%s should be preferred to the %s", sug, ctx.nodeText(call)))
		return true
	})
	return out
}

