func checkRegexpSimplify(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 1 {
			return true
		}
		fname := ctx.callFuncName(call)
		if !strings.HasPrefix(fname, "regexp.") {
			return true
		}
		pat, ok := stringLitValue(call.Args[0])
		if !ok {
			return true
		}
		simplified, changed := simplifyRegexp(pat)
		if changed {
