func checkSliceClear(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		fs, ok := n.(*ast.ForStmt)
		if !ok || fs.Body == nil {
			return true
		}
		// for i:=0; i<len(buf); i++ { buf[i]=0 }
		// init: i:=0, cond i < len(buf), post i++
		initAs, ok := fs.Init.(*ast.AssignStmt)
		if !ok || len(initAs.Rhs) != 1 {
			return true
		}
		if v, ok := constIntValue(initAs.Rhs[0]); !ok || v != 0 {
			return true
		}
		condBin, ok := unparen(fs.Cond).(*ast.BinaryExpr)
		if !ok || condBin.Op != token.LSS {
			return true
		}
		// cond Y is len(expr)
		call, ok := unparen(condBin.Y).(*ast.CallExpr)
		if !ok || !isLenCall(ctx, call) {
			return true
		}
		bufExpr := call.Args[0]
		// body single stmt buf[i]=0
		if len(fs.Body.List) != 1 {
			return true
		}
		as, ok := fs.Body.List[0].(*ast.AssignStmt)
		if !ok || len(as.Lhs) != 1 || len(as.Rhs) != 1 {
			return true
		}
		idx, ok := unparen(as.Lhs[0]).(*ast.IndexExpr)
		if !ok {
			return true
		}
		if !ctx.exprEq(idx.X, bufExpr) {
			return true
		}
		if v, ok := constIntValue(as.Rhs[0]); !ok || v != 0 {
			return true
		}
		out = append(out, ctx.warn(fs.Pos(), "rewrite as for-range so compiler can recognize this pattern"))
		return true
	})
	return out
}

func checkSloppyReassign(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || ifs.Init == nil {
			return true
		}
		as, ok := ifs.Init.(*ast.AssignStmt)
		if !ok || as.Tok != token.ASSIGN {
			return true
		}
		// err = f(); cond uses err? Message: re-assignment to `err` can be replaced with `err := ff()`
		// Position: ifs.Init? Probe 3:36 - IfStmt starts at if, init at err = ...
		// warn at as.Pos()
		if len(as.Lhs) == 1 && len(as.Rhs) == 1 {
			out = append(out, ctx.warn(as.Pos(), "re-assignment to `%s` can be replaced with `%s := %s`", ctx.nodeText(as.Lhs[0]), ctx.nodeText(as.Lhs[0]), ctx.nodeText(as.Rhs[0])))
		}
		return true
	})
	return out
}

func checkSortSlice(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		fname := ctx.callFuncName(call)
		if fname != "sort.Slice" && fname != "sort.SliceStable" && fname != "sort.SliceIsSorted" {
			return true
		}
		sliceExpr := call.Args[0]
		fl, ok := unparen(call.Args[1]).(*ast.FuncLit)
		if !ok || fl.Body == nil {
			return true
		}
		// find comparisons in fl body: expr[i] < expr[j] where expr is not sliceExpr
		// Probe: keys[i] < keys[j] while sorting xs
		// Locate return statements
		reported := false
		ast.Inspect(fl.Body, func(nn ast.Node) bool {
			if reported {
				return false
			}
			bin, ok := nn.(*ast.BinaryExpr)
			if !ok {
				return true
			}
			// find index exprs in bin
			var idxExprs []*ast.IndexExpr
			ast.Inspect(bin, func(nnn ast.Node) bool {
				if ie, ok := nnn.(*ast.IndexExpr); ok {
					idxExprs = append(idxExprs, ie)
				}
				return true
			})
			for _, ie := range idxExprs {
				if !ctx.exprEq(ie.X, sliceExpr) {
					out = append(out, ctx.warn(call.Pos(), "cmp func must use %s slice in comparison", ctx.nodeText(sliceExpr)))
					reported = true
					break
				}
			}
			return true
		})
		return true
	})
	return out
}

func checkSprintfQuotedString(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 1 {
			return true
		}
		fname := ctx.callFuncName(call)
		if fname != "fmt.Sprintf" && fname != "fmt.Printf" && fname != "fmt.Fprintf" {
			return true
		}
		// format arg index
		formatIdx := 0
		if fname == "fmt.Fprintf" {
			formatIdx = 1
		}
		if len(call.Args) <= formatIdx {
			return true
		}
		format, ok := stringLitValue(call.Args[formatIdx])
		if !ok {
			return true
		}
		if strings.Contains(format, "\"%s\"") || strings.Contains(format, "'%s'") {
			// Message: use %q instead of "%s" for quoted strings
			out = append(out, ctx.warn(call.Args[formatIdx].Pos(), "use %%q instead of \"%s\" for quoted strings"))
		}
		return true
	})
	return out
}

func checkSqlQuery(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 1 {
			return true
		}
		sel, ok := selectorOf(call.Fun)
		if !ok || sel.Sel.Name != "Query" {
			return true
		}
		// receiver type must be *sql.DB or sql.Tx etc: check receiver type name contains sql. or DB?
		// Use type info: receiver type's package is database/sql
		t := ctx.exprType(sel.X)
		isDB := false
		if t != nil {
			s := t.String()
			if strings.Contains(s, "database/sql") || strings.HasSuffix(s, ".DB") || strings.Contains(s, "*sql.DB") {
				isDB = true
			}
		} else {
			// fallback: selector X name is db?
			if name, ok := identName(sel.X); ok && (name == "db" || name == "tx") {
				isDB = true
			}
		}
		if !isDB {
			return true
		}
		query, ok := stringLitValue(call.Args[0])
		if !ok {
			// QueryContext first arg is ctx, query is second
			if len(call.Args) >= 2 {
				query, ok = stringLitValue(call.Args[1])
			}
		}
		if !ok {
			return true
		}
		upper := strings.ToUpper(strings.TrimSpace(query))
		if strings.HasPrefix(upper, "UPDATE") || strings.HasPrefix(upper, "INSERT") || strings.HasPrefix(upper, "DELETE") {
			// Message probe: use db.Exec() if returned result is not needed - where db is receiver text
			out = append(out, ctx.warn(call.Pos(), "use %s.Exec() if returned result is not needed", ctx.nodeText(sel.X)))
		}
		return true
	})
	return out
}

func checkStringConcatSimplify(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		if ctx.callFuncName(call) != "strings.Join" {
			return true
		}
		cl, ok := unparen(call.Args[0]).(*ast.CompositeLit)
		if !ok {
			return true
		}
		sep, ok := stringLitValue(call.Args[1])
		if !ok {
			return true
		}
		// Elements must be (?) at least 2 ?
		if len(cl.Elts) < 2 {
			return true
		}
		var parts []string
		for _, el := range cl.Elts {
			parts = append(parts, ctx.nodeText(el))
		}
		sepLit := strconv.Quote(sep)
		sug := strings.Join(parts, " + "+sepLit+" + ")
		out = append(out, ctx.warn(call.Pos(), "suggestion: %s", sug))
		return true
	})
	return out
}

func checkStringXbytes(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
