		if !ok {
			return true
		}
		// copy(b, []byte(s)) / copy(b, string(...)) patterns and also generic conversion []byte(s) where? Probe:
		// First function copy: flagged []byte(s) for copy second arg
		// Second function return []byte(s) not flagged (maybe because conversion itself needed)
		// So check only inside copy / append (?) 
		if id, ok := unparen(call.Fun).(*ast.Ident); ok && id.Name == "copy" && len(call.Args) == 2 {
