						}
					}
					if isIdent(conv.Fun, "string") {
						// string([]byte) where arg is []byte sequence?
					}
				}
			}
		}
		return true
	})
	return out
}

func checkStringsCompare(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		// strings.Compare(x,y) == 0 etc, also <0, >0 etc
		extract := func() (*ast.CallExpr, int64, token.Token, bool) {
			// bin X is compare call, Y is const
			if call, ok := unparen(bin.X).(*ast.CallExpr); ok && ctx.callFuncName(call) == "strings.Compare" {
				if v, ok := constIntValue(bin.Y); ok {
					return call, v, bin.Op, true
				}
			}
			if call, ok := unparen(bin.Y).(*ast.CallExpr); ok && ctx.callFuncName(call) == "strings.Compare" {
				if v, ok := constIntValue(bin.X); ok {
					// flipped op
					return call, v, flipOp(bin.Op), true
				}
			}
			return nil, 0, token.ILLEGAL, false
		}
		call, cval, op, ok := extract()
		if !ok || cval != 0 || len(call.Args) != 2 {
			return true
		}
		x := ctx.nodeText(call.Args[0])
		y := ctx.nodeText(call.Args[1])
		var opStr string
		switch op {
		case token.EQL:
			opStr = "=="
		case token.NEQ:
			opStr = "!="
		case token.LSS:
			opStr = "<"
		case token.GTR:
			opStr = ">"
		case token.LEQ:
			opStr = "<="
		case token.GEQ:
			opStr = ">="
		default:
			return true
		}
		out = append(out, ctx.warn(bin.Pos(), "suggestion: %s %s %s", x, opStr, y))
		return true
	})
	return out
}

func checkSyncMapLoadAndDelete(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// Pattern in separate statements; simpler: detect Load call assigned, then later Delete same receiver/key in same function
	// For our implementation, process assignment statements inside blocks
	walkFile(lf, func(n ast.Node) bool {
		// IfStmt with LoadAssign in Init? Pattern from docs: v,ok:=m.Load(k); if ok { m.Delete(k); f(v); }
		// Implement inside Func bodies scanning stmt lists
		return true
	})
	// Process blocks
	processList := func(list []ast.Stmt) {
		for i := 0; i < len(list); i++ {
			// load assign statement
			as, ok := list[i].(*ast.AssignStmt)
			if !ok || len(as.Rhs) != 1 {
				continue
			}
			call, ok := unparen(as.Rhs[0]).(*ast.CallExpr)
			if !ok {
				continue
			}
			sel, ok := selectorOf(call.Fun)
			if !ok || sel.Sel.Name != "Load" || len(call.Args) != 1 {
				continue
			}
			// Search subsequent statements (including inside IfStmt bodies) for Delete
			for j := i + 1; j < len(list); j++ {
				found := false
				ast.Inspect(list[j], func(nn ast.Node) bool {
					if c2, ok := nn.(*ast.CallExpr); ok {
						if s2, ok := selectorOf(c2.Fun); ok && s2.Sel.Name == "Delete" && len(c2.Args) == 1 {
							if ctx.exprEq(s2.X, sel.X) && ctx.exprEq(c2.Args[0], call.Args[0]) {
								found = true
							}
						}
					}
					return true
				})
				if found {
					out = append(out, ctx.warn(call.Pos(), "use %s.LoadAndDelete to perform load+delete operations atomically", ctx.nodeText(sel.X)))
					break
				}
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.BlockStmt:
			processList(v.List)
		case *ast.CaseClause:
			processList(v.Body)
		}
		return true
	})
	return out
}

func checkTimeExprSimplify(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || (bin.Op != token.QUO && bin.Op != token.MUL) {
			return true
		}
		// t.Unix() /1000 -> UnixMilli, /1e6 -> UnixMicro, *1000 -> ??? maybe also seconds ?
		call, ok := unparen(bin.X).(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := selectorOf(call.Fun)
		if !ok || len(call.Args) != 0 {
			return true
		}
		method := sel.Sel.Name
		if method != "Unix" && method != "UnixMilli" && method != "UnixMicro" {
			return true
		}
		v, ok := constIntValue(bin.Y)
		if !ok {
			return true
		}
		recv := ctx.nodeText(sel.X)
		if method == "Unix" && bin.Op == token.QUO && v == 1000 {
			out = append(out, ctx.warn(bin.Pos(), "use %s.UnixMilli() instead of %s", recv, ctx.nodeText(bin)))
		} else if method == "Unix" && bin.Op == token.QUO && v == 1000000 {
			out = append(out, ctx.warn(bin.Pos(), "use %s.UnixMicro() instead of %s", recv, ctx.nodeText(bin)))
		} else if method == "Unix" && bin.Op == token.QUO && v == 1000000000 {
			// UnixNano?
		} else if method == "UnixMilli" && bin.Op == token.QUO && v == 1000 {
			out = append(out, ctx.warn(bin.Pos(), "use %s.UnixMicro() instead of %s", recv, ctx.nodeText(bin)))
			// Actually UnixMilli()/1000 = seconds -> Unix() ?
			// Correction: UnixMilli/1000 is seconds, suggestion should be Unix() - We'll refine later
		}
		return true
	})
	return out
}

func checkTodo(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	for _, cg := range lf.AST.Comments {
		for _, c := range cg.List {
			if !strings.HasPrefix(c.Text, "//") {
				continue
			}
			text := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
			// starts with TODO / FIXME / BUG
			for _, kw := range []string{"TODO", "FIXME", "BUG"} {
				if text == kw || (strings.HasPrefix(text, kw) && (len(text) == len(kw) || text[len(kw)] == ' ' || text[len(kw)] == ':' || text[len(kw)] == '(')) {
					// has detail if after kw there is (assignee): or : detail with length?
					rest := strings.TrimSpace(text[len(kw):])
					hasDetail := false
					if strings.HasPrefix(rest, "(") && strings.Contains(rest, "):") {
						// TODO(admin): detail - rest after ): is detail?
						idx := strings.Index(rest, "):")
						if len(strings.TrimSpace(rest[idx+2:])) > 0 {
							hasDetail = true
						}
					} else if strings.HasPrefix(rest, ":") && len(strings.TrimSpace(rest[1:])) > 0 {
						hasDetail = true
					}
					if !hasDetail {
						out = append(out, ctx.warn(c.Pos(), "may want to add detail/assignee to this TODO/FIXME/BUG comment"))
					}
					break
				}
			}
		}
	}
	return out
}

func checkTruncateCmp(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch bin.Op {
		case token.LSS, token.GTR, token.LEQ, token.GEQ, token.EQL, token.NEQ:
		default:
			return true
		}
		// X is conversion to smaller int, Y is other int of larger (?) Probe int16(x) < y where x int32, y int16 - conversion to int16, other is int16 - wait suggestion cast other to int32.
		// Pattern: castExpr (type conversion) on one side, other side's type has smaller bits than source of cast.
		checkSide := func(convExpr ast.Expr, other ast.Expr, convOnLeft bool) {
			call, ok := unparen(convExpr).(*ast.CallExpr)
			if !ok || len(call.Args) != 1 {
				return
			}
			// conversion type is call.Fun type expr
			convType := ctx.exprType(call.Fun) // type of Fun as type? TypeOf for type expr returns that type
			if convType == nil {
				// try using type of whole call
				convType = ctx.exprType(call)
			}
			srcType := ctx.exprType(call.Args[0])
			otherType := ctx.exprType(other)
			if convType == nil || srcType == nil || otherType == nil {
				return
			}
			convBits := intBits(convType)
			srcBits := intBits(srcType)
			otherBits := intBits(otherType)
			if convBits == 0 || srcBits == 0 || otherBits == 0 {
				return
			}
			if paramTruncateCmpSkipArch {
				if isArchDependent(convType) || isArchDependent(srcType) || isArchDependent(otherType) {
					// Still allow if all are sized? Probe used int32/int16 all sized - ok.
					// Skip only if any is arch dependent (int/uint/uintptr)
					// But need to know types names: check basics kind
					if isArchKind(convType) || isArchKind(srcType) || isArchKind(otherType) {
						return
					}
				}
			}
			if convBits < srcBits && otherBits <= convBits {
				// Warning: truncation in comparison 32->16 bit; cast the other operand to int32 instead
				out = append(out, ctx.warn(bin.Pos(), "truncation in comparison %d->%d bit; cast the other operand to %s instead", srcBits, convBits, typeDisplay(srcType)))
			}
		}
		checkSide(bin.X, bin.Y, true)
		checkSide(bin.Y, bin.X, false)
		return true
	})
	return out
}

func intBits(t types.Type) int {
	b, ok := t.Underlying().(*types.Basic)
	if !ok {
		return 0
	}
	switch b.Kind() {
	case types.Int8, types.Uint8:
		return 8
	case types.Int16, types.Uint16:
		return 16
	case types.Int32, types.Uint32:
		return 32
	case types.Int64, types.Uint64:
		return 64
	case types.Int, types.Uint, types.Uintptr:
		return 64 // arch dependent size on amd64
	}
	return 0
}
func isArchDependent(t types.Type) bool { return isArchKind(t) }
func isArchKind(t types.Type) bool {
	b, ok := t.Underlying().(*types.Basic)
	if !ok {
		return false
	}
	return b.Kind() == types.Int || b.Kind() == types.Uint || b.Kind() == types.Uintptr || b.Kind() == types.UntypedInt
}
func typeDisplay(t types.Type) string {
	// For int32 type, String returns "int32"
	return t.String()
}

func checkTypeAssertChain(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// If-else chain where each if init is type assertion to diff types on same expr
	// Re-use ifElseChain counting but specific
	walkFile(lf, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok {
			return true
		}
		// Only roots: determine if this if is else-if child
		// We can't know parent; but we can attempt to detect chain from this if and if it looks like assert chain with at least 2 (?) thresholds.
		// To avoid duplicate for else-if nodes, we will track roots via a set built earlier... Simpler: in walk, if chain length >=2 and this if's init is type assertion, warn - but else-if node will also have chain length 1 and won't warn if threshold =2 else-ifs total?
		// Probe: chain with 1 else-if (2 assertions total) flagged. So threshold is number of assertions >=2? Else-if subchain would have only 1 assertion in its own chain (itself) so not flagged.
		count := 0
		cur := ifs
		var base ast.Expr
		for cur != nil {
			// init must be assignment with type assertion
			has := false
			if cur.Init != nil {
				if as, ok := cur.Init.(*ast.AssignStmt); ok && len(as.Rhs) == 1 {
					if ta, ok := unparen(as.Rhs[0]).(*ast.TypeAssertExpr); ok {
						if base == nil {
							base = ta.X
							has = true
						} else if ctx.exprEq(ta.X, base) {
							has = true
						}
					}
				}
			}
			if !has {
				break
			}
			count++
			if cur.Else != nil {
				if nxt, ok := cur.Else.(*ast.IfStmt); ok {
					cur = nxt
					continue
				}
			}
			break
		}
		if count >= 3 {
			// Doc says 3 assertions (T1,T2,T3) ??? probe with 2 flagged (T1,T2) count=2 but flagged
			// We'll lower to 2
		}
		if count >= 2 {
			out = append(out, ctx.warn(ifs.Pos(), "rewrite if-else to type switch statement"))
		}
		return true
	})
	return out
}

func checkTypeDefFirst(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	// Collect method receiver type names encountered before their type definition (GenDecl TypeSpec)
	seenMethod := map[string]bool{}
	// iterate decls in order
	for _, decl := range lf.AST.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			if d.Recv != nil && len(d.Recv.List) > 0 {
				recvType := receiverBaseName(ctx.nodeText(d.Recv.List[0].Type))
				if recvType != "" {
					seenMethod[recvType] = true
				}
			}
		case *ast.GenDecl:
			if d.Tok == token.TYPE {
				for _, spec := range d.Specs {
					if ts, ok := spec.(*ast.TypeSpec); ok {
						if seenMethod[ts.Name.Name] {
							out = append(out, ctx.warn(d.Pos(), "definition of type '%s' should appear before its methods", ts.Name.Name))
						}
					}
				}
			}
		}
	}
	return out
}

func receiverBaseName(s string) string {
	s = strings.TrimSpace(s)
	s = strings.TrimPrefix(s, "*")
	// generics [..]
	if idx := strings.Index(s, "["); idx >= 0 {
		s = s[:idx]
	}
	// package qualifier
	if idx := strings.LastIndex(s, "."); idx >= 0 {
		s = s[idx+1:]
	}
	return s
}

func checkTypeUnparen(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	for _, decl := range lf.AST.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.TYPE {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			// check if type expr contains parentheses around types: [](func([](func())))
			if containsParenType(ts.Type) {
				sug := removeParenTypes(ts.Type, ctx)
				out = append(out, ctx.warn(ts.Pos(), "could simplify %s to %s", ctx.nodeText(ts.Type), sug))
			}
		}
	}
	// Also other type expressions? func params etc? Probe only type decl.
	return out
}

func containsParenType(e ast.Expr) bool {
	found := false
	ast.Inspect(e, func(n ast.Node) bool {
		if _, ok := n.(*ast.ParenExpr); ok {
			found = true
		}
		return true
	})
	return found
}

func removeParenTypes(e ast.Expr, ctx *checkerContext) string {
	// Use printer after stripping parens AST clone? Easier: format node text and remove parentheses that are around types?
	// For the probe type [](func([](func()))) -> []func([]func())
	// Our formatNode for ParenExpr will keep parentheses. Need construct a cleaned representation by traversing and building string.
	return buildTypeString(e, ctx)
}

func buildTypeString(e ast.Expr, ctx *checkerContext) string {
	switch t := e.(type) {
	case *ast.ParenExpr:
		return buildTypeString(t.X, ctx)
	case *ast.ArrayType:
		length := ""
		if t.Len != nil {
			length = ctx.nodeText(t.Len)
		}
		return "[" + length + "]" + buildTypeString(t.Elt, ctx)
	case *ast.FuncType:
		params := ""
		if t.Params != nil {
			var parts []string
			for _, f := range t.Params.List {
				// unnamed
				parts = append(parts, buildTypeString(f.Type, ctx))
				// if names? for type decl func signature in type context names are rarely
				if len(f.Names) > 0 {
					// Reconstruct: names type
					// override
					parts[len(parts)-1] = namesString(f.Names) + " " + buildTypeString(f.Type, ctx)
				}
			}
			params = strings.Join(parts, ", ")
		}
		res := ""
		if t.Results != nil && len(t.Results.List) > 0 {
			if len(t.Results.List) == 1 && len(t.Results.List[0].Names) == 0 {
				res = " " + buildTypeString(t.Results.List[0].Type, ctx)
			} else {
				var parts []string
				for _, f := range t.Results.List {
					parts = append(parts, buildTypeString(f.Type, ctx))
				}
				res = " (" + strings.Join(parts, ", ") + ")"
			}
		}
		return "func(" + params + ")" + res
	default:
		return ctx.nodeText(e)
	}
}
func namesString(names []*ast.Ident) string {
	var ss []string
	for _, n := range names {
		ss = append(ss, n.Name)
	}
	return strings.Join(ss, ", ")
}

func checkUncheckedInlineErr(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || ifs.Init == nil || ifs.Cond == nil {
			return true
		}
		as, ok := ifs.Init.(*ast.AssignStmt)
		if !ok || len(as.Lhs) != 1 {
			return true
		}
		errVar, ok := as.Lhs[0].(*ast.Ident)
		if !ok {
			return true
		}
		// RHS must be a call returning error? assume if var name contains err or RHS call
		// Condition must be a binary comparison involving a different variable (not errVar) against nil
		bin, ok := unparen(ifs.Cond).(*ast.BinaryExpr)
		if !ok {
			return true
		}
		condUsesErr := false
		otherVar := ""
		ast.Inspect(bin, func(nn ast.Node) bool {
			if id, ok := nn.(*ast.Ident); ok {
				if id.Name == errVar.Name {
					condUsesErr = true
				} else if id.Name != "nil" && otherVar == "" {
					// might be other error var
					otherVar = id.Name
				}
			}
			return true
		})
		if condUsesErr {
			return true
		}
		// Also ensure condition is checking something != nil or == nil
		if bin.Op != token.NEQ && bin.Op != token.EQL {
			return true
		}
		if otherVar == "" {
			return true
		}
		out = append(out, ctx.warn(ifs.Init.Pos(), "%s error is unchecked, maybe intended to check it instead of %s", errVar.Name, otherVar))
		return true
	})
	return out
}

func checkUnlabelStmt(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ls, ok := n.(*ast.LabeledStmt)
		if !ok {
			return true
		}
		// label is redundant if it's only used by a single break/continue directly targeting it and that statement would target same loop without label?
		// Probing: derp: for ... { if x==0 { break derp } } - label used once for break inside immediate loop.
		// Count uses of label in its statement
		label := ls.Label.Name
		uses := 0
		ast.Inspect(ls.Stmt, func(nn ast.Node) bool {
			if bs, ok := nn.(*ast.BranchStmt); ok && bs.Label != nil && bs.Label.Name == label {
				uses++
			}
			return true
		})
		if uses <= 1 {
			out = append(out, ctx.warn(ls.Pos(), "label %s is redundant", label))
		}
		return true
	})
	return out
}

func checkUnnamedResult(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	checkFunc := func(ft *ast.FuncType, pos token.Pos, exported bool, name string) {
		if ft == nil || ft.Results == nil {
			return
		}
		if len(ft.Results.List) == 0 {
			return
		}
		// Count results: fields with names vs unnamed
		unnamedCount := 0
		total := 0
		for _, f := range ft.Results.List {
			if len(f.Names) == 0 {
				unnamedCount++
				total++
			} else {
				total += len(f.Names)
			}
		}
		if unnamedCount == 0 {
			return
		}
		// Criteria: at least 2 results? Probe: func f() (float64,float64) 2 fields unnamed -> flagged, Foo() (int,int) flagged even though checkExported false default? Wait probe: both f and Foo flagged despite param checkExported false (default false - "whether to check exported functions" default false meaning exported are NOT checked? But Foo was flagged in my probe with default enable unnamedResults - I enabled specifically, param default false. If checkExported false meant exported skipped, Foo should not flagged. Yet it was. Means parameter semantics reversed: checkExported false = ??? Or unnamedResult check applies to exported unless checkExported false ??? Confusing.
		// In fmt scan: paramTypeCombine etc. For unnamedResult in fmt? Not.
		// Probe more in refinement.
		if total >= 2 {
			out = append(out, ctx.warn(pos, "consider giving a name to these results"))
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			exp := v.Name != nil && ast.IsExported(v.Name.Name)
			name := ""
			if v.Name != nil { name = v.Name.Name }
			checkFunc(v.Type, v.Pos(), exp, name)
		case *ast.FuncLit:
			checkFunc(v.Type, v.Pos(), false, "")
		}
		return true
	})
	return out
}

func checkUnnecessaryBlock(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		// BlockStmt that is a standalone statement inside another Block and does not introduce declarations?
		// ast walk visits Block as node for FuncBody as well - standalone blocks appear as a statement in a parent Block list.
		// We need parent info: Process blocks' statement lists
		if block, ok := n.(*ast.BlockStmt); ok {
			for _, stmt := range block.List {
				if inner, ok := stmt.(*ast.BlockStmt); ok {
					// check if inner has definitions (declares variables)
					hasDefs := false
					ast.Inspect(inner, func(nn ast.Node) bool {
						switch nn.(type) {
						case *ast.DeclStmt, *ast.AssignStmt:
							// AssignStmt with := is definition, = is not
							if as, ok := nn.(*ast.AssignStmt); ok && as.Tok == token.DEFINE {
								hasDefs = true
							}
							if _, ok := nn.(*ast.DeclStmt); ok {
								hasDefs = true
							}
						}
						return true
					})
					if !hasDefs {
						out = append(out, ctx.warn(inner.Pos(), "block doesn't have definitions, can be simply deleted"))
					}
				}
			}
		}
		return true
	})
	return out
}

func checkUnnecessaryDefer(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// defer as last statement in a function body (BlockStmt)
	walkFile(lf, func(n ast.Node) bool {
		var body *ast.BlockStmt
		switch v := n.(type) {
		case *ast.FuncDecl:
			body = v.Body
		case *ast.FuncLit:
			body = v.Body
		default:
			return true
		}
		if body == nil || len(body.List) == 0 {
			return true
		}
		last := body.List[len(body.List)-1]
		if d, ok := last.(*ast.DeferStmt); ok {
			out = append(out, ctx.warn(d.Pos(), "%s is placed just before return", ctx.nodeText(d)))
			// NodeText for DeferStmt includes "defer os.Remove(fn)" - probe message: defer os.Remove(fn) is placed...
			// Our nodeText for stmt includes exactly that.
		}
		return true
	})
	return out
}

func checkWeakCond(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || bin.Op != token.LAND {
			return true
		}
		// pattern: xs != nil && xs[0] != nil (or any index access)
		left, ok1 := unparen(bin.X).(*ast.BinaryExpr)
		if !ok1 || left.Op != token.NEQ {
			return true
		}
		if !isNilExpr(left.Y) && !isNilExpr(left.X) {
			return true
		}
		var sliceExpr ast.Expr
		if isNilExpr(left.Y) { sliceExpr = left.X } else { sliceExpr = left.Y }
		// right side contains index expr on sliceExpr
		found := false
		ast.Inspect(bin.Y, func(nn ast.Node) bool {
			if ie, ok := nn.(*ast.IndexExpr); ok && ctx.exprEq(ie.X, sliceExpr) {
				found = true
			}
			return true
		})
		if found {
			out = append(out, ctx.warn(bin.Pos(), "suspicious `%s`; nil check may not be enough, check for len", ctx.nodeText(bin)))
		}
		return true
	})
	return out
}

func checkWhyNoLint(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	for _, cg := range lf.AST.Comments {
		for _, c := range cg.List {
			if !strings.HasPrefix(c.Text, "//") {
				continue
			}
			text := strings.TrimSpace(strings.TrimPrefix(c.Text, "//"))
			if text == "nolint" || strings.HasPrefix(text, "nolint:") || strings.HasPrefix(text, "nolint ") {
				// has explanation if after nolint there is // reason or ":"? Probe: //nolint (no), //nolint // reason (yes)
				// text after nolint
				rest := strings.TrimSpace(strings.TrimPrefix(text, "nolint"))
				// rest may be ":checkname" etc - not explanation
				// Explanation is separated by // in original comment: c.Text contains second //
				// c.Text example "//nolint // reason" -> after first //, text = "nolint // reason"
				if strings.Contains(text, "//") {
					continue
				}
				if strings.HasPrefix(rest, "//") {
					continue
				}
				out = append(out, ctx.warn(c.Pos(), "include an explanation for nolint directive"))
			}
		}
	}
	return out
}

func checkYoda(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok {
			return true
		}
		switch bin.Op {
		case token.EQL, token.NEQ, token.LSS, token.GTR, token.LEQ, token.GEQ:
		default:
			return true
		}
		// left is constant (nil or literal), right is non-const
		if !isConstExpr(ctx, bin.X) {
			return true
		}
		if isConstExpr(ctx, bin.Y) {
			return true
		}
		// Suggestion: swap and flip op if relational
		newOp := bin.Op
		if bin.Op == token.LSS || bin.Op == token.GTR || bin.Op == token.LEQ || bin.Op == token.GEQ {
			newOp = flipOp(bin.Op)
		}
		sug := fmt.Sprintf("%s %s %s", ctx.nodeText(bin.Y), newOp.String(), ctx.nodeText(bin.X))
		out = append(out, ctx.warn(bin.Pos(), "consider to change order in expression to %s", sug))
		return true
	})
	return out
}

func isConstExpr(ctx *checkerContext, e ast.Expr) bool {
	e = unparen(e)
	switch v := e.(type) {
	case *ast.BasicLit:
		return true
	case *ast.Ident:
		return v.Name == "nil" || v.Name == "true" || v.Name == "false"
	case *ast.UnaryExpr:
		return isConstExpr(ctx, v.X)
	}
	// types constant value
	if ctx.pkg.TypesInfo != nil {
		if tv, ok := ctx.pkg.TypesInfo.Types[e]; ok && tv.Value != nil {
			return true
		}
	}
	return false
}

func checkZeroByteRepeat(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		if ctx.callFuncName(call) != "bytes.Repeat" {
			return true
		}
		// arg0 is []byte{0} composite
		cl, ok := unparen(call.Args[0]).(*ast.CompositeLit)
		if !ok || len(cl.Elts) != 1 {
			return true
		}
		if v, ok := constIntValue(cl.Elts[0]); !ok || v != 0 {
			return true
		}
		out = append(out, ctx.warn(call.Pos(), "avoid %s; consider using make([]byte, %s) instead", ctx.nodeText(call), ctx.nodeText(call.Args[1])))
		return true
	})
	return out
}
