func checkBadLock(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	processList := func(list []ast.Stmt) {
		for i := 0; i+1 < len(list); i++ {
			// Lock as ExprStmt, next Unlock same receiver
			e1, ok1 := list[i].(*ast.ExprStmt)
			e2, ok2 := list[i+1].(*ast.ExprStmt)
			if !ok1 || !ok2 {
				continue
			}
			c1, ok1 := unparen(e1.X).(*ast.CallExpr)
			c2, ok2 := unparen(e2.X).(*ast.CallExpr)
			if !ok1 || !ok2 {
				continue
			}
			s1, ok1 := selectorOf(c1.Fun)
			s2, ok2 := selectorOf(c2.Fun)
			if !ok1 || !ok2 {
				continue
			}
			if s1.Sel.Name == "Lock" && s2.Sel.Name == "Unlock" && ctx.exprEq(s1.X, s2.X) {
				out = append(out, ctx.warn(c1.Pos(), "defer is missing, mutex is unlocked immediately"))
			}
			// Also Lock without... RLock?
			if (s1.Sel.Name == "RLock" && s2.Sel.Name == "RUnlock") && ctx.exprEq(s1.X, s2.X) {
				out = append(out, ctx.warn(c1.Pos(), "defer is missing, mutex is unlocked immediately"))
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.BlockStmt:
			processList(v.List)
		case *ast.CaseClause:
			processList(v.Body)
		case *ast.CommClause:
			processList(v.Body)
		}
		return true
	})
	return out
}

func checkBadRegexp(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// For regexp compile calls with literal patterns
	checkPattern := func(call *ast.CallExpr, pat string, pos token.Pos) {
		// detection: non-capturing group with ^ inside alternation: (?:^aa|bb|cc)
		// Simplified analyses on raw pattern
		// ^ applied only to `aa` in ^aa|bb|cc : find pattern starting with ^ or (?:^ and containing |
		// We'll implement regex for "(?:^X|"
		if idx := strings.Index(pat, "|"); idx >= 0 {
			// find ^ somewhere before |
			// cases: pattern begins '^' then alternation at top level (no group)
			// Or "(?:^aa|bb|cc"
			// Extract first alternative after ^
			// Determine subcase from probe: `(?:^aa|bb|cc)foo[aba]` gave "^ applied only to `aa` in ^aa|bb|cc"
			// Message substring is the alternation inside group without (?: and )
			// Simplify: if pattern contains "(?:^"
			if strings.Contains(pat, "(?:^") {
				start := strings.Index(pat, "(?:^") + len("(?:")
				end := strings.Index(pat, ")")
				if end > start {
					inner := pat[start:end] // ^aa|bb|cc + maybe includes foo? In probe, pattern `(?:^aa|bb|cc)foo` - end is after cc, inner=^aa|bb|cc
					parts := strings.Split(inner, "|")
					if len(parts) > 1 {
						first := strings.TrimPrefix(parts[0], "^")
						out = append(out, ctx.warn(pos, "^ applied only to `%s` in %s", first, inner))
					}
				}
			} else if strings.HasPrefix(pat, "^") && !strings.HasPrefix(pat, "^(?:") && !strings.HasPrefix(pat, "^(") {
				// top-level ^a|b
				// Does original flag? Probably
				parts := strings.Split(pat, "|")
				if len(parts) > 1 {
					// only if no grouping
					if !strings.Contains(pat, "(") {
						first := strings.TrimPrefix(parts[0], "^")
						out = append(out, ctx.warn(pos, "^ applied only to `%s` in %s", first, pat))
					}
				}
			}
		}
		// duplicated char in char class [aba] / [aa]
		// find [...] classes
		for i := 0; i < len(pat); i++ {
			if pat[i] == '[' {
				// find closing ]
				j := i + 1
				if j < len(pat) && pat[j] == '^' {
					j++
				}
				if j < len(pat) && pat[j] == ']' {
					j++
				}
				startClass := i
				for j < len(pat) && pat[j] != ']' {
					if pat[j] == '\\' {
						j++
					}
					j++
				}
				if j >= len(pat) {
					break
				}
				class := pat[startClass+1 : j] // without brackets, may include ^
				// strip leading ^
				content := strings.TrimPrefix(class, "^")
				seen := map[rune]bool{}
				reported := map[rune]bool{}
				for _, r := range content {
					if r == '-' || r == '\\' {
						continue
					}
					if seen[r] && !reported[r] {
						out = append(out, ctx.warn(pos, "`%c` is duplicated in [%s]", r, class))
						reported[r] = true
					}
					seen[r] = true
				}
				i = j
			}
		}
		// Additional bad patterns probed later
	}
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 1 {
			return true
		}
		fname := ctx.callFuncName(call)
		if fname == "regexp.MustCompile" || fname == "regexp.Compile" || fname == "regexp.MustCompilePOSIX" || fname == "regexp.CompilePOSIX" {
			if pat, ok := stringLitValue(call.Args[0]); ok {
				checkPattern(call, pat, call.Args[0].Pos())
			}
		}
		return true
	})
	return out
}

func checkBadSorting(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		// assignments like xs = sort.StringSlice(xs), also conversion sort.Float64Slice, IntSlice
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 1 {
			return true
		}
		fname := ctx.callFuncName(call)
		var suggest string
		switch fname {
		case "sort.StringSlice":
			suggest = "sort.Strings"
		case "sort.IntSlice":
			suggest = "sort.Ints"
		case "sort.Float64Slice":
			suggest = "sort.Float64s"
		}
		if suggest != "" {
			out = append(out, ctx.warn(call.Pos(), "suspicious %s usage, maybe %s was intended?", fname, suggest))
		}
		return true
	})
	return out
}

