func checkEmptyStringTest(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || (bin.Op != token.EQL && bin.Op != token.NEQ) {
			return true
		}
		// len(s)==0 or 0==len(s)
		var lenCall *ast.CallExpr
		var isEq bool
		if call, ok := unparen(bin.X).(*ast.CallExpr); ok && isLenCall(ctx, call) {
			if v, ok := constIntValue(bin.Y); ok && v == 0 {
				lenCall = call
				isEq = bin.Op == token.EQL
			}
		} else if call, ok := unparen(bin.Y).(*ast.CallExpr); ok && isLenCall(ctx, call) {
			if v, ok := constIntValue(bin.X); ok && v == 0 {
				lenCall = call
				isEq = bin.Op == token.EQL
			}
		}
		if lenCall == nil {
			return true
		}
		sExpr := lenCall.Args[0]
		// Only if s is string type (or unknown)
		if t := ctx.exprType(sExpr); t != nil && !isStringType(t) {
			return true
		}
		opStr := "=="
		if !isEq {
			opStr = "!="
		}
		out = append(out, ctx.warn(bin.Pos(), "replace `%s` with `%s %s \"\"`", ctx.nodeText(bin), ctx.nodeText(sExpr), opStr))
		return true
	})
	return out
}

func checkEqualFold(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || bin.Op != token.EQL {
			return true
		}
		// strings.ToLower(x) == strings.ToLower(y) or ToUpper, also bytes? 
		getLowerArg := func(e ast.Expr) (ast.Expr, string, bool) {
			call, ok := unparen(e).(*ast.CallExpr)
			if !ok || len(call.Args) != 1 {
				return nil, "", false
			}
			fname := ctx.callFuncName(call)
			if fname == "strings.ToLower" || fname == "strings.ToUpper" || fname == "bytes.ToLower" || fname == "bytes.ToUpper" {
				return call.Args[0], fname, true
			}
			return nil, "", false
		}
		xarg, xf, ok1 := getLowerArg(bin.X)
		yarg, yf, ok2 := getLowerArg(bin.Y)
		if !ok1 || !ok2 || xf != yf {
			return true
		}
		pkg := "strings"
		if strings.HasPrefix(xf, "bytes.") {
			pkg = "bytes"
		}
		out = append(out, ctx.warn(bin.Pos(), "consider replacing with %s.EqualFold(%s, %s)", pkg, ctx.nodeText(xarg), ctx.nodeText(yarg)))
		return true
	})
	return out
}

func checkEvalOrder(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ret, ok := n.(*ast.ReturnStmt)
		if !ok || len(ret.Results) < 2 {
			return true
		}
		// Pattern: return x, f(&x) where later result is a call taking address of a variable used earlier
		// Collect idents used in earlier results
		used := map[string]bool{}
		for i, res := range ret.Results {
			// check this result is a call containing &ident where ident used in previous results
			foundCall := false
			var callText string
			ast.Inspect(res, func(nn ast.Node) bool {
				if call, ok := nn.(*ast.CallExpr); ok {
					// contains unary & ident in args
					for _, arg := range call.Args {
						if ue, ok := unparen(arg).(*ast.UnaryExpr); ok && ue.Op == token.AND {
							if id, ok := unparen(ue.X).(*ast.Ident); ok && used[id.Name] {
								foundCall = true
								callText = ctx.nodeText(call)
							}
						}
						if id, ok := unparen(arg).(*ast.Ident); ok && used[id.Name] {
							// passing by value? not
							_ = id
						}
					}
				}
				return true
			})
			if foundCall && i > 0 {
				out = append(out, ctx.warn(ret.Pos(), "may want to evaluate %s before the return statement", callText))
			}
			// add identifiers from this result
			ast.Inspect(res, func(nn ast.Node) bool {
				if id, ok := nn.(*ast.Ident); ok {
					// exclude selector / function names? simple: add ident if it's not a package?
					used[id.Name] = true
				}
				return true
			})
		}
		return true
	})
	return out
}

func checkExposedSyncMutex(ctx *checkerContext, lf *loadedFile) []warning {
