func checkRangeExprCopy(ctx *checkerContext, lf *loadedFile) []warning { return checkRangeCopyCommon(ctx, lf, true) }
func checkRangeValCopy(ctx *checkerContext, lf *loadedFile) []warning { return checkRangeCopyCommon(ctx, lf, false) }

func checkRangeCopyCommon(ctx *checkerContext, lf *loadedFile, isExpr bool) []warning {
	var out []warning
	// Determine enclosing function name to skip test funcs if param
	currentFuncName := ""
	// We need traversal with func context. Do manual recursion?
	// Simplistic walk: collect FuncDecls and inspect their bodies separately.
	checkRangeStmt := func(rs *ast.RangeStmt, funcName string) {
		if isExpr {
			// rangeExprCopy: range expr type size > threshold, and expr is not pointer/slice/map etc.
			// skip test funcs if param true: ??? Param skipTestFuncs default true meaning (?) doc: whether to check test functions (default true) - wording ambiguous: skipTestFuncs true = skip test funcs? Or check? Flag help: "whether to check test functions (default true)" but name is skipTestFuncs - mismatch.
			// In original, rangeValCopy on fmt? Not.
			// Probe later: func TestX with large range - if default skips or not.
			if paramRangeExprCopySkipTests && isTestFuncName(funcName) {
				// According name skipTestFuncs=true should skip
				// But doc param text says whether to check test functions (default true) contradictory.
				// We'll assume name semantics (skip).
				return
			}
			t := ctx.exprType(rs.X)
			if t == nil {
				return
			}
			// If X is pointer, slicing etc skip: if type is pointer, range over *array avoids copy already
			if _, ok := t.Underlying().(*types.Pointer); ok {
				return
			}
			sz := typeSize(ctx, t)
			if sz > int64(paramRangeExprCopySize) {
				// Message: copy of xs (2048 bytes) can be avoided with &xs
				out = append(out, ctx.warn(rs.Pos(), "copy of %s (%d bytes) can be avoided with &%s", ctx.nodeText(rs.X), sz, ctx.nodeText(rs.X)))
			}
		} else {
			if paramRangeValCopySkipTests && isTestFuncName(funcName) {
				return
			}
			// rangeValCopy: value variable (?) copying each iteration: element type size > threshold
			// rs.Value must be present and not blank?
			if rs.Value == nil {
				return
			}
			if id, ok := rs.Value.(*ast.Ident); ok && id.Name == "_" {
				return
			}
			// element type: type of range expr element
			t := ctx.exprType(rs.X)
			if t == nil {
				return
			}
			var elem types.Type
			switch u := t.Underlying().(type) {
			case *types.Slice:
				elem = u.Elem()
			case *types.Array:
				elem = u.Elem()
			case *types.Map:
				elem = u.Elem()
			case *types.Pointer:
				// *array
				if arr, ok := u.Elem().Underlying().(*types.Array); ok {
					elem = arr.Elem()
				}
			}
			if elem == nil {
				return
			}
			sz := typeSize(ctx, elem)
			if sz > int64(paramRangeValCopySize) {
				out = append(out, ctx.warn(rs.Pos(), "each iteration copies %d bytes (consider pointers or indexing)", sz))
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.FuncDecl:
			if v.Name != nil { currentFuncName = v.Name.Name }
			if v.Body != nil {
				ast.Inspect(v.Body, func(nn ast.Node) bool {
					if rs, ok := nn.(*ast.RangeStmt); ok {
						checkRangeStmt(rs, currentFuncName)
					}
					return true
				})
			}
			return false // avoid duplicate via outer walk? But nested FuncLit inside will be visited? We returned false, inspect won't descend into FuncDecl body - we already inspected. FuncLits inside will have been inspected for RangeStmts with outer funcName (approx)
		case *ast.FuncLit:
			// FuncLit name unknown
			ast.Inspect(v.Body, func(nn ast.Node) bool {
				if rs, ok := nn.(*ast.RangeStmt); ok {
					checkRangeStmt(rs, "")
				}
				return true
			})
			return false
		}
		return true
	})
	return out
}

