func simplifyRegexp(pat string) (string, bool) {
	changed := false
	res := pat
	// (?:a|b|c) -> [abc] where alternatives are single chars
	// Find (?: ... )
	for {
		idx := strings.Index(res, "(?:")
		if idx < 0 {
			break
		}
		end := strings.Index(res[idx:], ")")
		if end < 0 {
			break
		}
		end = idx + end
		inner := res[idx+3 : end]
		parts := strings.Split(inner, "|")
		allSingle := true
		for _, p := range parts {
			if len(p) != 1 {
				allSingle = false
			}
		}
		if allSingle && len(parts) > 1 {
			res = res[:idx] + "[" + strings.Join(parts, "") + "]" + res[end+1:]
			changed = true
		} else {
			break
		}
	}
	// "   " (spaces repeated literal) -> " {3}" ? Probe: (?:a|b|c)   [a-z][a-z]* -> [abc] {3}[a-z]+
	// Replace runs of spaces (literal) with space + {n}
	res2 := ""
	for i := 0; i < len(res); {
		if res[i] == ' ' {
			j := i
			for j < len(res) && res[j] == ' ' {
				j++
			}
			count := j - i
			if count > 1 {
				res2 += fmt.Sprintf(" {%d}", count)
				changed = true
			} else {
				res2 += " "
			}
			i = j
		} else {
			res2 += string(res[i])
			i++
		}
	}
	res = res2
	// [a-z][a-z]* -> [a-z]+ ; generally X* preceding (?) pattern: [<class>][same]*? The probe: [a-z][a-z]*  -> [a-z]+
	// Replace repeated char class followed by same class *
	res = replaceRepeatedClass(res, &changed)
	// a| etc already
	// [a-z]*[a-z] etc not
	return res, changed
}

func replaceRepeatedClass(s string, changed *bool) string {
	// Find occurrences of pattern [..][..]* with same class
	i := 0
	var out strings.Builder
	for i < len(s) {
		if s[i] == '[' {
			end1 := strings.Index(s[i:], "]")
			if end1 < 0 {
				break
			}
			end1 = i + end1
			class1 := s[i : end1+1]
			// check following [class]*
			if end1+1 < len(s) && s[end1+1] == '[' {
				end2 := strings.Index(s[end1+1:], "]")
				if end2 >= 0 {
					end2 = end1 + 1 + end2
					class2 := s[end1+1 : end2+1]
					if class1 == class2 && end2+1 < len(s) && s[end2+1] == '*' {
						out.WriteString(class1 + "+")
						*changed = true
						i = end2 + 2
						continue
					}
				}
			}
		}
		out.WriteByte(s[i])
		i++
	}
	out.WriteString(s[i:])
	// Actually loop above double counted? Simplify: we built partially; if no replacement, return s
	// This implementation when not matching writes byte and moves; when matching writes and jumps.
	// However trailing append duplicates - we already wrote rest? The for loop ends when i>=len, out.WriteString(s[i:]) is empty.
	return out.String()
}

func checkReturnAfterHttpError(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || ifs.Body == nil {
			return true
		}
		// look for http.Error call as last statement? Or any statement not followed by return
		// Probe: if true { http.Error(...) } - single statement, no return, flagged.
		for idx, stmt := range ifs.Body.List {
			// stmt may be ExprStmt call http.Error
			var call *ast.CallExpr
			if es, ok := stmt.(*ast.ExprStmt); ok {
				call, _ = unparen(es.X).(*ast.CallExpr)
			}
			if call == nil {
				continue
			}
			if ctx.callFuncName(call) != "http.Error" {
				continue
			}
			// If later statements contain return, skip? Probe: if error block had return after (?) flagged if no return after in same block
			hasReturnAfter := false
			for _, later := range ifs.Body.List[idx+1:] {
				if _, ok := later.(*ast.ReturnStmt); ok {
					hasReturnAfter = true
				}
				// also if later statement is return in nested? ignore
			}
			// Also if http.Error is last statement and following code in outer block? original only checks within if?
			if !hasReturnAfter {
				out = append(out, ctx.warn(stmt.Pos(), "Possibly return is missed after the http.Error call"))
			}
		}
		return true
	})
	return out
}

