func extractFirstString(s string) (string,string,bool) {
	s=strings.TrimSpace(s)
	if len(s)==0 {return "",s,false}
	if s[0]=='`' {
		end:=strings.Index(s[1:],"`")
		if end<0 {return "",s,false}
		return s[1:1+end], s[1+end+1:], true
	}
	if s[0]=='"' {
		// use strconv
		i:=1
		for i<len(s){
			if s[i]=='\\'{i+=2;continue}
			if s[i]=='"'{ 
				v:=s[1:i]
				// unescape simple
				v=strings.ReplaceAll(v,`\"`,`"`)
				v=strings.ReplaceAll(v,"\\n","\n")
				return v,s[i+1:],true
			}
			i++
		}
	}
	// string may be after some chars? find first ` or "
	for i,ch:=range s {
		if ch=='`' || ch=='"' {
			v,rest,ok:=extractFirstString(s[i:])
			return v,rest,ok
		}
	}
	return "",s,false
}

func runRuleguardRules(ctx *checkerContext, lf *loadedFile) []warning {
	// If no custom rules, embedded rules currently unknown - return none
	if ctx.rg==nil || len(ctx.rg.rules)==0 { return nil }
	// Very simple matcher: if match pattern is a literal call pattern like `fmt.Sprint($x)` we attempt textual matching using source.
	// For each AST call node, compare its normalized text template where $var wildcards match any expr.
	var out []warning
	for _, rule := range ctx.rg.rules {
		for _, pat := range rule.patterns {
			// skip complex patterns with Where etc.
			patText:=strings.TrimSpace(pat.matchText)
			// Patterns may contain $$ etc.
			walkFile(lf, func(n ast.Node) bool {
				if call,ok:=n.(*ast.CallExpr); ok {
					// textual template match roughly: replace $identifier in patText with wildcard; check if call text matches skeleton (func name part)
					if ruleguardMatchCall(ctx, patText, call) {
						msg:=pat.msg
						// Replace $var in msg with actual matched text? Placeholder substitution naive: if msg contains $...
						// We'll leave as is unless $x etc - original substitutes.
						msg = substituteRuleVars(msg, patText, ctx, call)
						out=append(out, ctx.warn(call.Pos(), "%s", msg))
					}
				}
				return true
			})
		}
	}
	return out
}

func ruleguardMatchCall(ctx *checkerContext, pat string, call *ast.CallExpr) bool {
	// Extract function name before '(' in pattern
	idx:=strings.Index(pat,"(")
	if idx<0 { return false }
	patFunc:=strings.TrimSpace(pat[:idx])
	// patFunc could be $func or fmt.X etc
	if strings.HasPrefix(patFunc,"$") { return true }
	return ctx.callFuncName(call)==patFunc || ctx.nodeText(call.Fun)==patFunc
