			// casing: (?i)deprecated: + space, word not exactly Deprecated
			if idx := strings.Index(text, ": "); idx > 0 {
				word := text[:idx]
				if strings.EqualFold(word, "deprecated") && word != "Deprecated" {
					out = append(out, ctx.warn(c.Pos(), "use `Deprecated: ` (note the casing) instead of `%s: `", word))
					warned = true
				} else if strings.EqualFold(word, "deprecate") {
					out = append(out, ctx.warn(c.Pos(), "typo in `%s`; should be `Deprecated`", word))
					warned = true
				}
			}
			if !warned && strings.HasPrefix(text, "Deprecated, ") {
