				// This function/type is deprecated
				if strings.HasPrefix(lower, "this function is deprecated") || strings.HasPrefix(lower, "this type is deprecated") {
					out = append(out, ctx.warn(c.Pos(), "the proper format is `Deprecated: <text>`"))
					warned = true
				} else if improperDeprecatedStart(lower) {
					out = append(out, ctx.warn(c.Pos(), "the proper format is `Deprecated: <text>`"))
					warned = true
				}
			}
			_ = warned
			paragraphStart = false
		}
	}
	return out
}

func improperDeprecatedStart(lower string) bool {
	// patterns: deprecated[.!]? (use|in favor of|in favour of)
	// or deprecated + space + use/in favor...
	if !strings.HasPrefix(lower, "deprecated") {
		return false
	}
	rest := lower[len("deprecated"):]
	// strip optional . or !
	if strings.HasPrefix(rest, ".") || strings.HasPrefix(rest, "!") {
		rest = rest[1:]
	}
	rest = strings.TrimSpace(rest)
	return strings.HasPrefix(rest, "use") || strings.HasPrefix(rest, "in favor of") || strings.HasPrefix(rest, "in favour of")
}

