new='''func checkArgOrder(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) != 2 {
			return true
		}
		fname := ctx.callFuncName(call)
		switch fname {
		case "strings.HasPrefix", "strings.HasSuffix", "strings.Contains", "strings.TrimPrefix", "strings.TrimSuffix",
			"bytes.HasPrefix", "bytes.HasSuffix", "bytes.Contains", "bytes.TrimPrefix", "bytes.TrimSuffix":
		default:
			return true
		}
		if !isLiteralExpr(call.Args[0]) {
			return true
		}
		if isLiteralExpr(call.Args[1]) {
			return true
		}
		out = append(out, ctx.warn(call.Pos(), "%s and %s arguments order looks reversed", ctx.nodeText(call.Args[0]), ctx.nodeText(call.Args[1])))
		return true
	})
	return out
}

func isLiteralExpr(e ast.Expr) bool {
	switch v := unparen(e).(type) {
	case *ast.BasicLit:
		return true
	case *ast.BinaryExpr:
		return isLiteralExpr(v.X) && isLiteralExpr(v.Y)
	case *ast.UnaryExpr:
		return isLiteralExpr(v.X)
	case *ast.CallExpr:
		// conversion like []byte("p") / string(...)
		if len(v.Args) != 1 {
			return false
		}
		// Fun must be a type (its text contains [] or is string/byte etc) - accept if arg literal and Fun is not an ident referring to a function?
		if _, ok := v.Fun.(*ast.Ident); ok {
			// string(x) conversion
			return isLiteralExpr(v.Args[0])
		}
		// ArrayType etc
		return isLiteralExpr(v.Args[0])
	case *ast.CompositeLit:
		for _, el := range v.Elts {
			if kv, ok := el.(*ast.KeyValueExpr); ok {
				if !isLiteralExpr(kv.Value) { return false }
			} else if !isLiteralExpr(el) {
				return false
			}
		}
		return true
	}
	return false
}

