func zeroValueForTypeNew(ctx *checkerContext, typeExpr ast.Expr, t types.Type) (string, bool) {
	typeText := ctx.formatNode(typeExpr)
	if t != nil {
		switch u := t.Underlying().(type) {
		case *types.Chan, *types.Signature:
			return "", true
		case *types.Basic:
			switch u.Kind() {
			case types.Bool, types.UntypedBool:
				if t.String() == "bool" {
					return "false", false
				}
				return typeText + "(false)", false
			case types.String, types.UntypedString:
				if t.String() == "string" {
					return `""`, false
				}
				return typeText + `("")`, false
			case types.Float32, types.Float64, types.UntypedFloat:
				if t.String() == "float64" {
					return "0.0", false
				}
				return typeText + "(0.0)", false
			case types.Complex64, types.Complex128, types.UntypedComplex:
				return "%!s(PANIC=String method: runtime error: invalid memory address or nil pointer dereference)", false
			default:
				if u.Info()&types.IsNumeric != 0 {
					if t.String() == "int" {
						return "0", false
					}
					return typeText + "(0)", false
				}
				if u.Kind() == types.UnsafePointer {
					return "", true
				}
			}
		case *types.Pointer, *types.Slice, *types.Map, *types.Interface:
			if _, isPtr := u.(*types.Pointer); isPtr {
				return "(" + typeText + ")(nil)", false
			}
			return typeText + "(nil)", false
		case *types.Array, *types.Struct:
			return typeText + "{}", false
		}
		// Named types with other underlying are handled above via underlying switch.
		return typeText + "{}", false
	}
	// No type info: fallback based on text
	base := typeText
	switch base {
	case "bool":
		return "false", false
	case "string":
		return `""`, false
	case "int":
		return "0", false
	case "float64":
		return "0.0", false
	case "float32":
		return "float32(0.0)", false
	}
	if strings.HasPrefix(base, "*") {
		return "(" + base + ")(nil)", false
	}
	if strings.HasPrefix(base, "[]") || strings.HasPrefix(base, "map[") || strings.HasPrefix(base, "interface") {
		return base + "(nil)", false
	}
	if strings.HasPrefix(base, "chan ") || strings.HasPrefix(base, "func(") {
		return "", true
	}
	// numeric named?
	return base + "{}", false
}

