{"command":"cat > regexp_simplify.go <<'EOF'
package main

import (
	"strings"
)

// A partial reimplementation of regexp simplification rules that
// were observed from the original checker.
func simplifyRegexpV2(pat string) (string, bool) {
	orig := pat
	s := pat
	s = simplifyClasses(s)
	s = simplifyQuantifiers(s)
	s = simplifyClassRepeats(s)
	s = simplifyAlternations(s)
	// After alternation conversion, quantifiers etc may still need spaces handling etc
	s = simplifySpaces(s)
	s = simplifyClasses(s)
	return s, s != orig
}

func simplifyQuantifiers(s string) string {
	// Replace {1} -> "", {0,1} -> ?, {1,} -> +, {0,} -> *
	// Scanning outside char classes
	var out strings.Builder
	inClass := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			out.WriteByte(c)
			out.WriteByte(s[i+1])
			i++
			continue
		}
		if c == '[' {
			inClass = true
		}
		if c == ']' {
			inClass = false
		}
		if !inClass && c == '{' {
			end := strings.Index(s[i:], "}")
			if end > 0 {
				inside := s[i+1 : i+end]
				switch inside {
				case "1":
					// skip writing quantifier
					i += end
					return simplifyQuantifiers(out.String() + s[i+1:]) // simpler recursion; fallback below handled by loop continuation
				case "0,1":
					out.WriteByte('?')
					i += end
					continue
				case "1,":
					out.WriteByte('+')
					i += end
					continue
				case "0,":
					out.WriteByte('*')
					i += end
					continue
				}
			}
		}
		out.WriteByte(c)
	}
	return out.String()
}

func simplifySpaces(s string) string {
	// runs of spaces (len>1) outside char classes become " {n}"
	var out strings.Builder
	inClass := false
	for i := 0; i < len(s); {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			out.WriteByte(c)
			out.WriteByte(s[i+1])
			i += 2
			continue
		}
		if c == '[' {
			inClass = true
		}
		if c == ']' {
			inClass = false
		}
		if !inClass && c == ' ' {
			j := i
			for j < len(s) && s[j] == ' ' {
				j++
			}
			n := j - i
			if n > 1 {
				out.WriteString(" {" + itoa(n) + "}")
			} else {
				out.WriteByte(' ')
			}
			i = j
			continue
		}
		out.WriteByte(c)
		i++
	}
	return out.String()
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var buf [8]byte
	pos := len(buf)
	for n > 0 {
		pos--
		buf[pos] = byte('0' + n%10)
		n /= 10
	}
	return string(buf[pos:])
}

// simplifyClasses handles [] simplifications
func simplifyClasses(s string) string {
	var out strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			out.WriteByte(c)
			out.WriteByte(s[i+1])
			i++
			continue
		}
		if c == '[' {
			// find end
			j := i + 1
			if j < len(s) && s[j] == '^' {
				j++
			}
			if j < len(s) && s[j] == ']' {
				j++
			}
			for j < len(s) && s[j] != ']' {
				if s[j] == '\\' && j+1 < len(s) {
					j++
				}
				j++
			}
			if j >= len(s) {
				out.WriteString(s[i:])
				break
			}
			class := s[i : j+1]
			newClass, isWholeReplacement, replacement := simplifyOneClass(class)
			if isWholeReplacement {
				out.WriteString(replacement)
			} else {
				out.WriteString(newClass)
			}
			i = j
			continue
		}
		out.WriteByte(c)
	}
	return out.String()
}

// returns (newClass, wholeReplacement bool, replacement)
func simplifyOneClass(class string) (string, bool, string) {
	inner := class[1 : len(class)-1]
	neg := false
	if strings.HasPrefix(inner, "^") {
		neg = true
		inner = inner[1:]
	}
	// single perl class: \d etc
	if len(inner) == 2 && inner[0] == '\\' && strings.ContainsRune("dwsDWS", rune(inner[1])) {
		if !neg {
			return "", true, inner
		}
	}
	// [0-9] -> \d, [^0-9] -> \D
	if inner == "0-9" {
		if neg {
			return "", true, `\D`
		}
		return "", true, `\d`
	}
	// Parse class elements: each element is either escape (2 chars) or a single char, and ranges x-y
	// Tokenize
	type elem struct {
		text string // \d or single char string (1 rune) or range
		isRange bool
		from rune
		to   rune
		raw  string
	}
	var elems []elem
	runes := []rune(inner)
	for i := 0; i < len(runes); {
		if runes[i] == '\\' && i+1 < len(runes) {
			elems = append(elems, elem{text: string(runes[i : i+2]), raw: string(runes[i : i+2])})
			i += 2
			continue
		}
		// range?
		if i+2 < len(runes)+0 && i+2 < len(runes) && runes[i+1] == '-' && runes[i+2] != ']' {
			// check range: need ensure i+2 exists and '-' is not at end (trailing - is literal) - in rune slice, end is len
			if i+2 < len(runes) {
				elems = append(elems, elem{isRange: true, from: runes[i], to: runes[i+2], raw: string(runes[i : i+3])})
				i += 3
				continue
			}
		}
		if i+1 < len(runes) && runes[i+1] == '-' && i+2 >= len(runes) {
			// trailing -, literal
		}
		elems = append(elems, elem{text: string(runes[i]), from: runes[i], raw: string(runes[i])})
		i++
	}
	// If single range
	if len(elems) == 1 && elems[0].isRange {
		from, to := elems[0].from, elems[0].to
		if from == to {
			if neg {
				return "[^" + string(from) + "]", false, ""
			}
			return "", true, string(from)
		}
		if to > from && to-from <= 2 {
			// expand to [abc]
			var chars string
			for r := from; r <= to; r++ {
				chars += string(r)
			}
			if neg {
				return "[^" + chars + "]", false, ""
			}
			return "[" + chars + "]", false, ""
		}
		return class, false, ""
	}
	// Multiple elems: replace a-a ranges with single char, and ranges size <=3 expansion
	changed := false
	var newInner strings.Builder
	if neg {
		newInner.WriteString("^")
	}
	for _, e := range elems {
		if e.isRange {
			if e.from == e.to {
				newInner.WriteRune(e.from)
				changed = true
			} else if e.to > e.from && e.to-e.from <= 2 {
				for r := e.from; r <= e.to; r++ {
					newInner.WriteRune(r)
				}
				changed = true
			} else {
				newInner.WriteString(e.raw)
			}
		} else {
			newInner.WriteString(e.text)
		}
	}
	// If after expansion, the class becomes like [abc] etc - if original had range that was expanded and now inner might represent ??? For [a-a-c] case, elems were range a-a, char -, char c ??? Our tokenization for "a-a-c": first range a-a, then ??? remaining "-c": runes '-' then 'c' - '-' at start of remaining would be literal '-' then c - writing them as "-c" yields [a-c] -> second iteration simplifyClasses will expand that range to [abc]. Our caller calls simplifyClasses again in V2 (second pass). Good.
	if changed {
		return "[" + newInner.String() + "]", false, ""
	}
	return class, false, ""
}

func simplifyClassRepeats(s string) string {
	// Find [...][...]* -> [...]+ and [...][...] repeated -> [...]{n}
	// Also handles [a-z][a-z]* case already (second has *)
	// Scan tokens
	type token struct {
		text string
		start int
		end int // exclusive after quantifier maybe?
		isClass bool
		quant string
		base string
	}
	// Tokenize sequence at top level only (skip group contents? groups are atoms but we treat text)
	// Simplistic string scan: look for class pattern occurrences
	res := s
	for {
		found := false
		// find two consecutive class atoms
		i := 0
		for i < len(res) {
			cls1, end1, ok1 := parseClassAt(res, i)
			if !ok1 { i++; continue }
			// quantifier after cls1?
			q1, endq1 := parseQuantAt(res, end1)
			_ = q1
			nextPos := end1
			if q1 != "" { nextPos = endq1 }
			cls2, end2, ok2 := parseClassAt(res, nextPos)
			if !ok2 || cls1 != cls2 || q1 != "" {
				i = end1
				continue
			}
			q2, endq2 := parseQuantAt(res, end2)
			if q2 == "*" {
				res = res[:i] + cls1 + "+" + res[endq2:]
				found = true
				break
			} else if q2 == "" {
				// count repeats: look ahead for more same class without quant
				count := 2
				pos := end2
				for {
					cn, enn, okn := parseClassAt(res, pos)
					if !okn || cn != cls1 { break }
					qn, eqn := parseQuantAt(res, enn)
					if qn != "" { break }
					_ = eqn
					count++
					pos = enn
				}
				res = res[:i] + cls1 + "{" + itoa(count) + "}" + res[pos:]
				found = true
				break
			} else {
				i = end1
				continue
			}
		}
		if !found { break }
	}
	return res
}

func parseClassAt(s string, i int) (string,int,bool) {
	if i >= len(s) || s[i] != '[' { return "", i, false }
	j := i+1
	if j < len(s) && s[j] == '^' { j++ }
	if j < len(s) && s[j] == ']' { j++ }
	for j < len(s) && s[j] != ']' {
		if s[j] == '\\' && j+1 < len(s) { j++ }
		j++
	}
	if j >= len(s) { return "", i, false }
	return s[i:j+1], j+1, true
}
func parseQuantAt(s string, i int) (string,int) {
	if i >= len(s) { return "", i }
	if s[i]=='*'||s[i]=='+'||s[i]=='?' { return string(s[i]), i+1 }
	if s[i]=='{' {
		end:=strings.Index(s[i:], "}")
		if end>0 { return s[i:i+end+1], i+end+1 }
	}
	return "", i
}

func simplifyAlternations(s string) string {
	// Group conversions
	// Find (?:...) and (...) groups with alternation of single chars
	for {
		changed := false
		for i:=0;i<len(s);i++ {
			if s[i]=='(' {
				// find matching )
				depth:=0; j:=i
				for ;j<len(s);j++ {
					if s[j]=='\\' { j++; continue }
					if s[j]=='[' {
						_,e,ok:=parseClassAt(s,j); if ok { j=e-1; continue }
					}
					if s[j]=='(' { depth++ }
					if s[j]==')' { depth--; if depth==0 { break } }
				}
				if j>=len(s) { break }
				group:=s[i:j+1]
				isNonCap:=strings.HasPrefix(group,"(?:")
				isCap:=!isNonCap && !strings.HasPrefix(group,"(?")
				if isNonCap || isCap {
					inner:=group[2:len(group)-1]
					if isNonCap { inner=group[3:len(group)-1] }
					if repl, ok:=alternationToClass(inner); ok {
						if isCap { repl="("+repl+")" }
						s=s[:i]+repl+s[j+1:]
						changed=true
						break
					}
				}
			}
		}
		if !changed { break }
	}
	// Top-level alternation: if entire string is alternation of single chars (outside classes/groups)
	if repl, ok:=alternationToClassTop(s); ok {
		return repl
	}
	return s
}

func alternationToClass(inner string) (string,bool) {
	// split by | at top level
	if !strings.Contains(inner,"|") { return "",false }
	parts:=strings.Split(inner,"|")
	var chars string
	for _,part:=range parts {
		// part must be a single character (one rune, not escaped class etc) - allow single byte char
		r:=[]rune(part)
		if len(r)!=1 { return "",false }
		chars+=part
	}
	return "["+chars+"]", true
}
func alternationToClassTop(s string) (string,bool) {
	// Only if no '(', '[', '\\' ?
	if strings.ContainsAny(s, "([\\") { return "",false }
	return alternationToClass(s)
}
