package main

import (
	"go/ast"
	"strings"
)

func checkTypeUnparenV2(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	if lf.AST == nil {
		return out
	}
	// collect paren nodes in type position and their roots
	seenRoot := map[ast.Node]bool{}
	// We need list of paren nodes in traversal order
	var parens []*ast.ParenExpr
	ast.Inspect(lf.AST, func(n ast.Node) bool {
		if pe, ok := n.(*ast.ParenExpr); ok {
			parens = append(parens, pe)
		}
		return true
	})
	for _, pe := range parens {
		root, ok := typeRootForParen(ctx, pe)
		if !ok || root == nil {
			continue
		}
		if seenRoot[root] {
			continue
		}
		seenRoot[root] = true
		orig := ctx.formatNode(root)
		sug := buildTypeStringV2(root, ctx)
		// For roots that are paren itself, formatNode may give (int) - fine.
		// If orig == sug, still original warned in many FuncType/Map cases (orig was stripped by their printer and equalled suggestion).
		// For a root that is a paren, if orig==sug (should not happen)
		// Warn regardless (as original does)
		out = append(out, ctx.warn(root.Pos(), "could simplify %s to %s", orig, sug))
	}
	return out
}

// typeRootForParen returns the maximal type expression root for a paren used as type, or false if not a type paren.
func typeRootForParen(ctx *checkerContext, pe *ast.ParenExpr) (ast.Node, bool) {
	if ctx.parents == nil {
		return nil, false
	}
	// The paren must itself be used as a type: climb
	cur := ast.Node(pe)
	root := ast.Node(pe)
	// state: whether we have entered a type context
	// We climb parents
	for {
		par := ctx.parents[cur]
		if par == nil {
			// At file top? paren was direct? Not type
			return nil, false
		}
		switch p := par.(type) {
		case *ast.ParenExpr:
			root = p
			cur = p
			continue
		case *ast.ArrayType:
			// ensure cur is Elt, not Len
			if p.Elt != cur && p.Len != cur {
				// cur might be a subnode inside Elt (e.g., FuncType that is Elt): path would go through that node, not direct.
				// In climbing, cur is the immediate child node on path, so if cur is Elt or something inside Elt, cur at this iteration is Elt node (since we stepped through it)
				// If cur is not Elt, it's not type (Len)
				return nil, false
			}
			root = p
			cur = p
			continue
		case *ast.MapType:
			root = p
			cur = p
			continue
		case *ast.ChanType:
			root = p
			cur = p
			continue
		case *ast.StarExpr:
			root = p
			cur = p
			continue
		case *ast.Ellipsis:
			root = p
			cur = p
			continue
		case *ast.Field:
			// cur is Field.Type (root so far). Parent of Field determines context.
			// Move to Field as cur, and let next iteration handle its parent
			cur = p
			continue
		case *ast.FuncType:
			// cur is a Field (Params/Results) or directly?
			// If this FuncType is the type of a FuncDecl, we should NOT promote to FuncType;
			// root stays as it was before (Field.Type)
			if ctx.parents[p] != nil {
				if _, isFuncDecl := ctx.parents[p].(*ast.FuncDecl); isFuncDecl {
					return root, true
				}
			}
			root = p
			cur = p
			continue
		case *ast.StructType, *ast.InterfaceType:
			// cur is a Field of struct/interface - root is Field.Type (already)
			return root, true
		case *ast.FuncDecl:
			// cur is either Field (recv/params/results) or FuncType; if cur is Field, root is Field.Type (already)
			// If cur is FuncType (should not happen because that case returns above)
			return root, true
		case *ast.FuncLit:
			return root, true
		case *ast.TypeSpec:
			// root is the TypeSpec.Type (cur should be that)
			return root, true
		case *ast.ValueSpec:
			return root, true
		case *ast.CallExpr:
			// conversion: cur is Fun (Paren or root type). Only if cur is exactly the Fun
			if p.Fun == cur || root == pe {
				// If root is not just pe, root is a larger type that is the Fun - that's also a conversion type, root is that type
				return root, true
			}
			return nil, false
		case *ast.TypeAssertExpr:
			if p.Type == cur || root == pe {
				return root, true
			}
			return nil, false
		case *ast.CompositeLit:
			if p.Type == cur {
				return root, true
			}
			// If root is a larger type that is CompositeLit.Type (cur is that type)
			if p.Type == root {
				return root, true
			}
			return nil, false
		case *ast.ReturnStmt, *ast.AssignStmt, *ast.ExprStmt, *ast.SendStmt, *ast.IncDecStmt:
			return nil, false
		default:
			// For other parents: if cur is a Field, its parent could be FieldList in various decls - handled via FuncType/Struct above
			// FieldList is not an ast.Node parent? parents map may have *ast.FieldList as parent of Field
			if _, ok := par.(*ast.FieldList); ok {
				cur = p
				continue
			}
			// Unknown parent: if root != pe, we are inside a type expression whose root we already have - return it
			// If root == pe and parent is something like IndexExpr etc, not type
			return nil, false
		}
	}
}

func buildTypeStringV2(e ast.Expr, ctx *checkerContext) string {
	switch t := e.(type) {
	case *ast.ParenExpr:
		return buildTypeStringV2(t.X, ctx)
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return buildTypeStringV2(t.X, ctx) + "." + t.Sel.Name
	case *ast.StarExpr:
		return "*" + buildTypeStringV2(t.X, ctx)
	case *ast.ArrayType:
		length := ""
		if t.Len != nil {
			length = ctx.nodeText(t.Len)
		}
		return "[" + length + "]" + buildTypeStringV2(t.Elt, ctx)
	case *ast.MapType:
		return "map[" + buildTypeStringV2(t.Key, ctx) + "]" + buildTypeStringV2(t.Value, ctx)
	case *ast.ChanType:
		switch t.Dir {
		case ast.SEND:
			return "chan<- " + buildTypeStringV2(t.Value, ctx)
		case ast.RECV:
			return "<-chan " + buildTypeStringV2(t.Value, ctx)
		default:
			return "chan " + buildTypeStringV2(t.Value, ctx)
		}
	case *ast.Ellipsis:
		return "..." + buildTypeStringV2(t.Elt, ctx)
	case *ast.FuncType:
		params := fieldListTypeString(t.Params, ctx)
		res := ""
		if t.Results != nil && len(t.Results.List) > 0 {
			if len(t.Results.List) == 1 && len(t.Results.List[0].Names) == 0 {
				res = " " + buildTypeStringV2(t.Results.List[0].Type, ctx)
			} else {
				res = " (" + fieldListTypeString(t.Results, ctx) + ")"
			}
		}
		return "func(" + params + ")" + res
	case *ast.StructType:
		var parts []string
		if t.Fields != nil {
			for _, f := range t.Fields.List {
				part := ""
				if len(f.Names) > 0 {
					part = namesString(f.Names) + " "
				}
				part += buildTypeStringV2(f.Type, ctx)
				if f.Tag != nil {
					part += " " + f.Tag.Value
				}
				parts = append(parts, part)
			}
		}
		return "struct{" + strings.Join(parts, "; ") + "}"
	case *ast.InterfaceType:
		var parts []string
		if t.Methods != nil {
			for _, f := range t.Methods.List {
				part := ""
				if len(f.Names) > 0 {
					part = namesString(f.Names) + " "
				}
				part += buildTypeStringV2(f.Type, ctx)
				parts = append(parts, part)
			}
		}
		if len(parts) == 0 {
			return "interface{}"
		}
		return "interface{" + strings.Join(parts, "; ") + "}"
	case *ast.BasicLit:
		return t.Value
	default:
		// Fallback to printed form, but strip parens via formatNode may keep them; use node text
		s := ctx.formatNode(e)
		// If it's not a type node we might be a generic type index etc.
		return s
	}
}

func fieldListTypeString(fl *ast.FieldList, ctx *checkerContext) string {
	if fl == nil {
		return ""
	}
	var parts []string
	for _, f := range fl.List {
		if len(f.Names) > 0 {
			parts = append(parts, namesString(f.Names)+" "+buildTypeStringV2(f.Type, ctx))
		} else {
			parts = append(parts, buildTypeStringV2(f.Type, ctx))
		}
	}
	return strings.Join(parts, ", ")
}
