func buildTypeStringV2(e ast.Expr, ctx *checkerContext) string {
	switch t := e.(type) {
	case *ast.ParenExpr:
		return buildTypeStringV2(t.X, ctx)
	case *ast.Ident:
		return t.Name
	case *ast.SelectorExpr:
		return buildTypeStringV2(t.X, ctx) + "." + t.Sel.Name
	case *ast.StarExpr:
		return "*" + buildTypeStringV2(t.X, ctx)
	case *ast.ArrayType:
		length := ""
		if t.Len != nil {
			length = ctx.nodeText(t.Len)
		}
		return "[" + length + "]" + buildTypeStringV2(t.Elt, ctx)
	case *ast.MapType:
		return "map[" + buildTypeStringV2(t.Key, ctx) + "]" + buildTypeStringV2(t.Value, ctx)
	case *ast.ChanType:
		switch t.Dir {
		case ast.SEND:
			return "chan<- " + buildTypeStringV2(t.Value, ctx)
		case ast.RECV:
			return "<-chan " + buildTypeStringV2(t.Value, ctx)
		default:
			return "chan " + buildTypeStringV2(t.Value, ctx)
		}
	case *ast.Ellipsis:
		return "..." + buildTypeStringV2(t.Elt, ctx)
	case *ast.FuncType:
		params := fieldListTypeString(t.Params, ctx)
		res := ""
		if t.Results != nil && len(t.Results.List) > 0 {
			if len(t.Results.List) == 1 && len(t.Results.List[0].Names) == 0 {
				res = " " + buildTypeStringV2(t.Results.List[0].Type, ctx)
			} else {
				res = " (" + fieldListTypeString(t.Results, ctx) + ")"
			}
		}
		return "func(" + params + ")" + res
	case *ast.StructType:
		var parts []string
		if t.Fields != nil {
			for _, f := range t.Fields.List {
				part := ""
				if len(f.Names) > 0 {
					part = namesString(f.Names) + " "
				}
				part += buildTypeStringV2(f.Type, ctx)
				if f.Tag != nil {
					part += " " + f.Tag.Value
				}
				parts = append(parts, part)
			}
		}
		return "struct{" + strings.Join(parts, "; ") + "}"
	case *ast.InterfaceType:
		var parts []string
		if t.Methods != nil {
			for _, f := range t.Methods.List {
				part := ""
				if len(f.Names) > 0 {
					part = namesString(f.Names) + " "
				}
				part += buildTypeStringV2(f.Type, ctx)
				parts = append(parts, part)
			}
		}
		if len(parts) == 0 {
			return "interface{}"
		}
		return "interface{" + strings.Join(parts, "; ") + "}"
	case *ast.BasicLit:
		return t.Value
	default:
		// Fallback to printed form, but strip parens via formatNode may keep them; use node text
		s := ctx.formatNode(e)
		// If it's not a type node we might be a generic type index etc.
		return s
	}
}

func fieldListTypeString(fl *ast.FieldList, ctx *checkerContext) string {
	if fl == nil {
		return ""
	}
	var parts []string
	for _, f := range fl.List {
		if len(f.Names) > 0 {
			parts = append(parts, namesString(f.Names)+" "+buildTypeStringV2(f.Type, ctx))
		} else {
			parts = append(parts, buildTypeStringV2(f.Type, ctx))
		}
	}
	return strings.Join(parts, ", ")
}
