	var out []warning
	// Build set of else-if ifs
	elseIfSet := map[*ast.IfStmt]bool{}
	walkFile(lf, func(n ast.Node) bool {
		if ifs, ok := n.(*ast.IfStmt); ok {
			cur := ifs
			for cur.Else != nil {
				if nxt, ok := cur.Else.(*ast.IfStmt); ok {
					elseIfSet[nxt] = true
					cur = nxt
				} else {
					break
				}
			}
		}
		return true
	})
	walkFile(lf, func(n ast.Node) bool {
		ifs, ok := n.(*ast.IfStmt)
		if !ok || elseIfSet[ifs] {
			return true
		}
		count := 0
		cur := ifs
		var base ast.Expr
		for cur != nil {
			has := false
			if cur.Init != nil {
				if as, ok := cur.Init.(*ast.AssignStmt); ok && len(as.Rhs) == 1 {
					if ta, ok := unparen(as.Rhs[0]).(*ast.TypeAssertExpr); ok {
						if base == nil {
							base = ta.X
							has = true
						} else if ctx.exprEq(ta.X, base) {
							has = true
						}
					}
				}
			}
			if !has {
				break
			}
			count++
			if cur.Else != nil {
				if nxt, ok := cur.Else.(*ast.IfStmt); ok {
					cur = nxt
					continue
				}
			}
			break
		}
		if count >= 2 {
			out = append(out, ctx.warn(ifs.Pos(), "rewrite if-else to type switch statement"))
		}
		return true
	})
