new2='''func checkUnlabelStmt(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	walkFile(lf, func(n ast.Node) bool {
		ls, ok := n.(*ast.LabeledStmt)
		if !ok {
			return true
		}
		// only labels on loop/switch/select statements
		switch ls.Stmt.(type) {
		case *ast.ForStmt, *ast.RangeStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
		default:
			return true
		}
		label := ls.Label.Name
		needed := false
		// Traverse labelled statement looking for branch uses of label that are inside a nested breakable construct
		var visit func(n ast.Node, nested bool)
		visit = func(n ast.Node, nested bool) {
			if n == nil || needed {
				return
			}
			// If this node is a nested breakable (and not the root labelled stmt), its children are nested
			childNested := nested
			if n != ls.Stmt {
				switch n.(type) {
				case *ast.ForStmt, *ast.RangeStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
					childNested = true
				}
			}
			if bs, ok := n.(*ast.BranchStmt); ok && bs.Label != nil && bs.Label.Name == label {
				if nested {
					needed = true
				}
				return
			}
			// Use ast.ChildNodes? No such: use Inspect on children manually via ast.Inspect with stack tracking is complex.
			// Fallback recursion using Inspect for children: we implement by iterating with ast.Inspect and tracking depth via a second pass below.
			_ = childNested
			// Direct children via Inspect that calls recursively - we instead do a manual stack below outside.
			_ = visit
		}
		_ = visit
		// Manual inspection: track nesting by walking with ast.Inspect and a stack of nodes
		// Compute depth: do a recursive traversal using ast.Inspect on each child? Simpler: use a stack approach with Inspect function that maintains count when entering/exiting is hard (Inspect provides nil callback on exit)
		nestedDepth := 0
		ast.Inspect(ls.Stmt, func(nn ast.Node) bool {
			if nn == nil {
				return true
			}
			// Detect if we are leaving? ast.Inspect calls with nil after children, but we can't easily map.
			// Instead determine for each branch node whether any ancestor (via parents) between branch and labelled stmt (exclusive) is a breakable construct.
			if bs, ok := nn.(*ast.BranchStmt); ok && bs.Label != nil && bs.Label.Name == label {
				// walk parents up to ls.Stmt
				cur := ast.Node(bs)
				for cur != nil && cur != ls.Stmt {
					par := ctx.parents[cur]
					if par == nil || par == ls {
						break
					}
					if par != ls.Stmt {
						switch par.(type) {
						case *ast.ForStmt, *ast.RangeStmt, *ast.SwitchStmt, *ast.TypeSwitchStmt, *ast.SelectStmt:
							needed = true
						}
					}
					cur = par
				}
			}
			_ = nestedDepth
			return true
		})
		if !needed {
			out = append(out, ctx.warn(ls.Pos(), "label %s is redundant", label))
		}
		return true
	})
	return out
