			return true
		}
		total := 0
		unnamed := 0
		candidates := 0
		var typesList []types.Type
		var isErrorList []bool
		var isBoolList []bool
		for _, f := range fd.Type.Results.List {
			typ := ctx.exprType(f.Type)
