				}
			} else {
				total += len(f.Names)
				for range f.Names {
					typesList = append(typesList, typ)
				}
			}
		}
		if unnamed == 0 || unnamed != total || total < 2 {
			return true
		}
		// Status pair idiom: (value, bool/error) exactly 2 results
		if total == 2 && len(isErrorList) == 2 {
			if (isErrorList[1] && !isErrorList[0]) || (isBoolList[1] && !isBoolList[0]) {
				return true
			}
		}
		if candidates >= 2 {
			out = append(out, ctx.warn(fd.Pos(), "consider giving a name to these results"))
		}
		_ = typesList
		return true
	})
	return out
}

func isNamedType(t types.Type, expr ast.Expr) bool {
	if t != nil {
		if _, ok := t.(*types.Named); ok {
			return true
		}
		return false
	}
	// No type info fallback: selector or ident that is not a basic type
	if _, ok := unparen(expr).(*ast.SelectorExpr); ok {
		return true
	}
	if id, ok := unparen(expr).(*ast.Ident); ok {
		switch id.Name {
		case "bool", "byte", "rune", "string", "int", "int8", "int16", "int32", "int64", "uint", "uint8", "uint16", "uint32", "uint64", "uintptr", "float32", "float64", "complex64", "complex128":
			return false
		default:
			return true
		}
	}
	return false
}

func isErrorTypeExpr(e ast.Expr) bool {
	id, ok := unparen(e).(*ast.Ident)
	return ok && id.Name == "error"
}

func isBoolTypeExpr(e ast.Expr) bool {
	id, ok := unparen(e).(*ast.Ident)
	return ok && id.Name == "bool"
}

