new='''func checkBadLock(ctx *checkerContext, lf *loadedFile) []warning {
	var lockOut []warning
	var rlockOut []warning
	processList := func(list []ast.Stmt) {
		for i := 0; i+1 < len(list); i++ {
			e1, ok1 := list[i].(*ast.ExprStmt)
			e2, ok2 := list[i+1].(*ast.ExprStmt)
			if !ok1 || !ok2 {
				continue
			}
			c1, ok1 := unparen(e1.X).(*ast.CallExpr)
			c2, ok2 := unparen(e2.X).(*ast.CallExpr)
			if !ok1 || !ok2 {
				continue
			}
			s1, ok1 := selectorOf(c1.Fun)
			s2, ok2 := selectorOf(c2.Fun)
			if !ok1 || !ok2 {
				continue
			}
			if s1.Sel.Name == "Lock" && s2.Sel.Name == "Unlock" && ctx.exprEq(s1.X, s2.X) {
				lockOut = append(lockOut, ctx.warn(c2.Pos(), "defer is missing, mutex is unlocked immediately"))
			}
			if s1.Sel.Name == "RLock" && s2.Sel.Name == "RUnlock" && ctx.exprEq(s1.X, s2.X) {
				rlockOut = append(rlockOut, ctx.warn(c2.Pos(), "defer is missing, mutex is unlocked immediately"))
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.BlockStmt:
			processList(v.List)
		case *ast.CaseClause:
			processList(v.Body)
		case *ast.CommClause:
			processList(v.Body)
		}
		return true
	})
	return append(lockOut, rlockOut...)
}

