			}
			if s1.Sel.Name == "Lock" && s2.Sel.Name == "Unlock" && ctx.exprEq(s1.X, s2.X) {
				g := getGroup(c1)
				g.locks = append(g.locks, ctx.warn(c2.Pos(), "defer is missing, mutex is unlocked immediately"))
			}
			if s1.Sel.Name == "RLock" && s2.Sel.Name == "RUnlock" && ctx.exprEq(s1.X, s2.X) {
				g := getGroup(c1)
				g.rlocks = append(g.rlocks, ctx.warn(c2.Pos(), "defer is missing, mutex is unlocked immediately"))
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.BlockStmt:
			processList(v.List)
		case *ast.CaseClause:
			processList(v.Body)
		case *ast.CommClause:
			processList(v.Body)
		}
		return true
	})
	// sort groups by function position
	for i := 0; i < len(groups); i++ {
		for j := i + 1; j < len(groups); j++ {
			if groups[j].pos < groups[i].pos {
				groups[i], groups[j] = groups[j], groups[i]
			}
		}
	}
	var out []warning
	for _, g := range groups {
		out = append(out, g.locks...)
		out = append(out, g.rlocks...)
	}
	return out
}

