		locks   []warning
		rlocks  []warning
	}
	var groups []*group
	byKey := map[ast.Node]*group{}
	getGroup := func(n ast.Node) *group {
		var fn ast.Node
		cur := n
		for cur != nil {
			par := ctx.parents[cur]
			if par == nil {
				break
			}
			if _, ok := par.(*ast.FuncDecl); ok {
				fn = par
				break
			}
			if _, ok := par.(*ast.FuncLit); ok {
				fn = par
				break
			}
			cur = par
		}
		key := fn
		if key == nil {
			key = n
		}
		if g, ok := byKey[key]; ok {
			return g
		}
		pos := token.Pos(0)
		if fn != nil {
			pos = fn.Pos()
		} else {
			pos = n.Pos()
		}
		g := &group{key: key, pos: pos}
		byKey[key] = g
		groups = append(groups, g)
		return g
	}
	processList := func(list []ast.Stmt) {
		for i := 0; i+1 < len(list); i++ {
			e1, ok1 := list[i].(*ast.ExprStmt)
			e2, ok2 := list[i+1].(*ast.ExprStmt)
			if !ok1 || !ok2 {
				continue
			}
			c1, ok1 := unparen(e1.X).(*ast.CallExpr)
			c2, ok2 := unparen(e2.X).(*ast.CallExpr)
			if !ok1 || !ok2 {
				continue
			}
			s1, ok1 := selectorOf(c1.Fun)
			s2, ok2 := selectorOf(c2.Fun)
			if !ok1 || !ok2 {
				continue
			}
			if s1.Sel.Name == "Lock" && s2.Sel.Name == "Unlock" && ctx.exprEq(s1.X, s2.X) {
				g := getGroup(c1)
				g.locks = append(g.locks, ctx.warn(c2.Pos(), "defer is missing, mutex is unlocked immediately"))
			}
			if s1.Sel.Name == "RLock" && s2.Sel.Name == "RUnlock" && ctx.exprEq(s1.X, s2.X) {
				g := getGroup(c1)
				g.rlocks = append(g.rlocks, ctx.warn(c2.Pos(), "defer is missing, mutex is unlocked immediately"))
			}
		}
	}
	walkFile(lf, func(n ast.Node) bool {
		switch v := n.(type) {
		case *ast.BlockStmt:
			processList(v.List)
		case *ast.CaseClause:
			processList(v.Body)
		case *ast.CommClause:
			processList(v.Body)
		}
		return true
	})
	// sort groups by function position
	for i := 0; i < len(groups); i++ {
		for j := i + 1; j < len(groups); j++ {
			if groups[j].pos < groups[i].pos {
				groups[i], groups[j] = groups[j], groups[i]
			}
		}
	}
	var out []warning
	for _, g := range groups {
		out = append(out, g.locks...)
		out = append(out, g.rlocks...)
	}
	return out
}

