{"command":"cat > boolexpr.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
)

func isBoolExprNode(n ast.Node) bool {
	switch v := n.(type) {
	case *ast.UnaryExpr:
		return v.Op == token.NOT
	case *ast.BinaryExpr:
		switch v.Op {
		case token.LAND, token.LOR, token.EQL, token.NEQ, token.LSS, token.GTR, token.LEQ, token.GEQ:
			return true
		}
	case *ast.ParenExpr:
		return isBoolExprNode(v.X)
	}
	return false
}

func checkBoolExprSimplifyV2(ctx *checkerContext, lf *loadedFile) []warning {
	var out []warning
	// Find candidates
	var candidates []ast.Node
	ast.Inspect(lf.AST, func(n ast.Node) bool {
		if n == nil || !isBoolExprNode(n) {
			return true
		}
		// Paren candidates are represented by their inner node for simplicity unless paren itself is a direct operand of NOT etc.
		if _, isParen := n.(*ast.ParenExpr); isParen {
			return true // let inner be handled; parent chain will see paren - but our candidate check below treats paren as blocker, so inner would be excluded. To handle, we don't add paren but we continue traversal.
		}
		// determine parent
		par := ctx.parents[n]
		// If parent is LAND/LOR/NOT/Paren, not a candidate (it's part of a larger combinator except comparison parents are allowed)
		switch par.(type) {
		case *ast.BinaryExpr:
			if b, ok := par.(*ast.BinaryExpr); ok && (b.Op == token.LAND || b.Op == token.LOR) {
				return true
			}
		case *ast.UnaryExpr:
			return true
		case *ast.ParenExpr:
			return true
		}
		candidates = append(candidates, n)
		return true
	})
	for _, cand := range candidates {
		// skip direct If/For condition candidates that are not LAND/LOR
		if par := ctx.parents[cand]; par != nil {
			isDirectCond := false
			if ifs, ok := par.(*ast.IfStmt); ok && ifs.Cond == cand {
				isDirectCond = true
			}
			if fs, ok := par.(*ast.ForStmt); ok && fs.Cond == cand {
				isDirectCond = true
			}
			if isDirectCond {
				if b, ok := cand.(*ast.BinaryExpr); !ok || (b.Op != token.LAND && b.Op != token.LOR) {
					continue
				}
			}
		}
		sug, changed := simplifyBoolExpr(ctx, cand)
		if !changed {
			continue
		}
		out = append(out, ctx.warn(cand.Pos(), "can simplify `%s` to `%s`", ctx.formatNode(cand), sug))
	}
	return out
}

// simplifyBoolExpr returns simplified text for a bool expression and whether it changed.
func simplifyBoolExpr(ctx *checkerContext, e ast.Node) (string, bool) {
	switch v := e.(type) {
	case *ast.ParenExpr:
		inner, changed := simplifyBoolExpr(ctx, v.X)
		if !changed {
			return ctx.formatNode(e), false
		}
		return "(" + inner + ")", true
	case *ast.UnaryExpr:
		if v.Op != token.NOT {
			return ctx.formatNode(e), false
		}
		inner := unparen(v.X)
		// double negation
		if iu, ok := inner.(*ast.UnaryExpr); ok && iu.Op == token.NOT {
			// simplify operand of inner NOT
			s, _ := simplifyBoolExpr(ctx, iu.X)
			return s, true
		}
		// negation of comparison
		if bin, ok := inner.(*ast.BinaryExpr); ok {
			var newOp token.Token
			switch bin.Op {
			case token.GEQ:
				newOp = token.LSS
			case token.GTR:
				newOp = token.LEQ
			case token.LEQ:
				newOp = token.GTR
			case token.LSS:
				newOp = token.GEQ
			case token.EQL:
				newOp = token.NEQ
			case token.NEQ:
				newOp = token.EQL
			default:
				// not a comparison: check inner simplification (e.g. !(ok && x>y-1) -> !(ok && x>=y))
				s, changed := simplifyBoolExpr(ctx, v.X)
				if changed {
					// s is simplified inner (without outer parens). Need to reconstruct !(...)
					// Use formatted unary with simplified text: we can return "!(" + s + ")" if inner was paren/binary
					// Determine: if v.X is Paren, simplify returns "(...)" - then "!" + that
					origInner, ch2 := simplifyBoolExpr(ctx, v.X)
					_ = s
					if ch2 {
						return "!" + origInner, true
					}
				}
				return ctx.formatNode(e), false
			}
			sug := ctx.formatNode(&ast.BinaryExpr{X: bin.X, Op: newOp, Y: bin.Y})
			return sug, true
		}
		// inner is LAND/LOR or other bool: simplify inner and wrap
		if s, changed := simplifyBoolExpr(ctx, v.X); changed {
			return "!" + s, true
		}
		return ctx.formatNode(e), false
	case *ast.BinaryExpr:
		// LAND / LOR
		if v.Op == token.LAND || v.Op == token.LOR {
			ls, lc := simplifyBoolExpr(ctx, v.X)
			rs, rc := simplifyBoolExpr(ctx, v.Y)
			if !lc && !rc {
				return ctx.formatNode(e), false
			}
			if !lc {
				ls = ctx.formatNode(v.X)
			}
			if !rc {
				rs = ctx.formatNode(v.Y)
			}
			return fmt.Sprintf("%s %s %s", ls, v.Op.String(), rs), true
		}
		// Comparisons
		// Negated equality: !(a) == !(b) -> (a) == (b)
		if v.Op == token.EQL {
			ux, ok1 := unparenKeep(v.X)
			uy, ok2 := unparenKeep(v.Y)
			_ = ux
			_ = uy
			// Check operands are Unary NOT (possibly through paren? original operands are !(x) where x is paren, NOT is at top of operand (unparen gives NOT? !(x) parsed as Unary with X=Paren)
			getNot := func(e ast.Expr) (*ast.UnaryExpr, bool) {
				if u, ok := unparen(e).(*ast.UnaryExpr); ok && u.Op == token.NOT {
					// But unparen removes paren around NOT? !(x) is not paren, just NOT.
					// If e is Paren containing NOT, unparen will give NOT.
					return u, true
				}
				if u, ok := e.(*ast.UnaryExpr); ok && u.Op == token.NOT {
					return u, true
				}
				return nil, false
			}
			if n1, ok1 := getNot(v.X); ok1 {
				if n2, ok2 := getNot(v.Y); ok2 {
					sug := fmt.Sprintf("%s %s %s", ctx.formatNode(n1.X), v.Op.String(), ctx.formatNode(n2.X))
					return sug, true
				}
			}
		}
		// Arithmetic offset rule
		if v.Op == token.GTR || v.Op == token.GEQ || v.Op == token.LSS || v.Op == token.LEQ {
			if sug, ok := simplifyArithCmp(ctx, v); ok {
				return sug, true
			}
		}
		// For comparison with bool operands, do not simplify operands here (they are separate candidates)
		return ctx.formatNode(e), false
	}
	// leaf
	if expr, ok := e.(ast.Expr); ok {
		return ctx.formatNode(expr), false
	}
	return ctx.formatNode(e), false
}

// unparenKeep is just unparen (named for clarity)
func unparenKeep(e ast.Expr) (ast.Expr, bool) {
	u := unparen(e)
	return u, u != nil
}

func simplifyArithCmp(ctx *checkerContext, bin *ast.BinaryExpr) (string, bool) {
	getOffset := func(e ast.Expr) (ast.Expr, int) {
		if b, ok := unparen(e).(*ast.BinaryExpr); ok && (b.Op == token.ADD || b.Op == token.SUB) {
			if val, ok := constIntValue(b.Y); ok && val == 1 {
				if b.Op == token.ADD {
					return b.X, 1
				}
				return b.X, -1
			}
		}
		return e, 0
	}
	lbase, loff := getOffset(bin.X)
	rbase, roff := getOffset(bin.Y)
	if (loff == 0 && roff == 0) || (loff != 0 && roff != 0) {
		return "", false
	}
	d := loff - roff
	var newOp token.Token
	droppable := false
	switch bin.Op {
	case token.GTR:
		if d == 1 {
			newOp = token.GEQ
			droppable = true
		}
	case token.LEQ:
		if d == 1 {
			newOp = token.LSS
			droppable = true
		}
	case token.GEQ:
		if d == -1 {
			newOp = token.GTR
			droppable = true
		}
	case token.LSS:
		if d == -1 {
			newOp = token.LEQ
			droppable = true
		}
	}
	if !droppable {
		return "", false
	}
	return ctx.formatNode(&ast.BinaryExpr{X: lbase, Op: newOp, Y: rbase}), true
}
