{"command":"cat > ruleguard_init_impl.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

func (st *ruleguardState) loadRuleguardRules() {
	if paramRuleguardRules == "" {
		return
	}
	// Validate failOn
	failOnSet := map[string]bool{}
	if paramRuleguardFailOn != "" {
		for _, tok := range strings.Split(paramRuleguardFailOn, ",") {
			if tok != "dsl" && tok != "import" && tok != "all" {
				msg := fmt.Sprintf("'failOnError' flag '%s' is invalid. It must be a comma-separated list and supported values are 'dsl,import,all'", paramRuleguardFailOn)
				fmt.Fprintf(os.Stderr, "\tdebug: ruleguard: initialization failure: ruleguard init error: %s\n", msg)
				fmt.Fprintf(os.Stderr, "init checkers: ruleguard init error: %s\n", msg)
				os.Exit(1)
			}
			failOnSet[tok] = true
		}
	}
	fatal := paramRuleguardFailOnError || failOnSet["all"] || failOnSet["dsl"]
	patterns := strings.Split(paramRuleguardRules, ",")
	for _, pat := range patterns {
		matches, _ := filepath.Glob(pat)
		if len(matches) == 0 {
			msg := fmt.Sprintf("no file matching '%s'", pat)
			fmt.Fprintf(os.Stderr, "\tdebug: ruleguard: initialization failure: ruleguard init error: %s\n", msg)
			fmt.Fprintf(os.Stderr, "init checkers: ruleguard init error: %s\n", msg)
			os.Exit(1)
		}
		st.rawFiles = append(st.rawFiles, matches...)
		for _, f := range matches {
			loadErr := st.tryLoadRuleFile(f)
			if loadErr != "" {
				if fatal {
					fmt.Fprintf(os.Stderr, "\tdebug: ruleguard: initialization failure: ruleguard init error: %s\n", loadErr)
					fmt.Fprintf(os.Stderr, "init checkers: ruleguard init error: %s\n", loadErr)
					os.Exit(1)
				}
				fmt.Fprintf(os.Stderr, "ruleguard init error, skip %s: %s\n", f, loadErr)
				continue
			}
		}
	}
	if len(st.rules) == 0 {
		st.emptyAfterLoad = true
	}
}

func (st *ruleguardState) tryLoadRuleFile(f string) string {
	data, err := os.ReadFile(f)
	if err != nil {
		return err.Error()
	}
	fset := token.NewFileSet()
	parsed, err := parser.ParseFile(fset, f, data, parser.ParseComments)
	if err != nil {
		// Format similar to typechecker errors is unknown; return the raw parse error string
		return err.Error()
	}
	// Check imports existence in GOROOT/GOPATH src
	_ = parsed
	for _, imp := range parsed.Imports {
		path, _ := strconv.Unquote(imp.Path.Value)
		if !importPackageExists(path) {
			pos := fset.Position(imp.Path.Pos())
			gorootLine := "\t($GOROOT not set)"
			if gr := os.Getenv("GOROOT"); gr != "" {
				gorootLine = fmt.Sprintf("\t%s (from $GOROOT)", filepath.Join(gr, "src", path))
			}
			gopath := os.Getenv("GOPATH")
			if gopath == "" {
				if home, err := os.UserHomeDir(); err == nil {
					gopath = filepath.Join(home, "go")
				}
			} else {
				// importer messages list each GOPATH entry? Use first entry
				parts := filepath.SplitList(gopath)
				if len(parts) > 0 {
					gopath = parts[0]
				}
			}
			gopathLine := fmt.Sprintf("\t%s (from $GOPATH)", filepath.Join(gopath, "src", path))
			return fmt.Sprintf("typechecker error: %s:%d:%d: could not import %s (can't find import: %q: cannot find package %q in any of:\n%s\n%s)", f, pos.Line, pos.Column, path, path, path, gorootLine, gopathLine)
		}
	}
	rules := parseGoruleText(string(data), f)
	st.rules = append(st.rules, rules...)
	_ = ast.NewIdent
	return ""
